INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "画家是会画画，而且常常画画的人。", "primary_collocate": null, "pronunciation": "huà jiā", "ipa": "xua⁵¹ tɕia⁵⁵", "syllable_count": 2, "sentences": [{"text": "我的邻居是一位画家，他每天都在画画。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家常常去公园，画花和树。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小爱画画，长大后想当画家。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用红色和黄色画了一幅秋天的画。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老画家每天早上都坐在河边画画。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想送我的画家朋友一盒好颜料。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家走到街上，看见一座老房子，马上画了下来。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这个画家在山里住了十年，画了很多山。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女画家很喜欢画小动物。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家的房间里，到处都是画笔和颜色。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "女画家", "label": "复合词"}, {"form": "画家村", "label": "复合词"}, {"form": "畫家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会画画并且常常画画的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89da991-ce23-4a2a-800d-16d17cb3d807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "画家", "is_correct": true, "explanation": "画家：会画画并且常常画画的人。"}, {"text": "画架", "is_correct": false, "explanation": "huàjià（第四声）与 huàjiā（第一声）第二个音节声调不同，意思是画画用的支架。"}, {"text": "花架", "is_correct": false, "explanation": "huājià 与 huàjiā 第一个音节声调不同（第一声与第四声），第二个音节声调也不同，意思是供花草攀爬的架子。"}, {"text": "花甲", "is_correct": false, "explanation": "huājiǎ 与 huàjiā 声母韵母相同，只是声调不同（第一声/第四声，第三声/第一声），意思是六十岁。"}], "explanations": {"画家": "画家：会画画并且常常画画的人。", "画架": "huàjià（第四声）与 huàjiā（第一声）第二个音节声调不同，意思是画画用的支架。", "花架": "huājià 与 huàjiā 第一个音节声调不同（第一声与第四声），第二个音节声调也不同，意思是供花草攀爬的架子。", "花甲": "huājiǎ 与 huàjiā 声母韵母相同，只是声调不同（第一声/第四声，第三声/第一声），意思是六十岁。"}, "sentence_index": null, "correct_answer": "画家"}, "level_3": {"options": [{"text": "画家", "is_correct": true, "explanation": "画家：会画画并且常常画画的人，与“每天都在画画”一致。"}, {"text": "盲人", "is_correct": false, "explanation": "语义：盲人看不见，与“每天都在画画”矛盾。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是偷东西的人，与“邻居每天画画”的描写不合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，与“每天都在画画”的描写不符。"}], "explanations": {"画家": "画家：会画画并且常常画画的人，与“每天都在画画”一致。", "盲人": "语义：盲人看不见，与“每天都在画画”矛盾。", "小偷": "语义：小偷是偷东西的人，与“邻居每天画画”的描写不合。", "厨师": "语义：厨师的工作是做饭，与“每天都在画画”的描写不符。"}, "sentence_index": 0, "correct_answer": "画家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我忘了带画家，只能用铅笔画画。", "explanation": "这里应该用〈颜料〉。画家指人，不能当工具带着，没有颜料才只能用铅笔画。"}, {"text": "这幅画家很有名，很多人去看。", "explanation": "这里应该用〈画〉。“画家”指画画的人，说作品要用“画”，这里说的是作品。"}, {"text": "我们周末去画家看书。", "explanation": "这里应该用〈图书馆〉。画家指人，不是看书的地方，看书要去〈图书馆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "画家", "is_correct": true, "explanation": "画家：看见老房子后用画画把它记录下来，与“画了下来”一致。"}, {"text": "摄影师", "is_correct": false, "explanation": "语义：摄影师用相机拍照，不会“画了下来”。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家用文字写作，不会把老房子“画了下来”。"}, {"text": "教练", "is_correct": false, "explanation": "语义：教练的工作是指导训练，与“画了下来”的动作不符。"}], "explanations": {"画家": "画家：看见老房子后用画画把它记录下来，与“画了下来”一致。", "摄影师": "语义：摄影师用相机拍照，不会“画了下来”。", "作家": "语义：作家用文字写作，不会把老房子“画了下来”。", "教练": "语义：教练的工作是指导训练，与“画了下来”的动作不符。"}, "sentence_index": 6, "correct_answer": "画家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸每天都在厨房里用画家做饭。", "explanation": "这里应该用〈锅〉。画家指人，不能当炊具，做饭要用〈锅〉。"}, {"text": "他用一支画家，画出了很美的山。", "explanation": "这里应该用〈画笔〉。“画家”是人，不能当工具，画画用的工具是“画笔”。"}, {"text": "我的画家挂在美术馆里，很多人去看。", "explanation": "这里应该用〈作品〉。“画家”指人，挂在美术馆里的是作品，要用“作品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐是一只画家，她画得很好。", "corrected_sentence": "我姐姐是一位画家，她画得很好。", "error_description": "量词“只”多用于动物，不用于数人。指人的画家应用量词“位”（或“个”），说“一位画家”，不能说“一只画家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当了五年画家们，后来改教书。", "corrected_sentence": "她当了五年画家，后来改教书。", "error_description": "“们”表示复数，指一个人时不能用“画家们”，应说“画家”，即“当了五年画家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
