INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以绘画为职业或擅长绘画的人。", "primary_collocate": null, "pronunciation": "huà jiā", "ipa": "xua⁵¹ tɕia⁵⁵", "syllable_count": 2, "sentences": [{"text": "他是一位有名的画家，画卖得很好。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠卖画生活，是个真正的画家。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家的画在世界上很有名。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多画家在这里开过画展。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是画家，但画得比画家还好。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家的作品在美术馆里放着，很多人去看。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位画家，工作就是画画和教学生。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个画家画马画得特别好，画里的马像活的。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位画家的画一张卖了十万块。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是画家，他的画室在城东。", "target_word": "画家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "女画家", "label": "复合词"}, {"form": "画家村", "label": "复合词"}, {"form": "畫家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以绘画为职业或绘画水平很高的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89da991-ce23-4a2a-800d-16d17cb3d807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
