INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "画家", "is_correct": true, "explanation": "画家：以绘画为职业的人，与“工作就是画画”一致。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家以写作为业，不是画画，与“工作就是画画和教学生”不符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生的工作是看病治疗，与“画画”不符。"}, {"text": "乘客", "is_correct": false, "explanation": "配价：“乘客”是搭乘交通工具的人，不能作为“工作就是画画和教学生”的身份。"}], "explanations": {"画家": "画家：以绘画为职业的人，与“工作就是画画”一致。", "作家": "语义：作家以写作为业，不是画画，与“工作就是画画和教学生”不符。", "医生": "语义：医生的工作是看病治疗，与“画画”不符。", "乘客": "配价：“乘客”是搭乘交通工具的人，不能作为“工作就是画画和教学生”的身份。"}, "sentence_index": 6, "correct_answer": "画家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了很多画家。", "explanation": "这里应该用〈颜料〉。“画家”指人，买的是画材，应说〈颜料〉。"}, {"text": "他把一个画家放在桌上。", "explanation": "这里应该用〈花瓶〉。画家指人，不能像东西一样放在桌上，放在桌上的应是〈花瓶〉。"}, {"text": "展厅里挂满了画家。", "explanation": "这里应该用〈画〉。“画家”指人，挂在墙上的是作品，要用“画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只有名的画家，画卖得很贵。", "corrected_sentence": "他是一位有名的画家，画卖得很贵。", "error_description": "量词“只”多用于动物，不用于数人。指人的画家应用量词“位”（或“个”），说“一位画家”，不能说“一只画家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当了五年画家们，后来改教书。", "corrected_sentence": "她当了五年画家，后来改教书。", "error_description": "“们”表示复数，指一个人时不能用“画家们”，应说“画家”，即“当了五年画家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
