INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94302, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示确实、的确，用以肯定事实。", "primary_collocate": null, "pronunciation": "zhēn gè", "ipa": "ʈʂən˥ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这件事真个不容易。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他真个来了，我没想到。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜真个不错。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的话，我真个信了。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说的真个没错。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年冬天真个比去年冷。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他真个忘了我们的约定。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山真个陡，我们爬了半天。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我真个没有骗你。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了这本书，我真个明白了不少。", "target_word": "真个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "旧白话", "sense_fingerprint": "确实、的确，肯定事实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1474bb06-a515-4e29-a498-439a526494f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真个", "is_correct": true, "explanation": "“真个”是副词，表示确实，用在“不容易”前，强调事情属实。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，不能说明“不容易”这一状态。"}, {"text": "拼命", "is_correct": false, "explanation": "搭配：“拼命”只修饰用力的动作，不能修饰“不容易”。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“不容易”描述的长期状况不合。"}], "explanations": {"真个": "“真个”是副词，表示确实，用在“不容易”前，强调事情属实。", "偶尔": "语义：“偶尔”表示有时候，不能说明“不容易”这一状态。", "拼命": "搭配：“拼命”只修饰用力的动作，不能修饰“不容易”。", "立刻": "语义：“立刻”表示马上发生，与“不容易”描述的长期状况不合。"}, "sentence_index": 0, "correct_answer": "真个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你说的话，我信真个了。", "explanation": "〈真个〉是副词，须放在谓语之前，不能放在句末。"}, {"text": "他来真个了，我没想到。", "explanation": "〈真个〉是副词，须放在谓语之前，不能放在句末。"}, {"text": "这家店的菜不错真个。", "explanation": "〈真个〉是副词，须放在所修饰的形容词之前，不能放在句末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真个", "is_correct": true, "explanation": "“真个”是副词，表示确实，修饰动词“忘了”，强调事情属实。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一直没有，与“忘了”这一已经发生的事相矛盾。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”用于叮嘱或劝阻，不能用来陈述已经发生的事。"}, {"text": "深深", "is_correct": false, "explanation": "搭配：“深深”修饰感情类动词，不能修饰“忘”这样的动作。"}], "explanations": {"真个": "“真个”是副词，表示确实，修饰动词“忘了”，强调事情属实。", "从来": "语义：“从来”表示一直没有，与“忘了”这一已经发生的事相矛盾。", "千万": "语义：“千万”用于叮嘱或劝阻，不能用来陈述已经发生的事。", "深深": "搭配：“深深”修饰感情类动词，不能修饰“忘”这样的动作。"}, "sentence_index": 6, "correct_answer": "真个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "看了这本书，我明白真个了不少。", "explanation": "〈真个〉是副词，须放在谓语之前，不能放在“明白”之后。"}, {"text": "看了这本书，我明白了不少真个。", "explanation": "〈真个〉是副词，须放在谓语之前，不能放在句末。"}, {"text": "看了这本书，真个我明白了不少。", "explanation": "〈真个〉是副词，须在主语之后，不能放在主语“我”之前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试真个的难，大家都没考好。", "corrected_sentence": "这次考试真个难，大家都没考好。", "error_description": "“真个”是副词，后面直接接形容词“难”，中间不能加“的”，应说“真个难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山真个的高，我们爬了半天。", "corrected_sentence": "这座山真个高，我们爬了半天。", "error_description": "“真个”是副词，后面直接接形容词，中间不能加“的”，应说“真个高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ed130b-2aba-4a6e-b4b9-e893077cc540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
