INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94303, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "称呼是叫一个人时用的名字。", "primary_collocate": null, "pronunciation": "chēng hu", "ipa": "ʈʂʰɤŋ˥ xu", "syllable_count": 2, "sentences": [{"text": "对老人，这个称呼很有礼貌。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“阿姨”是对年纪大的女士的称呼。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢别人用这个称呼叫他。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给他起了一个有意思的称呼。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中文里，每个家人都有不同的称呼。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师这个称呼让他很高兴。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王，你换一个称呼吧，我听着不习惯。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见到客人，要用礼貌的称呼。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对爸爸的哥哥有一个特别的称呼。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个称呼太正式了，我们是朋友。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个称呼", "label": "量词"}], "register": "中性", "sense_fingerprint": "称呼：当面叫人时用的名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94303, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称呼", "is_correct": true, "explanation": "此处指叫人时用的名字，“很有礼貌”修饰它，符合语境。"}, {"text": "发型", "is_correct": false, "explanation": "语义：发型是头发的样式，不能说有礼貌。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“礼貌”来形容，句子不通。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，不能用“礼貌”来形容，句子不通。"}], "explanations": {"称呼": "此处指叫人时用的名字，“很有礼貌”修饰它，符合语境。", "发型": "语义：发型是头发的样式，不能说有礼貌。", "天气": "语义：天气不能用“礼貌”来形容，句子不通。", "电视": "语义：电视是电器，不能用“礼貌”来形容，句子不通。"}, "sentence_index": 0, "correct_answer": "称呼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把荣誉的称呼戴在了胸前。", "explanation": "这里应该用〈奖章〉。称呼是叫人的名字，不能像奖章一样戴在胸前。"}, {"text": "朋友给他起了一条有意思的称呼。", "explanation": "这里应该用〈个〉。称呼是抽象的名字，不用“条”；“条”用于细长的东西。"}, {"text": "妈妈把我的称呼放进了冰箱里。", "explanation": "这里是搭配错误：称呼是叫人用的说法，抽象无形，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称呼", "is_correct": true, "explanation": "此处指叫人的名称，“换一个……我听着不习惯”说的是对叫法的不习惯，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是叫人的名称，换颜色无法说“听着不习惯”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“听”不搭配“味道”，说听味道不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能“听着”，也不是叫人的名称。"}], "explanations": {"称呼": "此处指叫人的名称，“换一个……我听着不习惯”说的是对叫法的不习惯，符合语境。", "颜色": "语义：颜色不是叫人的名称，换颜色无法说“听着不习惯”。", "味道": "搭配：“听”不搭配“味道”，说听味道不通。", "桌子": "语义：桌子是家具，不能“听着”，也不是叫人的名称。"}, "sentence_index": 6, "correct_answer": "称呼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他评上了高级称呼。", "explanation": "这里应该用〈职称〉。称呼是叫人的名字，专业技术等级要用“职称”。"}, {"text": "大家对他的工作给予了很高的称呼。", "explanation": "这里应该用〈赞誉〉。称呼只是叫人用的名字，不能表示对工作的评价。"}, {"text": "这块地的称呼有五亩。", "explanation": "这里应该用〈面积〉。称呼是叫人的名字，不能用来表示大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友给我起了一只新称呼。", "corrected_sentence": "朋友给我起了一个新称呼。", "error_description": "量词错误：称呼的量词是“个”，应说“一个新称呼”，不能说“一只”；“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用了一道亲切的称呼。", "corrected_sentence": "她用了一个亲切的称呼。", "error_description": "量词错误：称呼的量词是“个”，“道”多用于门、题、光等，不能用于称呼。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
