INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用某个名称叫（人）；以某种名称相称。", "primary_collocate": null, "pronunciation": "chēng hu", "ipa": "ʈʂʰɤŋ˥ xu", "syllable_count": 2, "sentences": [{"text": "我应该怎么称呼您？", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们都称呼他王老师。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公司里，大家称呼经理为李总。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她让我称呼她小林就可以。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子应该称呼爸爸的哥哥为伯伯。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么称呼这位客人？", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，人们常常称呼不认识的女士为阿姨。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比我大，我称呼他哥哥。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都亲切地称呼她张奶奶。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以直接称呼我老王。", "target_word": "称呼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "称呼了", "label": "体标"}, {"form": "称呼过", "label": "体标"}], "register": "中性", "sense_fingerprint": "称呼：用某个名称叫人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称呼", "is_correct": true, "explanation": "此处指用某个名称叫人，符合“我应该怎么……您”的语境。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语是车辆，不能接人作宾语。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”的对象是物体，不能用于人。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：“清洁”表示使干净，不能用来指对人的叫法，句子不通。"}], "explanations": {"称呼": "此处指用某个名称叫人，符合“我应该怎么……您”的语境。", "驾驶": "配价：“驾驶”的宾语是车辆，不能接人作宾语。", "搬运": "配价：“搬运”的对象是物体，不能用于人。", "清洁": "语义：“清洁”表示使干净，不能用来指对人的叫法，句子不通。"}, "sentence_index": 0, "correct_answer": "称呼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中称呼了一块金牌。", "explanation": "这里应该用〈获得〉。称呼只能用于叫人，不能表示得到奖牌。"}, {"text": "我每天早上称呼一下体重。", "explanation": "这里是“称量”的意思，与“用名称叫人”的称呼不同，称呼没有称量的意思。"}, {"text": "他站在路边，大声称呼出租车。", "explanation": "这里应该用〈叫〉。称呼只用于人，表示用名称叫，不能用于招呼出租车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称呼", "is_correct": true, "explanation": "此处表示人们用“阿姨”叫不认识的女士，符合语境。"}, {"text": "分析", "is_correct": false, "explanation": "配价：“分析”的对象是事情或问题，不能接“为阿姨”。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”不能与“为阿姨”搭配，说打扮女士为阿姨不通。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是指出缺点，不能用来指对女士的叫法。"}], "explanations": {"称呼": "此处表示人们用“阿姨”叫不认识的女士，符合语境。", "分析": "配价：“分析”的对象是事情或问题，不能接“为阿姨”。", "打扮": "搭配：“打扮”不能与“为阿姨”搭配，说打扮女士为阿姨不通。", "批评": "语义：批评是指出缺点，不能用来指对女士的叫法。"}, "sentence_index": 6, "correct_answer": "称呼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我的手机称呼了一次，我没听见。", "explanation": "这里应该用〈打〉。称呼用于叫人，不能用来指给手机打电话。"}, {"text": "他在日记里称呼了这件事。", "explanation": "这里应该用〈记录〉。称呼只能用于人，不能用来记下事情。"}, {"text": "他称呼了一道难题，结果做出来了。", "explanation": "这里应该用〈解答〉。称呼只能用于叫人，不能用于题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前称呼他过王老师。", "corrected_sentence": "我以前称呼过他王老师。", "error_description": "体标位置错误：“过”应紧跟动词“称呼”，说“称呼过他”，不能说“称呼他过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都很亲切的称呼他李叔叔。", "corrected_sentence": "我们都很亲切地称呼他李叔叔。", "error_description": "结构助词错误：修饰动词“称呼”的状语后要用“地”，应说“亲切地称呼”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
