INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94305, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空军是在天上开飞机保护国家的军人。", "primary_collocate": null, "pronunciation": "kōng jūn", "ipa": "kʰʊŋ˥˥ tɕyn˥˥", "syllable_count": 2, "sentences": [{"text": "他是一名空军，每天开飞机。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸年轻时是空军。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位空军穿着蓝色的制服。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军叔叔带我们看了飞机。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位空军飞过很多地方。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大后想当空军。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔是空军，在天上保护着我们的国家。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是空军，不是海军。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个空军很年轻，也很勇敢。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位空军，他会开飞机。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "空軍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开飞机保卫国家的军人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b63a56-8ab2-40e1-be94-f37f7483128e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空军", "is_correct": true, "explanation": "“空军”指开飞机保卫国家的军人，与“一名”和“开飞机”都相符。"}, {"text": "空姐", "is_correct": false, "explanation": "语义：“空姐”是机上服务人员，不开飞机，与句中“每天开飞机”矛盾。"}, {"text": "空调", "is_correct": false, "explanation": "语义：“空调”是家电，不是人，不能用“一名”来量，也不能开飞机。"}, {"text": "空间", "is_correct": false, "explanation": "语义：“空间”指范围或场所，不是人，与“每天开飞机”不搭。"}], "explanations": {"空军": "“空军”指开飞机保卫国家的军人，与“一名”和“开飞机”都相符。", "空姐": "语义：“空姐”是机上服务人员，不开飞机，与句中“每天开飞机”矛盾。", "空调": "语义：“空调”是家电，不是人，不能用“一名”来量，也不能开飞机。", "空间": "语义：“空间”指范围或场所，不是人，与“每天开飞机”不搭。"}, "sentence_index": 0, "correct_answer": "空军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位空军每天在音乐厅里弹钢琴。", "explanation": "此处应该用〈钢琴家〉。“空军”指军人，不指弹钢琴的音乐家，与句意不符。"}, {"text": "这位空军很热情，给乘客端茶。", "explanation": "此处应该用〈空姐〉。“空军”指军人，不指在飞机上服务的乘务员。"}, {"text": "这位空军每天在菜市场卖菜。", "explanation": "此处应该用〈菜贩〉。“空军”指军人，与卖菜的职业不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空军", "is_correct": true, "explanation": "“空军”指保卫国家的军人，与“是”和“在天上保护国家”相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是人，不能“在天上保护国家”。"}, {"text": "空中", "is_correct": false, "explanation": "搭配：“空中”是处所词，不能用在“是”后作身份名词。"}, {"text": "空袭", "is_correct": false, "explanation": "语义：“空袭”指从空中攻击，与句中“保护”的意思相反。"}], "explanations": {"空军": "“空军”指保卫国家的军人，与“是”和“在天上保护国家”相符。", "空气": "语义：“空气”不是人，不能“在天上保护国家”。", "空中": "搭配：“空中”是处所词，不能用在“是”后作身份名词。", "空袭": "语义：“空袭”指从空中攻击，与句中“保护”的意思相反。"}, "sentence_index": 6, "correct_answer": "空军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我认识一位空军，她每天在医院给病人看病。", "explanation": "此处应该用〈医生〉。“空军”指开飞机的军人，在医院给病人看病的是医生。"}, {"text": "我认识一位空军，她会在飞机上给乘客端茶。", "explanation": "此处应该用〈空姐〉。“空军”指军人，不指在飞机上服务的乘务员。"}, {"text": "我认识一位空军，他每天在学校给学生上课。", "explanation": "此处应该用〈老师〉。“空军”指开飞机的军人，在学校给学生上课的是老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他父亲是一只空军，常年在外。", "corrected_sentence": "他父亲是一名空军，常年在外。", "error_description": "错误形式：“一只空军”；正确形式：“一名空军”。“只”用于动物，指人应用量词“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表哥是的空军，常在天上飞。", "corrected_sentence": "我表哥是空军，常在天上飞。", "error_description": "错误形式：“是的空军”，“的”位置错误；正确形式：“是空军”，名词直接作“是”的表语，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
