INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主要在空中作战的军种。", "primary_collocate": null, "pronunciation": "kōng jūn", "ipa": "kʰʊŋ˥˥ tɕyn˥˥", "syllable_count": 2, "sentences": [{"text": "中国空军有很多新飞机。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在空军工作了十年。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陆军、海军和空军都很重要。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军今天举行了大型表演。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机场是空军的基地。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军需要很多会开飞机的人。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家买了新飞机给空军。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军和海军一起参加了演习。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哥哥想加入空军。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军的飞机在天上飞。", "target_word": "空军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "空軍", "label": "繁体"}, {"form": "空军基地", "label": "复合"}, {"form": "空军部队", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队中以飞机在空中作战的军种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b63a56-8ab2-40e1-be94-f37f7483128e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空军", "is_correct": true, "explanation": "“空军”是军种名称，可以作“中国”的定语中心语，说明中国的哪一个军种有新飞机。"}, {"text": "空调", "is_correct": false, "explanation": "语义：“空调”是家用电器，不是军队，不能说“中国空调有很多新飞机”。"}, {"text": "空间", "is_correct": false, "explanation": "语义：“空间”指范围或场所，不是军队，与“有很多新飞机”不搭。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能与“有很多新飞机”搭配，不能指一个拥有飞机的机构。"}], "explanations": {"空军": "“空军”是军种名称，可以作“中国”的定语中心语，说明中国的哪一个军种有新飞机。", "空调": "语义：“空调”是家用电器，不是军队，不能说“中国空调有很多新飞机”。", "空间": "语义：“空间”指范围或场所，不是军队，与“有很多新飞机”不搭。", "空气": "搭配：“空气”不能与“有很多新飞机”搭配，不能指一个拥有飞机的机构。"}, "sentence_index": 0, "correct_answer": "空军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用空军切菜。", "explanation": "此处应该用〈菜刀〉。「空军」指军种，不是工具，不能用来切菜。"}, {"text": "小鸟在空军飞。", "explanation": "此处应该用〈空中〉。“空军”指军种，不是空间，不能表示小鸟飞翔的地方。"}, {"text": "我想坐空军去上海。", "explanation": "此处应该用〈飞机〉。“空军”是军队，不是交通工具，不能用来表示乘坐的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空军", "is_correct": true, "explanation": "“空军”是军种名称，作“给”的宾语，说明买飞机是给哪个军种。"}, {"text": "空缺", "is_correct": false, "explanation": "语义：“空缺”指缺少的职位或位置，不能接受飞机。"}, {"text": "空中", "is_correct": false, "explanation": "搭配：“空中”是处所词，不能作“给”的受事对象，不能说“买飞机给空中”。"}, {"text": "空姐", "is_correct": false, "explanation": "语义：“空姐”指机上服务人员，不是军队，买新飞机不会给她。"}], "explanations": {"空军": "“空军”是军种名称，作“给”的宾语，说明买飞机是给哪个军种。", "空缺": "语义：“空缺”指缺少的职位或位置，不能接受飞机。", "空中": "搭配：“空中”是处所词，不能作“给”的受事对象，不能说“买飞机给空中”。", "空姐": "语义：“空姐”指机上服务人员，不是军队，买新飞机不会给她。"}, "sentence_index": 6, "correct_answer": "空军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支空军在草原上放牧牛羊。", "explanation": "此处应该用〈牧民〉。“空军”指军种，不指从事放牧的人，与句意不符。"}, {"text": "爸爸开着空军去海上打鱼。", "explanation": "此处应该用〈渔船〉。“空军”指军种，不是船，不能开去打鱼。"}, {"text": "这块空军很重。", "explanation": "此处应该用〈石头〉。「空军」指军种，不是物体，不能用「块」来量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只空军很厉害。", "corrected_sentence": "这支空军很厉害。", "error_description": "错误形式：“这只空军”；正确形式：“这支空军”。“只”用于动物，指军队作为队伍时应用量词“支”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这架飞机是空军地。", "corrected_sentence": "这架飞机是空军的。", "error_description": "错误形式：“空军地”，“地”用于修饰动词，不能表示所属；正确形式：“空军的”，“的”表示所属关系。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
