INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94307, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "签名是用笔把自己的名字写在纸上。", "primary_collocate": null, "pronunciation": "qiān míng", "ipa": "tɕʰjɛn⁵⁵ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "请你在这张纸的下面签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，在合同上签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办银行卡的时候，要在表上签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，考试前要在名单上签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了带笔，没办法签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先看一下这张纸，没问题就签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在收据上签名，然后给了我。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签名以后，这份文件就有用了。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用蓝色的笔在信的最后签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来开会的人都要先在本子上签名。", "target_word": "签名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "签了名", "label": "完成体"}, {"form": "签过名", "label": "经历体"}, {"form": "签个名", "label": "离合形式"}], "register": "中性", "sense_fingerprint": "用笔把自己的名字写在纸上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b63a56-8ab2-40e1-be94-f37f7483128e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：在纸的下面唱歌与“签字”的场景不符，句意不通。"}, {"text": "签名", "is_correct": true, "explanation": "正确。请对方在纸的下面写上名字，就是签名。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“在纸的下面”不能睡觉，句子在意义上不合理。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“在纸的下面”后面不与“吃饭”搭配。"}], "explanations": {"唱歌": "语义：在纸的下面唱歌与“签字”的场景不符，句意不通。", "签名": "正确。请对方在纸的下面写上名字，就是签名。", "睡觉": "语义：“在纸的下面”不能睡觉，句子在意义上不合理。", "吃饭": "搭配：“在纸的下面”后面不与“吃饭”搭配。"}, "sentence_index": 0, "correct_answer": "签名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上在公园里签名，身体越来越好。", "explanation": "这里应该用〈跑步〉。在公园锻炼身体要说跑步，签名是用笔把自己的名字写在纸上，不能锻炼身体。"}, {"text": "我每天给花签名，让它长得更好。", "explanation": "这里应该用〈浇〉。签名指写下名字，给花补充水分要用〈浇〉。"}, {"text": "我用湿布在窗户上签名。", "explanation": "这里应该用〈擦〉。用湿布处理窗户要说〈擦〉，签名不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "签名", "is_correct": true, "explanation": "正确。收据上需要本人写下名字，然后交给对方，就是签名。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“在收据上”后面不能接“跑步”，人不能在纸上跑步。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：收据是纸，不能在上面洗澡，句子的场景不成立。"}, {"text": "看书", "is_correct": false, "explanation": "搭配：“在收据上”不能与“看书”搭配，句子在意义上说不通。"}], "explanations": {"签名": "正确。收据上需要本人写下名字，然后交给对方，就是签名。", "跑步": "搭配：“在收据上”后面不能接“跑步”，人不能在纸上跑步。", "洗澡": "语义：收据是纸，不能在上面洗澡，句子的场景不成立。", "看书": "搭配：“在收据上”不能与“看书”搭配，句子在意义上说不通。"}, "sentence_index": 6, "correct_answer": "签名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在窗前签名，望着外面的雨。", "explanation": "这里应该用〈看〉。站在窗前看外面的景色要说看，签名指亲笔留下自己的名字，不能这样用。"}, {"text": "妈妈在厨房里签名，做了一桌菜。", "explanation": "这里应该用〈做饭〉。在厨房做菜要说做饭，签名是用笔把自己的名字写在纸上，与做菜无关。"}, {"text": "工人在机器上签名，完成了检查。", "explanation": "这里应该用〈标记〉。工人在机器上做记号要说标记，签名指亲笔留下自己的名字，不用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在合同上签名名。", "corrected_sentence": "他在合同上签名。", "error_description": "错误形式：“签名名”，多出一个“名”；正确形式：“签名”，“签名”是离合词，已含“名”字，后面不能再加。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位明星当场签名得。", "corrected_sentence": "这位明星当场签名。", "error_description": "错误形式：“签名得”，“得”后面需要补语，不能直接接在动词后；正确形式：“签名”，直接作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
