INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94309, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "罢了是说话时放在最后，意思是只是这样，没什么。", "primary_collocate": null, "pronunciation": "bà le", "ipa": "pa˥˩ lə", "syllable_count": 2, "sentences": [{"text": "我只是开个玩笑罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是生气，只是有点累罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这没什么，我只是随便说说罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不过是想帮帮你罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她就是想知道你过得好不好罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哭了，不过是因为太想家罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有别的意思，只是问问罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天走路上班，不过是为了锻炼身体罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，只是不懂事罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不是生他的气，只是想一个人安静一下罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末助词，表示只是如此，没有别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94309, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了是句末助词，表示“只是如此，没什么”。"}, {"text": "怕了", "is_correct": false, "explanation": "pà（第四声）与 bà（第四声）声母不同：p 送气、b 不送气，意思是“怕了”。"}, {"text": "骂了", "is_correct": false, "explanation": "mà（第四声）与 bà（第四声）声母不同，m 是鼻音，意思是“骂了”。"}, {"text": "拔了", "is_correct": false, "explanation": "bá（第二声）与 bà（第四声）声调不同，意思是“拔了”。"}, {"text": "办了", "is_correct": false, "explanation": "bàn（第四声）比 bà 多一个韵尾 n，意思是“办了”。"}], "explanations": {"罢了": "正确：罢了是句末助词，表示“只是如此，没什么”。", "怕了": "pà（第四声）与 bà（第四声）声母不同：p 送气、b 不送气，意思是“怕了”。", "骂了": "mà（第四声）与 bà（第四声）声母不同，m 是鼻音，意思是“骂了”。", "拔了": "bá（第二声）与 bà（第四声）声调不同，意思是“拔了”。", "办了": "bàn（第四声）比 bà 多一个韵尾 n，意思是“办了”。"}, "sentence_index": null, "correct_answer": "罢了"}, "level_3": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了表示“只是如此，没什么”，与“只是”呼应。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”是动态助词，表示状态持续，不能放在句末表示“只是如此”。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，与“只是开个玩笑”的陈述语气矛盾。"}, {"text": "乎", "is_correct": false, "explanation": "语域：“乎”是文言语气词，不适合这句口语。"}], "explanations": {"罢了": "正确：罢了表示“只是如此，没什么”，与“只是”呼应。", "着": "体貌：“着”是动态助词，表示状态持续，不能放在句末表示“只是如此”。", "吗": "语义：“吗”表示疑问，与“只是开个玩笑”的陈述语气矛盾。", "乎": "语域：“乎”是文言语气词，不适合这句口语。"}, "sentence_index": 0, "correct_answer": "罢了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力罢了，成绩也很好。", "explanation": "这里应该用〈而且〉。“罢了”表示“只是如此”，表示并列递进要用“而且”。"}, {"text": "吃饭的时候罢了，我们就去散步。", "explanation": "这里“罢了”放在“时候”后，不能表示动作完成，语义不通；应说“吃完饭，我们就去散步。”"}, {"text": "快去写作业罢了！", "explanation": "这里“罢了”表示“只是如此”，语义不通；祈使语气要用“吧”，应说“快去写作业吧！”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94309, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了是句末助词，表示“只是如此，没什么”。"}, {"text": "大了", "is_correct": false, "explanation": "dà（第四声）与 bà（第四声）声母不同，意思是“大了”。"}, {"text": "爬了", "is_correct": false, "explanation": "pá（第二声）与 bà（第四声）声母送气不同、声调也不同，意思是“爬了”。"}, {"text": "扒了", "is_correct": false, "explanation": "bā（第一声）与 bà（第四声）声调不同，意思是“扒了”。"}], "explanations": {"罢了": "正确：罢了是句末助词，表示“只是如此，没什么”。", "大了": "dà（第四声）与 bà（第四声）声母不同，意思是“大了”。", "爬了": "pá（第二声）与 bà（第四声）声母送气不同、声调也不同，意思是“爬了”。", "扒了": "bā（第一声）与 bà（第四声）声调不同，意思是“扒了”。"}, "sentence_index": null, "correct_answer": "罢了"}, "level_3": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了表示“只是如此，没什么”，与“只是”呼应。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，不适合这句口语。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言语气词，不合现代口语。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示状态持续，不能放在句末表示“只是如此”。"}], "explanations": {"罢了": "正确：罢了表示“只是如此，没什么”，与“只是”呼应。", "矣": "语域：“矣”是文言语气词，不适合这句口语。", "哉": "语域：“哉”是文言语气词，不合现代口语。", "着": "体貌：“着”表示状态持续，不能放在句末表示“只是如此”。"}, "sentence_index": 6, "correct_answer": "罢了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不肯罢了休，非要问个明白。", "explanation": "这里应该用〈罢休〉。“罢了”与“罢休”不能叠用，应说“不肯罢休”。"}, {"text": "我会一直支持你，直到成功罢了。", "explanation": "这里应该用〈为止〉。“罢了”表示“只是如此”，不表示持续到某一时刻；表示“直到”要用“为止”。"}, {"text": "这次考试考得很好罢了，我真为你骄傲。", "explanation": "“罢了”表示“只是如此”，把成绩说轻，与“真为你骄傲”的赞美相矛盾；应去掉“罢了”，说“这次考试考得很好，我真为你骄傲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只是随便问问罢了的。", "corrected_sentence": "我只是随便问问罢了。", "error_description": "“罢了”是句末助词，后面不能再接“的”；应去掉“的”，改为“我只是随便问问罢了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没有骂他，只是想一个人待一会儿而已罢了。", "corrected_sentence": "我没有骂他，只是想一个人待一会儿罢了。", "error_description": "“罢了”与“而已”意思重复，句末不能叠用；应只保留“罢了”，改为“只是想一个人待一会儿罢了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
