INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94310, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用在句末，表示“不过如此”的语气。", "primary_collocate": null, "pronunciation": "bà le", "ipa": "pa˥˩ lə", "syllable_count": 2, "sentences": [{"text": "别担心，那不过是个小错误罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩不算好，也就是中等罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这有什么了不起，运气好罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他很会说，其实也就是嘴上功夫罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店名气大，东西也普通罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们说的好办法，不过是老办法罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以为他多厉害，其实不过是个新手罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛赢了，也只是碰巧罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山不高，在我看来就是个小山坡罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人夸他聪明，其实他只是比别人多努力一点罢了。", "target_word": "罢了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末助词，淡化事情，语气是不过如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94310, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了是句末助词，表示“不过如此”的语气。"}, {"text": "大了", "is_correct": false, "explanation": "dà（第四声）与 bà（第四声）声母不同，意思是“大了”。"}, {"text": "爬了", "is_correct": false, "explanation": "pá（第二声）与 bà（第四声）声母送气不同、声调也不同，意思是“爬了”。"}, {"text": "扒了", "is_correct": false, "explanation": "bā（第一声）与 bà（第四声）声调不同，意思是“扒了”。"}, {"text": "办了", "is_correct": false, "explanation": "bàn（第四声）比 bà 多一个韵尾 n，意思是“办了”。"}], "explanations": {"罢了": "正确：罢了是句末助词，表示“不过如此”的语气。", "大了": "dà（第四声）与 bà（第四声）声母不同，意思是“大了”。", "爬了": "pá（第二声）与 bà（第四声）声母送气不同、声调也不同，意思是“爬了”。", "扒了": "bā（第一声）与 bà（第四声）声调不同，意思是“扒了”。", "办了": "bàn（第四声）比 bà 多一个韵尾 n，意思是“办了”。"}, "sentence_index": null, "correct_answer": "罢了"}, "level_3": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了表示“不过如此”，与“不过是”呼应。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”是动态助词，表示状态持续，不能放在句末表示“不过如此”。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，与“不过是个小错误”的判断矛盾。"}, {"text": "乎", "is_correct": false, "explanation": "语域：“乎”是文言语气词，不适合这句口语。"}], "explanations": {"罢了": "正确：罢了表示“不过如此”，与“不过是”呼应。", "着": "体貌：“着”是动态助词，表示状态持续，不能放在句末表示“不过如此”。", "吗": "语义：“吗”表示疑问，与“不过是个小错误”的判断矛盾。", "乎": "语域：“乎”是文言语气词，不适合这句口语。"}, "sentence_index": 0, "correct_answer": "罢了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话不过是罢了，我们别当真。", "explanation": "这里“不过是”后缺少所说明的内容，“罢了”不能直接作谓语；应说“他的话不过是玩笑罢了”。"}, {"text": "他很聪明，学习也很好罢了。", "explanation": "这里应该用〈而且〉。“罢了”表示“不过如此”，表示并列递进要用“而且”。"}, {"text": "喝茶的时候罢了，我们再走吧。", "explanation": "这里“罢了”放在“时候”后，不能表示动作完成，语义不通；应说“喝完茶，我们再走吧。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94310, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了是句末助词，表示“不过如此”的语气。"}, {"text": "怕了", "is_correct": false, "explanation": "pà（第四声）与 bà（第四声）声母不同：p 送气、b 不送气，意思是“怕了”。"}, {"text": "骂了", "is_correct": false, "explanation": "mà（第四声）与 bà（第四声）声母不同，m 是鼻音，意思是“骂了”。"}, {"text": "拔了", "is_correct": false, "explanation": "bá（第二声）与 bà（第四声）声调不同，意思是“拔了”。"}], "explanations": {"罢了": "正确：罢了是句末助词，表示“不过如此”的语气。", "怕了": "pà（第四声）与 bà（第四声）声母不同：p 送气、b 不送气，意思是“怕了”。", "骂了": "mà（第四声）与 bà（第四声）声母不同，m 是鼻音，意思是“骂了”。", "拔了": "bá（第二声）与 bà（第四声）声调不同，意思是“拔了”。"}, "sentence_index": null, "correct_answer": "罢了"}, "level_3": {"options": [{"text": "罢了", "is_correct": true, "explanation": "正确：罢了表示“不过如此”，与“不过是个新手”呼应。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，与“其实不过是个新手”的判断矛盾。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，不适合这句口语。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言语气词，不合现代口语。"}], "explanations": {"罢了": "正确：罢了表示“不过如此”，与“不过是个新手”呼应。", "吗": "语义：“吗”表示疑问，与“其实不过是个新手”的判断矛盾。", "矣": "语域：“矣”是文言语气词，不适合这句口语。", "哉": "语域：“哉”是文言语气词，不合现代口语。"}, "sentence_index": 6, "correct_answer": "罢了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "快去练习罢了！", "explanation": "这里“罢了”表示“不过如此”，语义不通；祈使语气要用“吧”，应说“快去练习吧！”"}, {"text": "他不肯罢了休，非要比个高低。", "explanation": "这里应该用〈罢休〉。“罢了”与“罢休”不能叠用，应说“不肯罢休”。"}, {"text": "这次考试考得很好罢了，我真为你骄傲。", "explanation": "“罢了”表示“不过如此”，把成绩说轻，与“真为你骄傲”的赞美相矛盾；应去掉“罢了”，说“这次考试考得很好，我真为你骄傲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别着急，这只是个小问题罢了了。", "corrected_sentence": "别着急，这只是个小问题罢了。", "error_description": "“罢了”已是句末语气，后面不能再加“了”；应去掉多余的“了”，改为“这只是个小问题罢了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛输了，也只是运气不好罢了着。", "corrected_sentence": "这次比赛输了，也只是运气不好罢了。", "error_description": "“罢了”是句末助词，后面不能再加动态助词“着”；应去掉“着”，改为“也只是运气不好罢了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94311, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狡猾", "is_correct": true, "explanation": "狡猾与老实相对，指耍心眼、不诚实。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋与“老实”没有反义关系，说的是用功、肯干。"}, {"text": "热情", "is_correct": false, "explanation": "热情与“老实”没有反义关系，说的是待人亲切、主动。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静与“老实”没有反义关系，说的是情绪不激动。"}], "correct_answer": "狡猾", "explanations": {"狡猾": "狡猾与老实相对，指耍心眼、不诚实。", "勤奋": "勤奋与“老实”没有反义关系，说的是用功、肯干。", "热情": "热情与“老实”没有反义关系，说的是待人亲切、主动。", "冷静": "冷静与“老实”没有反义关系，说的是情绪不激动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94311, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狡猾", "is_correct": true, "explanation": "狡猾与老实相对，指耍心眼、不诚实。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢与“老实”没有反义关系，说的是不怕困难或危险。"}, {"text": "慷慨", "is_correct": false, "explanation": "慷慨与“老实”没有反义关系，说的是大方、不吝啬。"}, {"text": "坚定", "is_correct": false, "explanation": "坚定与“老实”没有反义关系，说的是意志不动摇。"}], "correct_answer": "狡猾", "explanations": {"狡猾": "狡猾与老实相对，指耍心眼、不诚实。", "勇敢": "勇敢与“老实”没有反义关系，说的是不怕困难或危险。", "慷慨": "慷慨与“老实”没有反义关系，说的是大方、不吝啬。", "坚定": "坚定与“老实”没有反义关系，说的是意志不动摇。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94311, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "老实是不说假话，不骗人。", "primary_collocate": null, "pronunciation": "lǎo shi", "ipa": "lau˨˩ ʂɨ", "syllable_count": 2, "sentences": [{"text": "他是个老实人，从来不说假话。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明很老实，做错事就告诉老师。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要老实回答我，是不是你拿的？", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老实的孩子不会骗人。", "target_word": "老实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做生意要老实，不能骗客人。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他老实地承认了自己的错误。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个卖菜的很老实，给的东西从不少秤。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，考试时要老实，不能抄别人的。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很老实，从来不夸大。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢和老实的人做朋友，因为可以相信他们。", "target_word": "老实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老老实实", "label": "重叠"}, {"form": "老实人", "label": "复合"}], "register": "口语", "sense_fingerprint": "诚实不说谎，不骗人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老实", "is_correct": true, "explanation": "正确：老实指诚实，不说假话、不骗人。"}, {"text": "老师", "is_correct": false, "explanation": "lǎoshī（第一声）与 lǎoshi（轻声）声调不同，意思是老师。"}, {"text": "老是", "is_correct": false, "explanation": "lǎoshì（第四声）与 lǎoshi（轻声）声调不同，意思是总是、一直。"}, {"text": "老死", "is_correct": false, "explanation": "lǎosǐ（第三声）与 lǎoshi（轻声）声调不同，意思是死于衰老。"}, {"text": "老鼠", "is_correct": false, "explanation": "lǎoshǔ（第三声）与 lǎoshi 的第二音节韵母和声调都不同，意思是老鼠。"}], "explanations": {"老实": "正确：老实指诚实，不说假话、不骗人。", "老师": "lǎoshī（第一声）与 lǎoshi（轻声）声调不同，意思是老师。", "老是": "lǎoshì（第四声）与 lǎoshi（轻声）声调不同，意思是总是、一直。", "老死": "lǎosǐ（第三声）与 lǎoshi（轻声）声调不同，意思是死于衰老。", "老鼠": "lǎoshǔ（第三声）与 lǎoshi 的第二音节韵母和声调都不同，意思是老鼠。"}, "sentence_index": null, "correct_answer": "老实"}, "level_3": {"options": [{"text": "老实", "is_correct": true, "explanation": "正确：老实指诚实、不说假话，与后面的“从来不说假话”一致。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：“狡猾”指耍心眼、不老实，与“从来不说假话”矛盾。"}, {"text": "虚伪", "is_correct": false, "explanation": "语义：“虚伪”指表里不一、装假，与“从来不说假话”矛盾。"}, {"text": "奸诈", "is_correct": false, "explanation": "语义：“奸诈”指虚伪狡猾、不讲信用，与“从来不说假话”的意思相反。"}], "explanations": {"老实": "正确：老实指诚实、不说假话，与后面的“从来不说假话”一致。", "狡猾": "语义：“狡猾”指耍心眼、不老实，与“从来不说假话”矛盾。", "虚伪": "语义：“虚伪”指表里不一、装假，与“从来不说假话”矛盾。", "奸诈": "语义：“奸诈”指虚伪狡猾、不讲信用，与“从来不说假话”的意思相反。"}, "sentence_index": 0, "correct_answer": "老实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份译文很老实，把原文的意思都译出来了。", "explanation": "这里应该用〈忠实〉。老实指为人诚实、不说假话，形容译文忠于原文要用“忠实”。"}, {"text": "他对学生要求很老实，从不放松。", "explanation": "这里应该用〈严格〉。老实只形容人的品性，不能用来形容要求或标准；应说“要求严格”。"}, {"text": "这把椅子很老实，坐上去一点都不晃。", "explanation": "这里应该用〈稳〉。老实只形容人的品性，不能用来形容椅子；形容椅子牢固、不摇晃要用“稳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老实", "is_correct": true, "explanation": "正确：老实指诚实，不欺骗，与“从不少秤”一致。"}, {"text": "贪婪", "is_correct": false, "explanation": "语义：“贪婪”指想多占便宜，与“从不少秤”的意思相反。"}, {"text": "狡诈", "is_correct": false, "explanation": "语义：“狡诈”指狡猾欺诈，与“从不少秤”的诚实语义矛盾。"}, {"text": "奸猾", "is_correct": false, "explanation": "语义：“奸猾”指奸诈耍滑，与“从不少秤”的诚实语义矛盾。"}], "explanations": {"老实": "正确：老实指诚实，不欺骗，与“从不少秤”一致。", "贪婪": "语义：“贪婪”指想多占便宜，与“从不少秤”的意思相反。", "狡诈": "语义：“狡诈”指狡猾欺诈，与“从不少秤”的诚实语义矛盾。", "奸猾": "语义：“奸猾”指奸诈耍滑，与“从不少秤”的诚实语义矛盾。"}, "sentence_index": 6, "correct_answer": "老实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事很老实，三言两语就把问题解决了。", "explanation": "这里应该用〈老练〉。老实指诚实不说谎，形容处事熟练、有经验要用“老练”。"}, {"text": "她的衣服很老实，只有一种颜色。", "explanation": "这里应该用〈朴素〉。老实只形容人，不能用来形容衣服；形容衣服简单、不花哨要用“朴素”。"}, {"text": "这个小贩很老实，一眼就看出了我是外地人。", "explanation": "这里应该用〈精明〉。“老实”形容人憨厚实在，与“一眼就看出”的机灵不符；形容人头脑灵活、善于识破要用“精明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈问他，他老实的说出了真相。", "corrected_sentence": "妈妈问他，他老实地说出了真相。", "error_description": "“老实”修饰动词“说出”，作状语时应用“地”，不能用“的”。应改为“老实地说出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说话老实的让人放心。", "corrected_sentence": "他说话老实得让人放心。", "error_description": "“老实”作补语，说明“说话”的样子，补语前应用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94312, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "调皮", "is_correct": true, "explanation": "调皮与老实相对，指爱闹、不听话。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢与“老实”没有反义关系，说的是不怕困难或危险。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐与“老实”没有反义关系，说的是有秩序、不零乱。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮与“老实”没有反义关系，说的是光线充足或颜色鲜亮。"}], "correct_answer": "调皮", "explanations": {"调皮": "调皮与老实相对，指爱闹、不听话。", "勇敢": "勇敢与“老实”没有反义关系，说的是不怕困难或危险。", "整齐": "整齐与“老实”没有反义关系，说的是有秩序、不零乱。", "明亮": "明亮与“老实”没有反义关系，说的是光线充足或颜色鲜亮。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94312, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顽皮", "is_correct": true, "explanation": "顽皮与老实相对，指淘气、不听话。"}, {"text": "慷慨", "is_correct": false, "explanation": "慷慨与“老实”没有反义关系，说的是大方、不吝啬。"}, {"text": "坚定", "is_correct": false, "explanation": "坚定与“老实”没有反义关系，说的是意志不动摇。"}, {"text": "斯文", "is_correct": false, "explanation": "斯文与“老实”没有反义关系，说的是举止文雅。"}], "correct_answer": "顽皮", "explanations": {"顽皮": "顽皮与老实相对，指淘气、不听话。", "慷慨": "慷慨与“老实”没有反义关系，说的是大方、不吝啬。", "坚定": "坚定与“老实”没有反义关系，说的是意志不动摇。", "斯文": "斯文与“老实”没有反义关系，说的是举止文雅。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94312, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "规矩；听话，不乱来。", "primary_collocate": null, "pronunciation": "lǎo shi", "ipa": "lau˨˩ ʂɨ", "syllable_count": 2, "sentences": [{"text": "孩子在课堂上很老实，不乱动。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你给我老实点儿，别乱跑！", "target_word": "老实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说了他以后，他老实多了。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗今天很老实，一直趴在地上。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在这儿老实待着，不要出去。", "target_word": "老实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前很爱玩，现在变老实了。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在警察面前老实多了。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学生很老实，从不迟到，也不吵架。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不老实，妈妈不带他出去玩。", "target_word": "老实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手放在桌上，老实地坐着。", "target_word": "老实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老老实实", "label": "重叠"}, {"form": "老实人", "label": "复合"}], "register": "口语", "sense_fingerprint": "规矩听话，不乱来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老实", "is_correct": true, "explanation": "正确：老实指规矩听话，不乱来。"}, {"text": "老师", "is_correct": false, "explanation": "lǎoshī（第一声）与 lǎoshi（轻声）声调不同，意思是老师。"}, {"text": "老式", "is_correct": false, "explanation": "lǎoshì（第四声）与 lǎoshi（轻声）声调不同，意思是旧式的、老样式的。"}, {"text": "老死", "is_correct": false, "explanation": "lǎosǐ（第三声）与 lǎoshi（轻声）声调不同，意思是死于衰老。"}, {"text": "老鼠", "is_correct": false, "explanation": "lǎoshǔ（第三声）与 lǎoshi 的第二音节韵母和声调都不同，意思是老鼠。"}], "explanations": {"老实": "正确：老实指规矩听话，不乱来。", "老师": "lǎoshī（第一声）与 lǎoshi（轻声）声调不同，意思是老师。", "老式": "lǎoshì（第四声）与 lǎoshi（轻声）声调不同，意思是旧式的、老样式的。", "老死": "lǎosǐ（第三声）与 lǎoshi（轻声）声调不同，意思是死于衰老。", "老鼠": "lǎoshǔ（第三声）与 lǎoshi 的第二音节韵母和声调都不同，意思是老鼠。"}, "sentence_index": null, "correct_answer": "老实"}, "level_3": {"options": [{"text": "老实", "is_correct": true, "explanation": "正确：老实指规矩听话、不乱来，与“不乱动”相符。"}, {"text": "调皮", "is_correct": false, "explanation": "语义：“调皮”指爱闹、不听话，与后面的“不乱动”意思相反。"}, {"text": "好动", "is_correct": false, "explanation": "语义：“好动”指喜欢活动，与“不乱动”矛盾。"}, {"text": "顽劣", "is_correct": false, "explanation": "语义：“顽劣”指顽皮不听话，与“不乱动”的意思相反。"}], "explanations": {"老实": "正确：老实指规矩听话、不乱来，与“不乱动”相符。", "调皮": "语义：“调皮”指爱闹、不听话，与后面的“不乱动”意思相反。", "好动": "语义：“好动”指喜欢活动，与“不乱动”矛盾。", "顽劣": "语义：“顽劣”指顽皮不听话，与“不乱动”的意思相反。"}, "sentence_index": 0, "correct_answer": "老实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里很老实，同学们都在低头看书。", "explanation": "这里应该用〈安静〉。老实形容人的行为规矩，不能用来形容场所的状态；描写环境要用“安静”。"}, {"text": "他遇到危险时很老实，马上想出了办法。", "explanation": "这里应该用〈冷静〉。老实指规矩听话、不乱来；形容遇事不慌、头脑清楚要用“冷静”。"}, {"text": "这辆车很老实，开起来一点也不晃。", "explanation": "这里应该用〈稳〉。老实形容人规矩、不乱动，不能用来形容车辆；车辆行驶平稳要用“稳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老实", "is_correct": true, "explanation": "正确：老实指规矩听话，与“多了”的变化及在警察面前的态度相符。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”描述身材，不表示态度变化，与“在警察面前”的语境不符。"}, {"text": "蛮横", "is_correct": false, "explanation": "语义：“蛮横”指强硬不讲理，与“在警察面前老实多了”的变化方向相反。"}, {"text": "放肆", "is_correct": false, "explanation": "语义：“放肆”指毫无拘束、不守规矩，与“在警察面前老实多了”的变化方向相反。"}], "explanations": {"老实": "正确：老实指规矩听话，与“多了”的变化及在警察面前的态度相符。", "胖": "语义：“胖”描述身材，不表示态度变化，与“在警察面前”的语境不符。", "蛮横": "语义：“蛮横”指强硬不讲理，与“在警察面前老实多了”的变化方向相反。", "放肆": "语义：“放肆”指毫无拘束、不守规矩，与“在警察面前老实多了”的变化方向相反。"}, "sentence_index": 6, "correct_answer": "老实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的房间很老实，床铺叠得整整齐齐。", "explanation": "这里应该用〈整洁〉。老实形容人的行为规矩，不能用来形容房间；形容房间干净利落要用“整洁”。"}, {"text": "他听到消息很老实，手都在抖。", "explanation": "这里应该用〈慌张〉。老实指规矩听话、不乱来；形容受惊、心神不定要用“慌张”。"}, {"text": "他的脑筋很老实，总能想出各种新点子。", "explanation": "这里应该用〈灵活〉。老实形容人规矩、诚实，不能形容脑筋；形容思路变通、善于想办法要用“灵活”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们老实得坐着，等老师讲课。", "corrected_sentence": "孩子们老实地坐着，等老师讲课。", "error_description": "“老实”修饰动词“坐”，作状语，应用“地”，不能用“得”（“得”用于补语）。应改为“老实地坐着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐很老实，一动不动。", "corrected_sentence": "他坐得很老实，一动不动。", "error_description": "“老实”作补语，说明“坐”的状态，动词与补语之间须用“得”，应为“坐得很老实”，不能省略“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
