INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94315, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94315, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "至高是高到不能再高了。", "primary_collocate": null, "pronunciation": "zhì gāo", "ipa": "tʂʐ̩⁵¹ kɑʊ̯⁵⁵", "syllable_count": 2, "sentences": [{"text": "获得金牌是运动员至高的荣誉。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对军人来说，保卫国家是至高的责任。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他心中，诚信是至高的美德。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖是音乐界至高的奖项。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对她来说，自由是至高的理想。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把孩子的安全看作至高的目标。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人在村里受到至高的尊重。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目标是成为这个行业的至高权威。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他看来，家人的健康是至高的幸福。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这个民族来说，太阳是至高的神。", "target_word": "至高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "至高无上", "label": "复合"}], "register": "书面语", "sense_fingerprint": "高到不能再高，地位、价值或程度最高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89da991-ce23-4a2a-800d-16d17cb3d807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通", "is_correct": false, "explanation": "语义：金牌是运动员的重要荣誉，说成“普通的荣誉”与金牌的分量相矛盾。"}, {"text": "微薄", "is_correct": false, "explanation": "搭配：“微薄”多修饰收入、力量、希望，不说“微薄的荣誉”。"}, {"text": "至高", "is_correct": true, "explanation": "正确：“至高”是最高、到顶的意思，修饰“荣誉”，与获得金牌相称。"}, {"text": "低贱", "is_correct": false, "explanation": "语义：“低贱”是贬义，与“荣誉”的褒义相反，句子语义不通。"}], "explanations": {"普通": "语义：金牌是运动员的重要荣誉，说成“普通的荣誉”与金牌的分量相矛盾。", "微薄": "搭配：“微薄”多修饰收入、力量、希望，不说“微薄的荣誉”。", "至高": "正确：“至高”是最高、到顶的意思，修饰“荣誉”，与获得金牌相称。", "低贱": "语义：“低贱”是贬义，与“荣誉”的褒义相反，句子语义不通。"}, "sentence_index": 0, "correct_answer": "至高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，他的分数是班里至高的。", "explanation": "这里应该用〈最高〉。“至高”多用于地位、价值、荣誉等抽象事物，分数这类可以计量的数值要用“最高”。"}, {"text": "这家至高的酒店在市中心。", "explanation": "这里应该用〈顶级〉。“至高”修饰抽象的地位或价值，不修饰酒店这类具体场所；“顶级”可以用来描述酒店。"}, {"text": "他的成绩比同学至高。", "explanation": "这里应该用〈高〉。“至高”表示最高程度，已是顶点，不能与“比”连用做比较；比较应说“比同学高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”与“尊重”的敬重之意相反，句子语义矛盾。"}, {"text": "粗暴", "is_correct": false, "explanation": "搭配：“粗暴”形容对待的方式，不修饰“尊重”。"}, {"text": "至高", "is_correct": true, "explanation": "正确：“至高”是最高的意思，修饰“尊重”，表示极度敬重。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，与受到尊重所包含的亲近语义不合。"}], "explanations": {"冷漠": "语义：“冷漠”与“尊重”的敬重之意相反，句子语义矛盾。", "粗暴": "搭配：“粗暴”形容对待的方式，不修饰“尊重”。", "至高": "正确：“至高”是最高的意思，修饰“尊重”，表示极度敬重。", "陌生": "语义：“陌生”指不熟悉，与受到尊重所包含的亲近语义不合。"}, "sentence_index": 6, "correct_answer": "至高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个骗子犯下的是至高的罪行。", "explanation": "这里应该用〈最严重〉。“至高”是褒义，表示最高的价值或地位，不能形容罪行这类负面的事。"}, {"text": "这道菜的味道至高，大家都爱吃。", "explanation": "这里应该用〈最好〉。“至高”用于地位、价值等抽象事物，不说“味道至高”。"}, {"text": "这座公园的面积在全市至高。", "explanation": "这里应该用〈最大〉。“至高”强调抽象的地位或价值，面积这类可以测量的数量要用“最大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对这个家庭来说，团结是很至高的信念。", "corrected_sentence": "对这个家庭来说，团结是至高的信念。", "error_description": "错误在于“很至高”。“至高”本身已表示最高程度，是绝对的说法，不能再用“很”修饰；去掉“很”即为正确说法“至高的信念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在行业内享有无上至高的地位。", "corrected_sentence": "他在行业内享有至高的地位。", "error_description": "错误在于“无上至高”。“至高无上”是固定说法，“无上”只能放在“至高”之后，前面多出的“无上”应删去，改为“至高的地位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
