INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94317, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94317, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "董事是公司里帮大家做大决定的人。", "primary_collocate": null, "pronunciation": "dǒng shì", "ipa": "tʊŋ˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他是这家公司的董事。", "target_word": "董事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "董事们今天开会，决定新计划。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司有五位董事。", "target_word": "董事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件大事要请董事来决定。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当上了公司的董事，很高兴。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老张是我们公司最年轻的董事。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要买新工厂，得先问问董事。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事们一起想办法，让公司越来越好。", "target_word": "董事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做过很多年老师，后来成了公司董事。", "target_word": "董事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买不买这家店，要听董事的意见。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "董事会", "label": "复合"}, {"form": "董事长", "label": "复合"}], "register": "正式", "sense_fingerprint": "公司里参加开会、帮助决定大事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94317, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "董事", "is_correct": true, "explanation": "正确答案。董事：公司里参与决定大事的人。"}, {"text": "同事", "is_correct": false, "explanation": "tóng（第二声）与 dǒng（第三声）声母不同（t/d），声调也不同，意思是一起工作的人。"}, {"text": "总是", "is_correct": false, "explanation": "zǒng 与 dǒng 声母不同（z/d），声调相同，意思是一直、经常。"}, {"text": "顶事", "is_correct": false, "explanation": "dǐng（第三声）与 dǒng（第三声）韵母不同（ing/ong），声调相同，意思是有用、管用。"}], "explanations": {"董事": "正确答案。董事：公司里参与决定大事的人。", "同事": "tóng（第二声）与 dǒng（第三声）声母不同（t/d），声调也不同，意思是一起工作的人。", "总是": "zǒng 与 dǒng 声母不同（z/d），声调相同，意思是一直、经常。", "顶事": "dǐng（第三声）与 dǒng（第三声）韵母不同（ing/ong），声调相同，意思是有用、管用。"}, "sentence_index": null, "correct_answer": "董事"}, "level_3": {"options": [{"text": "董事", "is_correct": true, "explanation": "正确：董事是公司里参与决策的人，可以说“这家公司的董事”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生属于学校，不是公司的人员身份，与“这家公司的”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“公司的病人”不搭配，病人与医院相关，不能说是公司的身份。"}, {"text": "校长", "is_correct": false, "explanation": "语义：校长管理的是学校，与“这家公司的”身份不符。"}], "explanations": {"董事": "正确：董事是公司里参与决策的人，可以说“这家公司的董事”。", "学生": "语义：学生属于学校，不是公司的人员身份，与“这家公司的”矛盾。", "病人": "搭配：“公司的病人”不搭配，病人与医院相关，不能说是公司的身份。", "校长": "语义：校长管理的是学校，与“这家公司的”身份不符。"}, "sentence_index": 0, "correct_answer": "董事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是公司的董事，每天负责给客人端茶倒水。", "explanation": "这里应该用〈服务员〉。董事是参与公司重大决策的人，不负责给客人端茶倒水这类服务工作。"}, {"text": "我们班的董事是最认真的学生，常帮老师收作业。", "explanation": "这里应该用〈班长〉。董事指公司董事会的成员，班里的学生干部不叫董事。"}, {"text": "我们公司的董事每天晚上在大门口值班，保护大家的安全。", "explanation": "这里应该用〈保安〉。董事负责公司的重大决策，不做值班、守门这类保卫工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "董事", "is_correct": true, "explanation": "正确：“问问”的对象应是能决定大事的董事。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“问”要求的对象是人或事情，不能问“空气”。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“问问”的对象要能回答问题，“石头”不能被问。"}, {"text": "臣子", "is_correct": false, "explanation": "语域：“臣子”是古代的说法，不符合现代公司决策的表达语域。"}], "explanations": {"董事": "正确：“问问”的对象应是能决定大事的董事。", "空气": "配价：“问”要求的对象是人或事情，不能问“空气”。", "石头": "配价：“问问”的对象要能回答问题，“石头”不能被问。", "臣子": "语域：“臣子”是古代的说法，不符合现代公司决策的表达语域。"}, "sentence_index": 6, "correct_answer": "董事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "董事每天负责给公园里的树剪枝。", "explanation": "这里应该用〈园丁〉。董事是参与公司重大决策的人，不负责给树剪枝这类园艺工作。"}, {"text": "董事每天负责给客户拍照留念。", "explanation": "这里应该用〈摄影师〉。董事是参与公司重大决策的人，不负责给客户拍照。"}, {"text": "董事每天在医院里给病人看病。", "explanation": "这里应该用〈医生〉。董事不从事医疗工作，不给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司新请了一只董事，他很有经验。", "corrected_sentence": "公司新请了一位董事，他很有经验。", "error_description": "量词错误：“董事”指人，应说“一位董事”，不能说“一只董事”。“只”多用于动物等，不用于指人的名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是大家都信任董事。", "corrected_sentence": "这是大家都信任的董事。", "error_description": "定语缺少“的”：“大家都信任的董事”中，“大家都信任”修饰“董事”，需加“的”，不能省略成“大家都信任董事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
