INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公司董事会的成员，参与公司重大事项决策。", "primary_collocate": null, "pronunciation": "dǒng shì", "ipa": "tʊŋ˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司有七名董事。", "target_word": "董事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每位董事都可以说自己的想法。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事要为公司的大事投票。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的董事去年才加入董事会。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事们开会讨论公司明年的计划。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位董事对公司的发展很关心。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两位董事不同意卖掉这家工厂。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当过三年董事，很了解公司的情况。", "target_word": "董事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事需要看公司的报告，再做决定。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司请了一位有经验的人当董事。", "target_word": "董事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "董事会", "label": "复合"}, {"form": "董事长", "label": "复合"}], "register": "正式", "sense_fingerprint": "董事会成员，参与公司重大事项的讨论和表决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f364600f-7b99-492e-92e1-8d9cb5f005bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94318, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "董事", "is_correct": true, "explanation": "正确答案。董事：董事会的成员，参与公司重大事项的决策。"}, {"text": "同事", "is_correct": false, "explanation": "tóng（第二声）与 dǒng（第三声）声母不同（t/d），声调也不同，意思是一起工作的人。"}, {"text": "总是", "is_correct": false, "explanation": "zǒng 与 dǒng 声母不同（z/d），声调相同，意思是一直、经常。"}, {"text": "顶事", "is_correct": false, "explanation": "dǐng（第三声）与 dǒng（第三声）韵母不同（ing/ong），声调相同，意思是有用、管用。"}], "explanations": {"董事": "正确答案。董事：董事会的成员，参与公司重大事项的决策。", "同事": "tóng（第二声）与 dǒng（第三声）声母不同（t/d），声调也不同，意思是一起工作的人。", "总是": "zǒng 与 dǒng 声母不同（z/d），声调相同，意思是一直、经常。", "顶事": "dǐng（第三声）与 dǒng（第三声）韵母不同（ing/ong），声调相同，意思是有用、管用。"}, "sentence_index": null, "correct_answer": "董事"}, "level_3": {"options": [{"text": "董事", "is_correct": true, "explanation": "正确：“这家公司有七名董事”指公司董事会的成员，与“公司”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "量词：“名”用于人，桌子是物品，不能说“七名桌子”。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“七名病人”与“这家公司”不搭配，病人与医院相关。"}, {"text": "校长", "is_correct": false, "explanation": "语义：校长管理学校，不能作为公司董事会的成员被计数。"}], "explanations": {"董事": "正确：“这家公司有七名董事”指公司董事会的成员，与“公司”搭配。", "桌子": "量词：“名”用于人，桌子是物品，不能说“七名桌子”。", "病人": "搭配：“七名病人”与“这家公司”不搭配，病人与医院相关。", "校长": "语义：校长管理学校，不能作为公司董事会的成员被计数。"}, "sentence_index": 0, "correct_answer": "董事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新来的董事每周都去学校给学生上数学课。", "explanation": "这里应该用〈老师〉。董事是公司董事会的成员，参与重大事项决策，不在学校给学生上课。"}, {"text": "这家公司的董事每天早上负责扫地。", "explanation": "这里应该用〈清洁工〉。董事是参与公司重大事项决策的人，不做扫地这类清洁工作。"}, {"text": "董事每天在工厂里操作机器，生产零件。", "explanation": "这里应该用〈工人〉。董事是参与公司重大事项决策的人，不在工厂里操作机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "董事", "is_correct": true, "explanation": "正确：“两位董事”是能表态、参与决定的人，可以“不同意”。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“不同意”的主语必须是能表态的人，“空气”不能表态。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“不同意”的主语必须能表达意见，“石头”不能表达意见。"}, {"text": "臣子", "is_correct": false, "explanation": "语域：“臣子”是古代用语，不符合现代公司决策的表达语域。"}], "explanations": {"董事": "正确：“两位董事”是能表态、参与决定的人，可以“不同意”。", "空气": "配价：“不同意”的主语必须是能表态的人，“空气”不能表态。", "石头": "配价：“不同意”的主语必须能表达意见，“石头”不能表达意见。", "臣子": "语域：“臣子”是古代用语，不符合现代公司决策的表达语域。"}, "sentence_index": 6, "correct_answer": "董事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "董事每天在病房里给病人打针、换药。", "explanation": "这里应该用〈护士〉。董事是参与公司重大事项决策的人，不在病房照顾病人。"}, {"text": "董事每天一早就去田里种菜。", "explanation": "这里应该用〈农民〉。董事是参与公司重大事项决策的人，不从事农业劳动。"}, {"text": "董事每天开着货车给客户送货。", "explanation": "这里应该用〈司机〉。董事不负责开车送货这类具体工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重要决定，每董事都要签字。", "corrected_sentence": "重要决定，每位董事都要签字。", "error_description": "量词缺失：“每”后面一般要带量词，应说“每位董事”，不能说“每董事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一件董事提出了新的想法。", "corrected_sentence": "一位董事提出了新的想法。", "error_description": "量词错误：“董事”指人，应说“一位董事”，不能说“一件董事”，“件”用于物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f71cdcf-f22b-47df-8eaa-818ce61cc587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
