INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94322, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94322, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就某一事物发表意见、互相交谈。", "primary_collocate": null, "pronunciation": "tán lùn", "ipa": "tʰan˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "大家都在谈论这本书的好坏。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上很多人谈论这个新办法。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们谈论着公司的新政策。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常常谈论天气的变化。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们谈论了这部电视剧的结局。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们谈论老师的教学方法。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太喜欢谈论别人的缺点。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者和专家谈论今年的经济情况。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对这个问题谈论得很热烈。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，代表们谈论过环境保护。", "target_word": "谈论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈论了", "label": "体标"}, {"form": "谈论着", "label": "体标"}, {"form": "谈论过", "label": "体标"}, {"form": "談論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对某事物发表看法并互相交流意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9550a99-05ab-43a0-8580-e05f022f057f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈论", "is_correct": true, "explanation": "“谈论”指对某事物发表看法、互相交流，与“这本书的好坏”相符。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”的对象是文字或计划，不能说“修改书的好坏”。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是具体物品，“好坏”是抽象性质，不能收藏。"}, {"text": "遵守", "is_correct": false, "explanation": "语义：“遵守”指服从规则，与“书的好坏”不相关。"}], "explanations": {"谈论": "“谈论”指对某事物发表看法、互相交流，与“这本书的好坏”相符。", "修改": "搭配：“修改”的对象是文字或计划，不能说“修改书的好坏”。", "收藏": "搭配：“收藏”的对象是具体物品，“好坏”是抽象性质，不能收藏。", "遵守": "语义：“遵守”指服从规则，与“书的好坏”不相关。"}, "sentence_index": 0, "correct_answer": "谈论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人坐在桌前，默默地谈论着明天的考试。", "explanation": "这里应该用〈想〉。〈谈论〉是几个人说出看法、互相交流，一个人默默地应该用〈想〉。"}, {"text": "这台电视机谈论了一下午。", "explanation": "这里应该用〈播放〉。〈谈论〉的主语须是能发表看法的人，电视机不能谈论，应说〈播放〉。"}, {"text": "奶奶谈论了一个故事给我听。", "explanation": "这里应该用〈讲〉。〈谈论〉是大家一起交流，奶奶讲故事给我听应该用〈讲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈论", "is_correct": true, "explanation": "“谈论”表示说话、交流看法，与“不太喜欢”和“别人的缺点”的语境相符。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是新事物或技术，不能用于“别人的缺点”。"}, {"text": "布置", "is_correct": false, "explanation": "搭配：“布置”的对象是场地或任务，不能说“布置别人的缺点”。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”指正式同意，不能用来表示对“缺点”的态度。"}], "explanations": {"谈论": "“谈论”表示说话、交流看法，与“不太喜欢”和“别人的缺点”的语境相符。", "发明": "搭配：“发明”的对象是新事物或技术，不能用于“别人的缺点”。", "布置": "搭配：“布置”的对象是场地或任务，不能说“布置别人的缺点”。", "批准": "语义：“批准”指正式同意，不能用来表示对“缺点”的态度。"}, "sentence_index": 6, "correct_answer": "谈论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫谈论过很多次。", "explanation": "这里应该用〈叫〉。〈谈论〉的主语须是能说话的人，猫不能谈论，猫的叫声应说〈叫〉。"}, {"text": "我每天早上在公园里谈论半个小时。", "explanation": "这里应该用〈跑步〉。〈谈论〉要有谈的对象和事情，在公园里锻炼身体应该用〈跑步〉。"}, {"text": "代表们在会上谈论环境保护，却一句话也没说。", "explanation": "这里与〈谈论〉的“说”矛盾，应该用〈关注〉。〈谈论〉表示发表看法，不能同时说“一句话也没说”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里大家谈论很激烈。", "corrected_sentence": "会议室里大家谈论得很激烈。", "error_description": "程度补语错误：“谈论”后缺少“得”，应说“谈论得很激烈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们谈论了过这个计划的风险。", "corrected_sentence": "他们谈论过这个计划的风险。", "error_description": "体标错误：“了”与“过”不能同时使用，应说“谈论过”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
