INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94323, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "论述是把道理一点一点讲清楚。", "primary_collocate": null, "pronunciation": "lùn shù", "ipa": "lu̯ən˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "老师在课上论述了这个道理。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用三个例子论述自己的看法。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章把环保的重要性论述得很清楚。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者先论述原因，再讲办法。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你论述一下读书的好处。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一点一点论述着这个问题的原因。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里论述过学习和休息的关系。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她论述得有道理，大家都点头。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长论述了为什么要多运动。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能把你的想法论述清楚？", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "论述了", "label": "体标"}, {"form": "论述过", "label": "体标"}, {"form": "论述着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "论述：把道理一步一步讲清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "论述", "is_correct": true, "explanation": "正确：“论述”是把道理一点一点讲清楚，老师在课上讲解这个道理，意思吻合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“道理”作宾语，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是具体物体表面，不能带“道理”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能带“道理”作宾语，句子不通。"}], "explanations": {"论述": "正确：“论述”是把道理一点一点讲清楚，老师在课上讲解这个道理，意思吻合。", "吃": "搭配：“吃”不能带“道理”作宾语，句子不通。", "擦": "搭配：“擦”的对象是具体物体表面，不能带“道理”作宾语。", "喝": "搭配：“喝”不能带“道理”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "论述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家一起论述这盘饺子，都很开心。", "explanation": "这里应该用〈吃〉。论述指把道理讲清楚，饺子是食物，不能论述，要说大家一起吃这盘饺子。"}, {"text": "他论述了一双新鞋，很舒服。", "explanation": "这里应该用〈穿〉。论述指把道理讲清楚，鞋子不能论述，要说穿上一双新鞋。"}, {"text": "我向新同学论述了我们学校的图书馆。", "explanation": "这里应该用〈介绍〉。论述侧重讲清道理，向别人说明事物的情况要用介绍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "论述", "is_correct": true, "explanation": "正确：“论述”是讲清道理，书里讲学习和休息的关系，意思吻合。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”不能跟“关系”搭配，书里跑过关系说不通。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象是具体物件，不能说搬关系。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：书不会讨厌什么，“讨厌”与书中讲道理的语境不符。"}], "explanations": {"论述": "正确：“论述”是讲清道理，书里讲学习和休息的关系，意思吻合。", "跑": "搭配：“跑”不能跟“关系”搭配，书里跑过关系说不通。", "搬": "搭配：“搬”的对象是具体物件，不能说搬关系。", "讨厌": "语义：书不会讨厌什么，“讨厌”与书中讲道理的语境不符。"}, "sentence_index": 6, "correct_answer": "论述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他论述了一碗面条，很香。", "explanation": "这里应该用〈吃〉。论述指把道理讲清楚，面条是食物，不能论述，要说吃一碗面条。"}, {"text": "妈妈论述了一块新蛋糕。", "explanation": "这里应该用〈做〉。论述指把道理讲清楚，蛋糕是具体食物，不能论述，要说做一块新蛋糕。"}, {"text": "这只小狗论述得很开心。", "explanation": "这里应该用〈玩〉。论述的主语应是能讲道理的人，小狗不能论述，要说玩得很开心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把解题的方法论述清了楚。", "corrected_sentence": "老师把解题的方法论述清楚。", "error_description": "错误形式是“论述清了楚”，在结果补语“清楚”中间插入了“了”。正确形式是“论述清楚”，“清楚”是一个整体的结果补语，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他论述地很清楚。", "corrected_sentence": "他论述得很清楚。", "error_description": "错误形式是“论述地很清楚”，程度补语的标志用成了“地”。正确形式是“论述得很清楚”，动词后表示程度的补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
