INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叙述并分析说明某个问题。", "primary_collocate": null, "pronunciation": "lùn shù", "ipa": "lu̯ən˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这位专家论述了经济发展的问题。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章先论述历史，再分析现在。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报告中论述了城市交通的问题。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的第二章论述了语言和文化。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者论述这件事时，用了很多数据。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇论文论述了空气污染的原因。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他论述过教育对孩子的影响。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用三百字论述你对这个问题的看法。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们论述环境和健康的关系。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告论述得很全面，也很清楚。", "target_word": "论述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "论述了", "label": "体标"}, {"form": "论述过", "label": "体标"}, {"form": "论述着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "论述：叙述并分析某个问题，常见于文章和报告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "论述", "is_correct": true, "explanation": "正确：“论述”是叙述并分析某个问题，专家讲经济发展的问题，意思吻合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物或水，不能说煮问题。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与专家分析问题的意思不合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能带“问题”作宾语，句子不通。"}], "explanations": {"论述": "正确：“论述”是叙述并分析某个问题，专家讲经济发展的问题，意思吻合。", "煮": "搭配：“煮”的对象是食物或水，不能说煮问题。", "扔": "语义：“扔”是丢弃，与专家分析问题的意思不合。", "洗": "搭配：“洗”不能带“问题”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "论述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们几个人论述了周末去哪儿玩。", "explanation": "这里应该用〈讨论〉。论述是一方讲清问题，几个人交换意见要用讨论。"}, {"text": "他论述了草原上的美丽风景。", "explanation": "这里应该用〈描写〉。论述用于分析问题，描绘景物的美丽要用描写。"}, {"text": "他在信里论述了一顿晚饭，很丰盛。", "explanation": "这里应该用〈吃〉。论述用于讲清或分析问题，晚饭是吃的东西，要说吃了一顿晚饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "论述", "is_correct": true, "explanation": "正确：“论述过”表示说明过教育对孩子的影响，意思吻合。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”不能带“影响”作宾语，句子不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”不能带“影响”作宾语，句子不通。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉文字等，“删除过影响”说不通。"}], "explanations": {"论述": "正确：“论述过”表示说明过教育对孩子的影响，意思吻合。", "跑": "搭配：“跑”不能带“影响”作宾语，句子不通。", "穿": "搭配：“穿”不能带“影响”作宾语，句子不通。", "删除": "语义：“删除”是去掉文字等，“删除过影响”说不通。"}, "sentence_index": 6, "correct_answer": "论述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他论述了一碗热汤，很好喝。", "explanation": "这里应该用〈喝〉。论述用于叙述并分析问题，热汤是喝的东西，不能论述，要说喝了一碗热汤。"}, {"text": "妈妈论述了一双新手套，很暖和。", "explanation": "这里应该用〈戴〉。论述用于讲清或分析问题，手套是戴在手上的东西，要说戴一双新手套。"}, {"text": "这只小猫论述得很可爱。", "explanation": "这里应该用〈长得〉。论述的主语应是能讲道理的人，小猫不能论述，形容它的样子要说长得很可爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她论述地很有条理。", "corrected_sentence": "她论述得很有条理。", "error_description": "错误形式是“论述地很有条理”，程度补语的标志用成了“地”。正确形式是“论述得很有条理”，动词后的补语要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把这个问题论述清了楚。", "corrected_sentence": "她把这个问题论述清楚。", "error_description": "错误形式是“论述清了楚”，在结果补语“清楚”中间插入了“了”。正确形式是“论述清楚”，“清楚”是一个整体的结果补语，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
