INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赌是拿钱或东西去比输赢。", "primary_collocate": null, "pronunciation": "dǔ", "ipa": "tu˨˩˦", "syllable_count": 1, "sentences": [{"text": "他们在桌子旁赌钱。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷从来不赌。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友们赌谁能赢这场球。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他赌了五百块，结果输了。", "target_word": "赌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不赌钱，只是玩玩。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一赌就是一整夜。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈不让爸爸赌钱。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个人赌一顿饭，输的人请客。", "target_word": "赌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手表拿去赌了。", "target_word": "赌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赌红了眼，什么都不管了。", "target_word": "赌", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赌了", "label": "体标（完成）"}, {"form": "赌过", "label": "体标（经历）"}, {"form": "赌着", "label": "体标（持续）"}, {"form": "賭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赌：拿钱或东西作注，比谁输谁赢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ce9a55-ce32-4de2-b1f7-ff56f8f8bde6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94325, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赌", "is_correct": true, "explanation": "赌（dǔ）：拿钱或东西作注，比输赢，是本义。"}, {"text": "肚", "is_correct": false, "explanation": "dù（第四声）与 dǔ（第三声）声调不同，肚子的意思，不是比输赢。"}, {"text": "度", "is_correct": false, "explanation": "dù（第四声）与 dǔ（第三声）声调不同，程度或度量的意思。"}, {"text": "土", "is_correct": false, "explanation": "tǔ 与 dǔ 声母不同（t 与 d），泥土的意思。"}, {"text": "苦", "is_correct": false, "explanation": "kǔ 与 dǔ 声母不同（k 与 d），苦味或辛苦的意思。"}, {"text": "补", "is_correct": false, "explanation": "bǔ 与 dǔ 声母不同（b 与 d），补充或修补的意思。"}], "explanations": {"赌": "赌（dǔ）：拿钱或东西作注，比输赢，是本义。", "肚": "dù（第四声）与 dǔ（第三声）声调不同，肚子的意思，不是比输赢。", "度": "dù（第四声）与 dǔ（第三声）声调不同，程度或度量的意思。", "土": "tǔ 与 dǔ 声母不同（t 与 d），泥土的意思。", "苦": "kǔ 与 dǔ 声母不同（k 与 d），苦味或辛苦的意思。", "补": "bǔ 与 dǔ 声母不同（b 与 d），补充或修补的意思。"}, "sentence_index": null, "correct_answer": "赌"}, "level_3": {"options": [{"text": "赌", "is_correct": true, "explanation": "正确：“赌”与“钱”搭配，表示拿钱比输赢，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语多为饮料，不能说喝钱。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的宾语是球或物体，不能说踢钱。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声表演，与“钱”没有语义关联，句子无法成立。"}], "explanations": {"赌": "正确：“赌”与“钱”搭配，表示拿钱比输赢，符合句意。", "喝": "搭配：“喝”的宾语多为饮料，不能说喝钱。", "踢": "搭配：“踢”的宾语是球或物体，不能说踢钱。", "唱": "语义：“唱”指发声表演，与“钱”没有语义关联，句子无法成立。"}, "sentence_index": 0, "correct_answer": "赌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把房子赌给了银行。", "explanation": "这里应该用〈抵押〉。抵押是把房产交给银行作担保，“赌”表示拿钱或东西比输赢，不能用于担保借贷。"}, {"text": "他把钥匙赌给了邻居保管。", "explanation": "这里应该用〈托〉。托是请人代为保管，“赌”表示拿东西比输赢，不能用于委托保管。"}, {"text": "他把车赌给了朋友开。", "explanation": "这里应该用〈借〉。借是把东西给别人使用，“赌”表示拿东西比输赢，不能表示出借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94325, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赌", "is_correct": true, "explanation": "赌（dǔ）：拿钱或东西作注，比输赢，是本义。"}, {"text": "鼓", "is_correct": false, "explanation": "gǔ 与 dǔ 声母不同（g 与 d），鼓或鼓励的意思。"}, {"text": "努", "is_correct": false, "explanation": "nǔ 与 dǔ 声母不同（n 与 d），努力的意思，不是比输赢。"}, {"text": "组", "is_correct": false, "explanation": "zǔ 与 dǔ 声母不同（z 与 d），组织或小组的意思。"}, {"text": "府", "is_correct": false, "explanation": "fǔ 与 dǔ 声母不同（f 与 d），政府或官府的意思。"}, {"text": "杜", "is_correct": false, "explanation": "dù（第四声）与 dǔ（第三声）声调不同，杜绝或姓杜的意思。"}], "explanations": {"赌": "赌（dǔ）：拿钱或东西作注，比输赢，是本义。", "鼓": "gǔ 与 dǔ 声母不同（g 与 d），鼓或鼓励的意思。", "努": "nǔ 与 dǔ 声母不同（n 与 d），努力的意思，不是比输赢。", "组": "zǔ 与 dǔ 声母不同（z 与 d），组织或小组的意思。", "府": "fǔ 与 dǔ 声母不同（f 与 d），政府或官府的意思。", "杜": "dù（第四声）与 dǔ（第三声）声调不同，杜绝或姓杜的意思。"}, "sentence_index": null, "correct_answer": "赌"}, "level_3": {"options": [{"text": "赌", "is_correct": true, "explanation": "正确：“赌”与“钱”搭配，表示拿钱比输赢，符合句意。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”多指吹气或吹牛，不能说吹钱。"}, {"text": "画", "is_correct": false, "explanation": "搭配：“画”的宾语是图画，不能说画钱。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”需要文字作载体，钱不能被写，句子无法成立。"}], "explanations": {"赌": "正确：“赌”与“钱”搭配，表示拿钱比输赢，符合句意。", "吹": "搭配：“吹”多指吹气或吹牛，不能说吹钱。", "画": "搭配：“画”的宾语是图画，不能说画钱。", "写": "语义：“写”需要文字作载体，钱不能被写，句子无法成立。"}, "sentence_index": 6, "correct_answer": "赌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师赌了我的作业。", "explanation": "这里应该用〈批改〉。批改是给作业打分、改正错误，“赌”表示拿东西比输赢，不能用于作业。"}, {"text": "他赌了一下菜的味道。", "explanation": "这里应该用〈尝〉。尝是用嘴试味道，“赌”表示拿东西比输赢，不能表示品尝。"}, {"text": "妈妈赌了一锅粥。", "explanation": "这里应该用〈煮〉。煮是加热做饭，“赌”表示拿东西比输赢，不能用于烹饪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天在朋友家赌钱了两百块。", "corrected_sentence": "他昨天在朋友家赌了两百块。", "error_description": "“赌钱”已是一个词，后面不能再接数量宾语；“赌”后直接接“了两百块”即可，正确为“赌了两百块”，不要在“赌”后面再加“钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时赌过一次，后来再也不赌过了。", "corrected_sentence": "他年轻时赌过一次，后来再也不赌了。", "error_description": "“再也不”之后表示以后不再发生时，应说“不赌了”，不能用“赌过了”；“过”表示经历，与“再也不”的持续否定语气不符，正确为“再也不赌了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
