INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94326, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用财物作注，赌输赢；比喻拿东西冒险。", "primary_collocate": null, "pronunciation": "dǔ", "ipa": "tu˨˩˦", "syllable_count": 1, "sentences": [{"text": "他喜欢赌钱，常常输光工资。", "target_word": "赌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们赌一把，看谁先到。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把全部的钱都赌上了。", "target_word": "赌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王赌输了房子和车。", "target_word": "赌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别赌了，再赌下去你会更穷。", "target_word": "赌", "complexity_tier": "T3", "furigana": "bié dǔ le, zài dǔ xià qu nǐ huì gèng qióng", "sentence_source": "generated"}, {"text": "他赌的是比赛的输赢。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了这次机会，他赌上了自己的名声。", "target_word": "赌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他赌了一整晚。", "target_word": "赌", "complexity_tier": "T3", "furigana": "tā dǔ le yì zhěng wǎn", "sentence_source": "generated"}, {"text": "创业是在赌自己的将来。", "target_word": "赌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不想赌，这样做太冒险了。", "target_word": "赌", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赌了", "label": "体标（完成）"}, {"form": "赌过", "label": "体标（经历）"}, {"form": "赌着", "label": "体标（持续）"}, {"form": "賭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赌：用钱财比输赢，也比喻拿名声、将来等去冒险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ce9a55-ce32-4de2-b1f7-ff56f8f8bde6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94326, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赌", "is_correct": true, "explanation": "dǔ（第三声）是要找的词，意思是用财物比输赢，也比喻拿东西冒险。"}, {"text": "土", "is_correct": false, "explanation": "tǔ（第三声）与 dǔ 声母不同（t 与 d），意思是泥土。"}, {"text": "肚", "is_correct": false, "explanation": "dù（第四声）与 dǔ 声调不同，意思是肚子。"}, {"text": "都", "is_correct": false, "explanation": "dū（第一声）与 dǔ 声调不同，读 dū 时意思是首都。"}, {"text": "度", "is_correct": false, "explanation": "dù（第四声）与 dǔ 声调不同，意思是程度。"}, {"text": "督", "is_correct": false, "explanation": "dū（第一声）与 dǔ 声调不同，意思是监督。"}], "explanations": {"赌": "dǔ（第三声）是要找的词，意思是用财物比输赢，也比喻拿东西冒险。", "土": "tǔ（第三声）与 dǔ 声母不同（t 与 d），意思是泥土。", "肚": "dù（第四声）与 dǔ 声调不同，意思是肚子。", "都": "dū（第一声）与 dǔ 声调不同，读 dū 时意思是首都。", "度": "dù（第四声）与 dǔ 声调不同，意思是程度。", "督": "dū（第一声）与 dǔ 声调不同，意思是监督。"}, "sentence_index": null, "correct_answer": "赌"}, "level_3": {"options": [{"text": "赌", "is_correct": true, "explanation": "“赌”是动词，表示拿钱财比输赢，与“喜欢……钱，常常输光工资”相符。"}, {"text": "攒", "is_correct": false, "explanation": "语义：“攒”表示积蓄，与“常常输光工资”的结果相反。"}, {"text": "存", "is_correct": false, "explanation": "语义：“存”表示存钱，与“输光工资”的后果矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般不跟“钱”搭配，“喜欢吃钱”搭配不当。"}], "explanations": {"赌": "“赌”是动词，表示拿钱财比输赢，与“喜欢……钱，常常输光工资”相符。", "攒": "语义：“攒”表示积蓄，与“常常输光工资”的结果相反。", "存": "语义：“存”表示存钱，与“输光工资”的后果矛盾。", "吃": "搭配：“吃”一般不跟“钱”搭配，“喜欢吃钱”搭配不当。"}, "sentence_index": 0, "correct_answer": "赌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他赌咒发誓，说这辈子再也不碰钱。", "explanation": "这里的“赌”属于“赌咒”，表示发誓，是另一个意思，与“拿财物比输赢”不同。"}, {"text": "他赌了三年英语，终于考上了大学。", "explanation": "这里应该用〈学习〉。“赌”指拿财物或性命碰运气，不能用来说学习英语。"}, {"text": "他赌了一下午的数学题，把作业全部做完了。", "explanation": "这里应该用〈练习〉。“赌”指拿财物碰运气，不能用来说做题、练习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94326, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赌", "is_correct": true, "explanation": "dǔ（第三声）是要找的词，意思是用财物比输赢，也比喻拿东西冒险。"}, {"text": "杜", "is_correct": false, "explanation": "dù（第四声）与 dǔ 声调不同，意思是杜绝，也是姓氏。"}, {"text": "渡", "is_correct": false, "explanation": "dù（第四声）与 dǔ 声调不同，意思是渡河。"}, {"text": "镀", "is_correct": false, "explanation": "dù（第四声）与 dǔ 声调不同，意思是镀金。"}, {"text": "嘟", "is_correct": false, "explanation": "dū（第一声）与 dǔ 声调不同，意思是嘟嘴。"}], "explanations": {"赌": "dǔ（第三声）是要找的词，意思是用财物比输赢，也比喻拿东西冒险。", "杜": "dù（第四声）与 dǔ 声调不同，意思是杜绝，也是姓氏。", "渡": "dù（第四声）与 dǔ 声调不同，意思是渡河。", "镀": "dù（第四声）与 dǔ 声调不同，意思是镀金。", "嘟": "dū（第一声）与 dǔ 声调不同，意思是嘟嘴。"}, "sentence_index": null, "correct_answer": "赌"}, "level_3": {"options": [{"text": "赌", "is_correct": true, "explanation": "“赌上”表示拿东西冒险，与“为了这次机会”的语境相符。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”表示失去，与“为了这次机会”的目的相悖。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送上”一般用于送出具体的东西，不能搭配“名声”。"}, {"text": "抛", "is_correct": false, "explanation": "搭配：“抛”多用于抛弃、扔掉，与“名声”搭配不当。"}], "explanations": {"赌": "“赌上”表示拿东西冒险，与“为了这次机会”的语境相符。", "丢": "语义：“丢”表示失去，与“为了这次机会”的目的相悖。", "送": "搭配：“送上”一般用于送出具体的东西，不能搭配“名声”。", "抛": "搭配：“抛”多用于抛弃、扔掉，与“名声”搭配不当。"}, "sentence_index": 6, "correct_answer": "赌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他赌工作，养活了一家人。", "explanation": "这里应该用〈努力〉。“赌”指拿财物碰运气，不能用来说勤勉地工作。"}, {"text": "他赌气不吃饭，一个人躲在房间里。", "explanation": "这里的“赌”属于“赌气”，表示闹别扭，是另一个意思，与“拿财物比输赢”不同。"}, {"text": "他每天赌钢琴两个小时。", "explanation": "这里应该用〈练习〉。“赌”不能用来表示练习乐器，与“钢琴”搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常常钱赌，输光了工资。", "corrected_sentence": "他常常赌钱，输光了工资。", "error_description": "“赌钱”是动宾结构，宾语“钱”应放在“赌”之后，不能说“钱赌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不肯听劝，还在赌桌上赌过下去。", "corrected_sentence": "他不肯听劝，还在赌桌上赌下去。", "error_description": "“过”表示曾经经历，与表示持续延续的“下去”不能同用；应去掉“过”，说“赌下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
