INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94329, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94329, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迎接是高兴地去等着人来，或等着事情到来。", "primary_collocate": null, "pronunciation": "yíng jiē", "ipa": "iŋ˧˥ tɕje˥˥", "syllable_count": 2, "sentences": [{"text": "我们高高兴兴地迎接新年。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们站在门口迎接客人。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家笑着迎接新的一年。", "target_word": "迎接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们唱着歌迎接老师。", "target_word": "迎接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市挂满了灯笼迎接春节。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他张开双手迎接朋友。", "target_word": "迎接", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校准备迎接新同学。", "target_word": "迎接", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们用笑脸迎接每一天。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家在街边迎接运动员回来。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小镇的人们热情地迎接旅客。", "target_word": "迎接", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎接了", "label": "体标（了）"}, {"form": "迎接过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "高兴地迎候人或事到来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '803b8d38-3b31-4866-a82b-2e7f4534b9dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迎接", "is_correct": true, "explanation": "正确。“迎接”表示高兴地等着人或事到来，与“高高兴兴地”的语境相合。"}, {"text": "送别", "is_correct": false, "explanation": "语义：“送别”指送走离开的人，新年是到来的，不能说送别新年。"}, {"text": "接受", "is_correct": false, "explanation": "搭配：“接受”的对象多是礼物、批评、建议，不说“接受新年”。"}, {"text": "慰问", "is_correct": false, "explanation": "语义：“慰问”是对辛苦或遭遇困难的人表示关怀，不用于迎接新年。"}], "explanations": {"迎接": "正确。“迎接”表示高兴地等着人或事到来，与“高高兴兴地”的语境相合。", "送别": "语义：“送别”指送走离开的人，新年是到来的，不能说送别新年。", "接受": "搭配：“接受”的对象多是礼物、批评、建议，不说“接受新年”。", "慰问": "语义：“慰问”是对辛苦或遭遇困难的人表示关怀，不用于迎接新年。"}, "sentence_index": 0, "correct_answer": "迎接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家在车站迎接出发的朋友。", "explanation": "这里应该用〈欢送〉。迎接表示欢迎到来的人或事，朋友要出发离开，应说欢送。"}, {"text": "他迎接了桌上的那杯热茶。", "explanation": "这里应该用〈接过〉。迎接只用于接人或事到来，不能用于接取物品。"}, {"text": "他总是迎接老板的喜好。", "explanation": "这里是“迎合、讨好”的意思，“迎接”不能表示迎合，只用于接人或事到来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎接", "is_correct": true, "explanation": "正确。“迎接”表示欢迎新同学到来，与“准备”的语境相合。"}, {"text": "送走", "is_correct": false, "explanation": "语义：“送走”指送别离去的人，新同学是来入学的，与句意矛盾。"}, {"text": "告别", "is_correct": false, "explanation": "语义：“告别”是对要离开的人道别，不用于刚来的新同学。"}, {"text": "驾临", "is_correct": false, "explanation": "语义：“驾临”是敬称尊贵人士到某处，不能以新同学作为迎接的对象，与“学校准备”的句意不合。"}], "explanations": {"迎接": "正确。“迎接”表示欢迎新同学到来，与“准备”的语境相合。", "送走": "语义：“送走”指送别离去的人，新同学是来入学的，与句意矛盾。", "告别": "语义：“告别”是对要离开的人道别，不用于刚来的新同学。", "驾临": "语义：“驾临”是敬称尊贵人士到某处，不能以新同学作为迎接的对象，与“学校准备”的句意不合。"}, "sentence_index": 6, "correct_answer": "迎接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人们在除夕迎接旧年。", "explanation": "这里应该用〈告别〉。迎接只用于欢迎到来的人或事，旧年是要离去的，应说告别。"}, {"text": "他迎接了桌上的一本书。", "explanation": "这里应该用〈拿起〉。迎接只用于接人或事到来，不能用于拿取物品。"}, {"text": "我在超市迎接了一个熟人。", "explanation": "这里是偶然碰到的意思，“迎接”只表示有意去接或欢迎到来，不表示碰见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家在门口迎接客人过。", "corrected_sentence": "大家在门口迎接客人。", "error_description": "错误形式：“迎接客人过”。正确形式：“迎接客人”。“过”不能放在宾语之后，这句不需要体标，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经在车站迎接着远方的朋友。", "corrected_sentence": "他们曾经在车站迎接过远方的朋友。", "error_description": "错误形式：“迎接着远方的朋友”。正确形式：“迎接过远方的朋友”。“着”表示持续进行，与“曾经”所指的经历不合，应用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
