INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "间或是偶尔会这样，不是常常这样。", "primary_collocate": null, "pronunciation": "jiàn huò", "ipa": "tɕjɛn⁵¹ xuo⁵¹", "syllable_count": 2, "sentences": [{"text": "他平时很安静，间或讲个笑话。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空很蓝，间或飘过几朵白云。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里很静，间或传来几声咳嗽。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在家看书，间或出去走走。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上人不多，间或有一辆车开过。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她间或给我打个电话，说说最近的事。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在树下，间或看看手里的报纸。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得不大，间或夹着几声雷。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不爱喝酒，间或在朋友家喝一点。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议很长，他间或看一下手机。", "target_word": "间或", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "偶尔、不常发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '803b8d38-3b31-4866-a82b-2e7f4534b9dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与前半句“平时很安静”矛盾"}, {"text": "间或", "is_correct": true, "explanation": "间或表示偶尔才讲一次，与“平时很安静”的语境相符"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示每次都如此，与“平时很安静”矛盾"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，不用于说明平时的习惯"}], "explanations": {"一直": "语义：“一直”表示持续不断，与前半句“平时很安静”矛盾", "间或": "间或表示偶尔才讲一次，与“平时很安静”的语境相符", "总是": "语义：“总是”表示每次都如此，与“平时很安静”矛盾", "已经": "体貌：“已经”表示动作已经完成，不用于说明平时的习惯"}, "sentence_index": 0, "correct_answer": "间或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都间或晨跑。", "explanation": "这里应该用〈经常〉。间或表示偶尔、不常发生，与“每天都”的规律性相矛盾"}, {"text": "这一周他间或每天都准时下班，从未迟到。", "explanation": "这里应该用〈总是〉。间或表示偶尔，与“每天都”和“从未迟到”的每次如此相矛盾"}, {"text": "他从早到晚间或工作。", "explanation": "这里应该用〈一直〉。间或表示偶尔，与“从早到晚”的持续不断相冲突"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急切催促，与“坐在树下”的悠闲不合"}, {"text": "间或", "is_correct": true, "explanation": "间或表示偶尔看一下报纸，与“坐在树下”的悠闲相符"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”表示突然发生，与“坐在树下”的安适情境不合"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去的经历，不能描述眼下的动作"}], "explanations": {"赶紧": "语义：“赶紧”表示急切催促，与“坐在树下”的悠闲不合", "间或": "间或表示偶尔看一下报纸，与“坐在树下”的悠闲相符", "猛然": "语义：“猛然”表示突然发生，与“坐在树下”的安适情境不合", "曾经": "体貌：“曾经”指过去的经历，不能描述眼下的动作"}, "sentence_index": 6, "correct_answer": "间或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个周末都间或回老家看父母。", "explanation": "这里应该用〈时常〉。间或表示偶尔，与“每个周末都”的规律性相矛盾"}, {"text": "每逢节日，他都间或包饺子。", "explanation": "这里应该用〈常常〉。间或表示偶尔，与“每逢节日都”的规律性相矛盾"}, {"text": "他一天到晚间或玩手机。", "explanation": "这里应该用〈老是〉。间或表示偶尔，与“一天到晚”的持续不断相矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲间或了来这里看看。", "corrected_sentence": "我父亲间或来这里看看。", "error_description": "错误形式：“间或了来”；正确形式：“间或来”。间或是表示偶尔的副词，后面不能加“了”，直接接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他间或的去超市买东西。", "corrected_sentence": "他间或去超市买东西。", "error_description": "错误形式：“间或的去”；正确形式：“间或去”。间或是副词，后面不能加“的”，直接接动词", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8923383d-c832-470c-b4ad-d4044ec9cdde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94333, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低潮", "is_correct": true, "explanation": "低潮与“高潮”构成反义，指事情发展最低落、最平淡的阶段。"}, {"text": "序幕", "is_correct": false, "explanation": "序幕指正式开始前的开头部分，与“高潮”是先后的阶段，不构成反义。"}, {"text": "尾声", "is_correct": false, "explanation": "尾声指活动或故事结束前的收尾部分，不是与高潮相对的状态。"}, {"text": "开场", "is_correct": false, "explanation": "开场指一开始的部分，与“高潮”不是反义关系。"}], "correct_answer": "低潮", "explanations": {"低潮": "低潮与“高潮”构成反义，指事情发展最低落、最平淡的阶段。", "序幕": "序幕指正式开始前的开头部分，与“高潮”是先后的阶段，不构成反义。", "尾声": "尾声指活动或故事结束前的收尾部分，不是与高潮相对的状态。", "开场": "开场指一开始的部分，与“高潮”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94333, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低潮", "is_correct": true, "explanation": "低潮与“高潮”构成反义，指事情发展最低落、最平淡的阶段。"}, {"text": "前奏", "is_correct": false, "explanation": "前奏指正式开始前的引子，与“高潮”是先后的阶段，不构成反义。"}, {"text": "余波", "is_correct": false, "explanation": "余波指事情过后残留的影响，不是与高潮相对的阶段。"}, {"text": "开幕", "is_correct": false, "explanation": "开幕指活动开始的时刻，与“高潮”不是反义关系。"}], "correct_answer": "低潮", "explanations": {"低潮": "低潮与“高潮”构成反义，指事情发展最低落、最平淡的阶段。", "前奏": "前奏指正式开始前的引子，与“高潮”是先后的阶段，不构成反义。", "余波": "余波指事情过后残留的影响，不是与高潮相对的阶段。", "开幕": "开幕指活动开始的时刻，与“高潮”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "高潮是一件事最热闹、最精彩的时候。", "primary_collocate": null, "pronunciation": "gāo cháo", "ipa": "kɑʊ̯˥ ʈʂʰɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "晚会的高潮是大家一起唱歌。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会进行到高潮时，大家都站了起来。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节的高潮是除夕晚上。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的节日活动到了高潮，街上到处是人。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表演一到高潮，现场的人都大声叫好。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日会的高潮是切蛋糕的时候。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上八点，舞会进入了高潮。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年夏天的游园会，高潮总是在最后一晚。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们唱着歌，把晚会推向了高潮。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出的高潮过去后，不少人开始回家了。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "晚会、节日、演出中最热闹、气氛最好的时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94333, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场地", "is_correct": false, "explanation": "语义：“场地”指地方，不是活动的内容，说“场地是大家一起唱歌”句意不通。"}, {"text": "高潮", "is_correct": true, "explanation": "高潮指晚会最热闹的时候，填入后与“大家一起唱歌”的语境相符。"}, {"text": "门票", "is_correct": false, "explanation": "语义：“门票”是买来入场的凭证，不是活动本身，句意不通。"}, {"text": "经费", "is_correct": false, "explanation": "搭配：“经费”是用来支付的钱，不能说“经费是大家一起唱歌”。"}], "explanations": {"场地": "语义：“场地”指地方，不是活动的内容，说“场地是大家一起唱歌”句意不通。", "高潮": "高潮指晚会最热闹的时候，填入后与“大家一起唱歌”的语境相符。", "门票": "语义：“门票”是买来入场的凭证，不是活动本身，句意不通。", "经费": "搭配：“经费”是用来支付的钱，不能说“经费是大家一起唱歌”。"}, "sentence_index": 0, "correct_answer": "高潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条抛物线的高潮在第三象限。", "explanation": "这里应该用〈顶点〉。顶点指抛物线等曲线的最高或最低点，可以说“抛物线的顶点”；高潮指事情最精彩的阶段，不能用于数学曲线。"}, {"text": "去年的用水量在三月达到了高潮。", "explanation": "这里应该用〈峰值〉。峰值指数量达到的最高点，可以说“用水量达到峰值”；高潮指事情最精彩的阶段，不能用于用水量。"}, {"text": "春节前，物价高潮，大家都很担心。", "explanation": "这里应该用〈高涨〉。高涨指物价等不断上升，可以说“物价高涨”；高潮指事情最精彩的阶段，不能用来形容物价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午夜", "is_correct": false, "explanation": "语义：“午夜”是半夜十二点左右，与句中的“晚上八点”矛盾。"}, {"text": "高潮", "is_correct": true, "explanation": "高潮指舞会最热闹的时段，填入后与“晚上八点”的时间语境相符。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：“凌晨”指天快亮的时候，与“晚上八点”矛盾。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“进入”后面不接“开幕”，应说“舞会开幕了”。"}], "explanations": {"午夜": "语义：“午夜”是半夜十二点左右，与句中的“晚上八点”矛盾。", "高潮": "高潮指舞会最热闹的时段，填入后与“晚上八点”的时间语境相符。", "凌晨": "语义：“凌晨”指天快亮的时候，与“晚上八点”矛盾。", "开幕": "搭配：“进入”后面不接“开幕”，应说“舞会开幕了”。"}, "sentence_index": 6, "correct_answer": "高潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的效果在一小时后到了高潮。", "explanation": "这里应该用〈峰值〉。峰值指效果达到的最高点，可以说“药效达到峰值”；高潮指事情最精彩的阶段，不能用于药效。"}, {"text": "这座山的高潮很陡峭，很难攀登。", "explanation": "这里应该用〈峰顶〉。峰顶指山的最高处，可以说“山的峰顶很陡峭”；高潮指事情最精彩的阶段，不能用来形容山。"}, {"text": "他的体力在二十岁时到了高潮。", "explanation": "这里应该用〈巅峰〉。巅峰指能力、状态达到的最高点，可以说“体力到了巅峰”；高潮指事情最精彩的阶段，不能用于人的体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场节日晚会有一只很精彩的高潮。", "corrected_sentence": "这场节日晚会有一个很精彩的高潮。", "error_description": "量词错误：“高潮”应搭配“个”，说“一个很精彩的高潮”；写成“一只”是错的，“只”一般用于动物，不能修饰高潮。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场演出有一颗很精彩的高潮。", "corrected_sentence": "这场演出有一次很精彩的高潮。", "error_description": "量词错误：“高潮”可以说“一次很精彩的高潮”；写成“一颗”是错的，“颗”多用于圆形小物，不能用来计量高潮。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
