INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94334, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低潮", "is_correct": true, "explanation": "低潮与“高潮”构成反义，指事情发展最低落、最平淡的阶段。"}, {"text": "前奏", "is_correct": false, "explanation": "前奏指正式开始前的引子，与“高潮”是先后的阶段，不构成反义。"}, {"text": "余波", "is_correct": false, "explanation": "余波指事情过后残留的影响，不是与高潮相对的阶段。"}, {"text": "开幕", "is_correct": false, "explanation": "开幕指活动开始的时刻，与“高潮”不是反义关系。"}], "correct_answer": "低潮", "explanations": {"低潮": "低潮与“高潮”构成反义，指事情发展最低落、最平淡的阶段。", "前奏": "前奏指正式开始前的引子，与“高潮”是先后的阶段，不构成反义。", "余波": "余波指事情过后残留的影响，不是与高潮相对的阶段。", "开幕": "开幕指活动开始的时刻，与“高潮”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展中最紧张、最精彩的阶段。", "primary_collocate": null, "pronunciation": "gāo cháo", "ipa": "kɑʊ̯˥ ʈʂʰɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影的高潮很紧张，我一直看着屏幕。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事讲到高潮的时候，他突然不说了。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的高潮出现在最后五分钟。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说的高潮在第十章。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧快到高潮了，我们都不想关电视。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲到故事的高潮，突然停了下来。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场球赛的高潮，是最后一个进球。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把故事的高潮写得非常精彩。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看过这部电影的人，都忘不了它的高潮。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的高潮过后，故事很快就结束了。", "target_word": "高潮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "故事、电影、比赛发展中最紧张、最精彩的阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "字幕", "is_correct": false, "explanation": "语义：“字幕”是屏幕上的文字，不能说它“很紧张”，句意不通。"}, {"text": "高潮", "is_correct": true, "explanation": "高潮指情节最紧张精彩的阶段，填入后与“很紧张”和“看着屏幕”相符。"}, {"text": "片名", "is_correct": false, "explanation": "语义：“片名”是电影的名字，没有紧张的状态，句意不通。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：“紧张”不能用来形容票价，票价只说贵或便宜。"}], "explanations": {"字幕": "语义：“字幕”是屏幕上的文字，不能说它“很紧张”，句意不通。", "高潮": "高潮指情节最紧张精彩的阶段，填入后与“很紧张”和“看着屏幕”相符。", "片名": "语义：“片名”是电影的名字，没有紧张的状态，句意不通。", "票价": "搭配：“紧张”不能用来形容票价，票价只说贵或便宜。"}, "sentence_index": 0, "correct_answer": "高潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小说的高潮是第二章埋下的线索。", "explanation": "这里应该用〈伏笔〉。伏笔指前文为后文埋下的线索，可以说“第二章埋下伏笔”；高潮指情节最精彩的阶段，不能指线索。"}, {"text": "这本小说的高潮是前面三章，都在介绍背景。", "explanation": "这里应该用〈铺垫〉。铺垫指为后面的情节做准备，可以说“前面三章都是铺垫”；高潮指情节最精彩的阶段，前面三章只介绍背景，不能称为高潮。"}, {"text": "这本小说的高潮只是个开头，人物还没有出场。", "explanation": "这里应该用〈开端〉。开端指故事一开始的部分，可以说“故事的开端很平静”；高潮指情节最精彩的阶段，不能指开头部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁判", "is_correct": false, "explanation": "语义：“裁判”是人，不能说“裁判是最后一个进球”，句意不通。"}, {"text": "高潮", "is_correct": true, "explanation": "高潮指比赛最紧张精彩的时刻，填入后与“最后一个进球”相符。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“观众”是看比赛的人，不会是进球本身，句意不通。"}, {"text": "球票", "is_correct": false, "explanation": "搭配：“球票”是用来买的，不能说“球票是最后一个进球”。"}], "explanations": {"裁判": "语义：“裁判”是人，不能说“裁判是最后一个进球”，句意不通。", "高潮": "高潮指比赛最紧张精彩的时刻，填入后与“最后一个进球”相符。", "观众": "语义：“观众”是看比赛的人，不会是进球本身，句意不通。", "球票": "搭配：“球票”是用来买的，不能说“球票是最后一个进球”。"}, "sentence_index": 6, "correct_answer": "高潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本小说的字数在第十章达到了高潮。", "explanation": "这里应该用〈峰值〉。峰值指数量达到的最高点，可以说“字数达到峰值”；高潮指情节最精彩的阶段，不能用于字数。"}, {"text": "这座雪山的高潮很陡，很难攀登。", "explanation": "这里应该用〈峰顶〉。峰顶指山的最高处，可以说“雪山的峰顶很陡”；高潮指情节最精彩的阶段，不能指山的最高处。"}, {"text": "他的体力在二十岁时到了高潮，之后慢慢下降。", "explanation": "这里应该用〈巅峰〉。巅峰指能力、状态达到的最高点，可以说“体力到了巅峰”；高潮指情节最精彩的阶段，不能用于人的体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说有一座很精彩的高潮。", "corrected_sentence": "这部小说有一个很精彩的高潮。", "error_description": "量词错误：“高潮”应搭配“个”，说“一个很精彩的高潮”；写成“一座”是错的，“座”多用于山、桥、建筑等，不能用于高潮。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场比赛有一颗精彩的高潮。", "corrected_sentence": "这场比赛有一个精彩的高潮。", "error_description": "量词错误：“高潮”应搭配“个”，说“一个精彩的高潮”；写成“一颗”是错的，“颗”多用于圆形小物，不能用于高潮。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94335, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良好", "is_correct": true, "explanation": "良好与“不良”意义相反，指好的、对人有益的。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂与“不良”无反义关系，指事情繁多或难以理解。"}, {"text": "安静", "is_correct": false, "explanation": "安静与“不良”无反义关系，指没有声音或状态平和。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴与“不良”无反义关系，指愉快的心情。"}], "correct_answer": "良好", "explanations": {"良好": "良好与“不良”意义相反，指好的、对人有益的。", "复杂": "复杂与“不良”无反义关系，指事情繁多或难以理解。", "安静": "安静与“不良”无反义关系，指没有声音或状态平和。", "高兴": "高兴与“不良”无反义关系，指愉快的心情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94335, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优良", "is_correct": true, "explanation": "优良与“不良”意义相反，指质量好、品行好。"}, {"text": "简单", "is_correct": false, "explanation": "简单与“不良”无反义关系，指不复杂。"}, {"text": "吵闹", "is_correct": false, "explanation": "吵闹与“不良”无反义关系，指声音大、乱哄哄。"}, {"text": "冷淡", "is_correct": false, "explanation": "冷淡与“不良”无反义关系，指态度不热情。"}], "correct_answer": "优良", "explanations": {"优良": "优良与“不良”意义相反，指质量好、品行好。", "简单": "简单与“不良”无反义关系，指不复杂。", "吵闹": "吵闹与“不良”无反义关系，指声音大、乱哄哄。", "冷淡": "冷淡与“不良”无反义关系，指态度不热情。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94335, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不良是不好，对人没有好处。", "primary_collocate": null, "pronunciation": "bù liáng", "ipa": "pu˥˩ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "抽烟是一种不良习惯。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熬夜对身体有不良影响。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的不良情绪影响了大家。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要改掉这些不良的生活习惯。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间玩手机会带来不良后果。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不良习惯很难改，但是可以改。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说坐姿不良会让背很痛。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭太快是不良的饮食习惯。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡眠不良，白天总是没精神。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母要让孩子远离不良习惯。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不良习惯", "label": "复合"}], "register": "书面", "sense_fingerprint": "不良：不好、对人没有好处，多修饰习惯、影响、情绪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94335, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不良", "is_correct": true, "explanation": "不良 bù liáng 指不好、对人没有好处，是目标词。"}, {"text": "不灵", "is_correct": false, "explanation": "不灵 bù líng 与 不良 韵母不同（ing 与 ang），意思是不灵活、不管用。"}, {"text": "不亮", "is_correct": false, "explanation": "亮 liàng 与 良 liáng 声调不同（第四声与第二声），不亮意思是不明亮。"}, {"text": "不祥", "is_correct": false, "explanation": "祥 xiáng 与 良 liáng 声母不同（x 与 l），意思是不吉利。"}], "explanations": {"不良": "不良 bù liáng 指不好、对人没有好处，是目标词。", "不灵": "不灵 bù líng 与 不良 韵母不同（ing 与 ang），意思是不灵活、不管用。", "不亮": "亮 liàng 与 良 liáng 声调不同（第四声与第二声），不亮意思是不明亮。", "不祥": "祥 xiáng 与 良 liáng 声母不同（x 与 l），意思是不吉利。"}, "sentence_index": null, "correct_answer": "不良"}, "level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "正确：不良习惯指不好的、对身体或他人有害的习惯。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线、颜色，不能修饰“习惯”。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”指空间广大，不能形容习惯。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写外形，不能用来修饰抽象的习惯。"}], "explanations": {"不良": "正确：不良习惯指不好的、对身体或他人有害的习惯。", "明亮": "搭配：“明亮”形容光线、颜色，不能修饰“习惯”。", "辽阔": "语义：“辽阔”指空间广大，不能形容习惯。", "高大": "体貌：“高大”描写外形，不能用来修饰抽象的习惯。"}, "sentence_index": 0, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份设计很不良，评委们都给了最高分。", "explanation": "这里应该用〈精美〉。不良表示不好、有害，设计“很不良”却获最高分，前后自相矛盾。"}, {"text": "他的口语很不良，每次发言都让大家惊喜。", "explanation": "这里应该用〈出色〉。不良表示不好、有害，不能用来夸人的口语好。"}, {"text": "这种锻炼对身体很不良，医生却建议大家多做。", "explanation": "这里应该用〈有益〉。不良表示有害，说锻炼对身体“很不良”却又建议多做，意思自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "正确：坐姿不良指姿势不正确、对身体有害。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”形容声音、笑容，不能修饰“坐姿”。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能修饰“坐姿”。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”指液体或眼神透明，不能形容坐姿。"}], "explanations": {"不良": "正确：坐姿不良指姿势不正确、对身体有害。", "甜美": "搭配：“甜美”形容声音、笑容，不能修饰“坐姿”。", "响亮": "搭配：“响亮”形容声音，不能修饰“坐姿”。", "清澈": "语义：“清澈”指液体或眼神透明，不能形容坐姿。"}, "sentence_index": 6, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的成绩很不良，老师在全班表扬了她。", "explanation": "这里应该用〈优秀〉。不良表示不好、有害，成绩“很不良”却受到表扬，前后矛盾。"}, {"text": "早睡早起是一种不良习惯，大家都应该坚持。", "explanation": "这里应该用〈良好〉。早睡早起有益健康，不能称为“不良”，说“不良习惯”意思正相反。"}, {"text": "这家餐厅的服务很不良，客人们都赞不绝口。", "explanation": "这里应该用〈周到〉。不良表示不好、有害，不能用来夸服务好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期久坐对身体很不良影响。", "corrected_sentence": "长期久坐对身体有不良影响。", "error_description": "程度副词位置错误：“很”不能直接修饰名词前的“不良”（中间无“的”），“不良影响”是固定说法，应去掉“很”，说“有不良影响”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把这些很不良习惯改掉了。", "corrected_sentence": "他终于把这些不良习惯改掉了。", "error_description": "程度副词位置错误：“很”直接插在“这些”之后、修饰名词前的“不良”（中间无“的”），不通顺，应删去“很”，说“这些不良习惯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94336, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良好", "is_correct": true, "explanation": "良好与“不良”意义相反，指好的、令人满意的。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚与“不良”无反义关系，指明白、不模糊。"}, {"text": "暖和", "is_correct": false, "explanation": "暖和与“不良”无反义关系，指温度适宜、有温度。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋与“不良”无反义关系，指努力、不懒惰。"}], "correct_answer": "良好", "explanations": {"良好": "良好与“不良”意义相反，指好的、令人满意的。", "清楚": "清楚与“不良”无反义关系，指明白、不模糊。", "暖和": "暖和与“不良”无反义关系，指温度适宜、有温度。", "勤奋": "勤奋与“不良”无反义关系，指努力、不懒惰。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94336, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优良", "is_correct": true, "explanation": "优良与“不良”意义相反，指质量好、水平高。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速与“不良”无反义关系，指速度快。"}, {"text": "凶猛", "is_correct": false, "explanation": "凶猛与“不良”无反义关系，指猛烈、有攻击性。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭与“不良”无反义关系，指坡面几乎直立。"}], "correct_answer": "优良", "explanations": {"优良": "优良与“不良”意义相反，指质量好、水平高。", "迅速": "迅速与“不良”无反义关系，指速度快。", "凶猛": "凶猛与“不良”无反义关系，指猛烈、有攻击性。", "陡峭": "陡峭与“不良”无反义关系，指坡面几乎直立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94336, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不好的；有害的。", "primary_collocate": null, "pronunciation": "bù liáng", "ipa": "pu˥˩ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种药可能有不良反应。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我没有不良用心。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多不良信息。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不良商家常常卖假货。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些不良信息对孩子有害。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不应该看不良内容。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，他和不良少年来往过。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，他有不良反应。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不良广告会让小孩学坏。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家不要看不良网站。", "target_word": "不良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不良反应", "label": "复合"}], "register": "书面", "sense_fingerprint": "不良：不好的、有害的，多修饰反应、信息、用心、商家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94336, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不良", "is_correct": true, "explanation": "不良 bù liáng 指不好的、有害的，是目标词。"}, {"text": "不灵", "is_correct": false, "explanation": "不灵 bù líng 与 不良 韵母不同（ing 与 ang），意思是不灵活、不管用。"}, {"text": "不亮", "is_correct": false, "explanation": "亮 liàng 与 良 liáng 声调不同（第四声与第二声），不亮意思是不明亮。"}, {"text": "不祥", "is_correct": false, "explanation": "祥 xiáng 与 良 liáng 声母不同（x 与 l），意思是不吉利。"}], "explanations": {"不良": "不良 bù liáng 指不好的、有害的，是目标词。", "不灵": "不灵 bù líng 与 不良 韵母不同（ing 与 ang），意思是不灵活、不管用。", "不亮": "亮 liàng 与 良 liáng 声调不同（第四声与第二声），不亮意思是不明亮。", "不祥": "祥 xiáng 与 良 liáng 声母不同（x 与 l），意思是不吉利。"}, "sentence_index": null, "correct_answer": "不良"}, "level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "正确：不良反应指药物引起的有害反应，是这里的固定搭配。"}, {"text": "绚丽", "is_correct": false, "explanation": "语义：“绚丽”形容色彩鲜艳，不能指药物的反应。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能与“反应”搭配。"}, {"text": "悠长", "is_correct": false, "explanation": "语义：“悠长”指时间或声音长久，不能修饰药物反应。"}], "explanations": {"不良": "正确：不良反应指药物引起的有害反应，是这里的固定搭配。", "绚丽": "语义：“绚丽”形容色彩鲜艳，不能指药物的反应。", "清脆": "搭配：“清脆”形容声音，不能与“反应”搭配。", "悠长": "语义：“悠长”指时间或声音长久，不能修饰药物反应。"}, "sentence_index": 0, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店的商品很不良，大家都抢着买。", "explanation": "这里应该用〈优质〉。不良表示不好、有害，不能用来说商品好、大家抢着买。"}, {"text": "这种运动对心脏很不良，医生却建议大家每天做。", "explanation": "这里应该用〈有益〉。不良表示有害，说运动对心脏“很不良”却又建议每天做，意思自相矛盾。"}, {"text": "这位老师的讲课很不良，学生们都听得很入迷。", "explanation": "这里应该用〈生动〉。不良表示不好，不能用来夸讲课好、学生听得入迷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "正确：不良少年指行为有害、品行不好的青少年。"}, {"text": "碧绿", "is_correct": false, "explanation": "体貌：“碧绿”形容颜色，不能用来描写少年。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不能修饰“少年”。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境，不能用于形容人。"}], "explanations": {"不良": "正确：不良少年指行为有害、品行不好的青少年。", "碧绿": "体貌：“碧绿”形容颜色，不能用来描写少年。", "沙哑": "搭配：“沙哑”形容嗓音，不能修饰“少年”。", "潮湿": "语义：“潮湿”形容环境，不能用于形容人。"}, "sentence_index": 6, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的不良方案被大家一致通过，都很满意。", "explanation": "这里应该用〈妙计〉。不良表示不好、有害，不能用来形容方案好。"}, {"text": "他每天读书一小时，这种不良习惯让他进步很快。", "explanation": "这里应该用〈好〉。读书有益，应说〈好习惯〉，不能用“不良习惯”来形容。"}, {"text": "这台机器的运行很不良，工人们都放心地使用。", "explanation": "这里应该用〈稳定〉。不良表示有害或不好，不能说机器运行“很不良”却让人放心使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服用这种药后，他出现了一种很不良反应。", "corrected_sentence": "服用这种药后，他出现了一种不良反应。", "error_description": "程度副词位置错误：“很”插在量词短语“一种”之后、修饰名词前的“不良”（中间无“的”），不通顺，应删去“很”，说“一种不良反应”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子在网上接触到的很不良信息应该及时过滤。", "corrected_sentence": "孩子在网上接触到的不良信息应该及时过滤。", "error_description": "程度副词位置错误：“很”直接修饰名词前的“不良”（中间无“的”）不通顺，“不良信息”是固定说法，应去掉“很”，说“不良信息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
