INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94337, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不许是不让做，不可以做。", "primary_collocate": null, "pronunciation": "bù xǔ", "ipa": "pu˥˩ ɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈不许我晚上玩手机。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师不许学生在教室里吃东西。", "target_word": "不许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里不许停车。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸不许弟弟一个人出门。", "target_word": "不许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里不许大声说话。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不许别人动他的东西。", "target_word": "不许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试的时候不许看手机。", "target_word": "不许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶不许我们浪费米饭。", "target_word": "不许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不许员工迟到。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家不许养狗。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不让别人做某事，不可以做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不许", "is_correct": true, "explanation": "正确：「不许」表示禁止，妈妈禁止我晚上玩手机，句意通顺。"}, {"text": "修", "is_correct": false, "explanation": "搭配：「修」的对象是器物，不能接「我晚上玩手机」这类动作。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：「祝贺」需要值得庆贺的事，「晚上玩手机」不是喜事，句意不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」的对象是物体表面，不能接「我晚上玩手机」这类动作。"}], "explanations": {"不许": "正确：「不许」表示禁止，妈妈禁止我晚上玩手机，句意通顺。", "修": "搭配：「修」的对象是器物，不能接「我晚上玩手机」这类动作。", "祝贺": "语义：「祝贺」需要值得庆贺的事，「晚上玩手机」不是喜事，句意不通。", "擦": "搭配：「擦」的对象是物体表面，不能接「我晚上玩手机」这类动作。"}, "sentence_index": 0, "correct_answer": "不许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个办法不许，我们换一个吧。", "explanation": "这里应该用〈不行〉。不许表示禁止别人做事；说办法不可行要用不行。"}, {"text": "我不许这道题的答案。", "explanation": "这里应该用〈不知道〉。不许禁止的是人的行为，不能用于答案；说不知道要用不知道。"}, {"text": "他不许时间吃午饭。", "explanation": "这里应该用〈没有〉。不许后面接禁止的行为，不能接「时间」这类名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不许", "is_correct": true, "explanation": "正确：「考试的时候不许看手机」表示禁止，句意通顺。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是场所，不能接「看手机」这类动作。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：「剪」的对象是有形物品，不能接「看手机」。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指燃烧或加热，与「考试的时候看手机」的语境无关。"}], "explanations": {"不许": "正确：「考试的时候不许看手机」表示禁止，句意通顺。", "打扫": "搭配：「打扫」的对象是场所，不能接「看手机」这类动作。", "剪": "搭配：「剪」的对象是有形物品，不能接「看手机」。", "烧": "语义：「烧」指燃烧或加热，与「考试的时候看手机」的语境无关。"}, "sentence_index": 6, "correct_answer": "不许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不许你的意见。", "explanation": "这里应该用〈不同意〉。不许的对象是人的行为，不能用于意见。"}, {"text": "这份报告不许要求。", "explanation": "这里应该用〈不符合〉。不许表示禁止，不表示与标准不一致。"}, {"text": "这支笔不许那支好用。", "explanation": "这里应该用〈不如〉。不许表示禁止，不表示比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷不许了我们在屋里抽烟。", "corrected_sentence": "爷爷不许我们在屋里抽烟。", "error_description": "「不许」后面不能加「了」，「了」表示完成，而禁止是持续的状态；应删去「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐被不许弟弟碰她的书。", "corrected_sentence": "姐姐不许弟弟碰她的书。", "error_description": "「不许」是动词，不能与「被」连用；「被」字句要求动词表示被动，这里应删去「被」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
