INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不允许；禁止。", "primary_collocate": null, "pronunciation": "bù xǔ", "ipa": "pu˥˩ ɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "图书馆里不许吃东西。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间不许抽烟。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "游泳池边不许跑步。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校不许学生带手机来。", "target_word": "不许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车时不许打电话。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们不许孩子看太久电视。", "target_word": "不许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里不许拍照。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生不许他喝酒。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸不许我晚回家。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园里不许带狗进来。", "target_word": "不许", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不允许，禁止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9286f32c-8c24-46f4-87e2-fe6cffd11487') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不许", "is_correct": true, "explanation": "正确：「图书馆里不许吃东西」表示禁止，句意通顺。"}, {"text": "修", "is_correct": false, "explanation": "搭配：「修」的对象是器物，不能接「吃东西」这类动作。"}, {"text": "擦", "is_correct": false, "explanation": "语义：「擦」指擦拭表面，与「图书馆里吃东西」无关，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是场所，不能接「吃东西」这类动作。"}], "explanations": {"不许": "正确：「图书馆里不许吃东西」表示禁止，句意通顺。", "修": "搭配：「修」的对象是器物，不能接「吃东西」这类动作。", "擦": "语义：「擦」指擦拭表面，与「图书馆里吃东西」无关，句意不通。", "打扫": "搭配：「打扫」的对象是场所，不能接「吃东西」这类动作。"}, "sentence_index": 0, "correct_answer": "不许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不许那道数学题。", "explanation": "这里应该用〈不会〉。不许禁止的是人的行为，不能用于题目；说不会做某题要用不会。"}, {"text": "他今天心情不许。", "explanation": "这里应该用〈不好〉。不许表示禁止，形容心情不佳要用不好。"}, {"text": "这个汤不许，太咸了。", "explanation": "这里应该用〈不好喝〉。不许表示禁止，形容味道差要用不好喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不许", "is_correct": true, "explanation": "正确：「这里不许拍照」表示禁止，句意通顺。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：「搬」的对象是物体，不能接「拍照」这类动作。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：「挂」的对象是物品，不能接「拍照」。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」指丢弃，与「拍照」的动作毫不相干，句意不通。"}], "explanations": {"不许": "正确：「这里不许拍照」表示禁止，句意通顺。", "搬": "搭配：「搬」的对象是物体，不能接「拍照」这类动作。", "挂": "搭配：「挂」的对象是物品，不能接「拍照」。", "扔": "语义：「扔」指丢弃，与「拍照」的动作毫不相干，句意不通。"}, "sentence_index": 6, "correct_answer": "不许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不许这个决定。", "explanation": "这里应该用〈不同意〉。不许表示禁止别人做事，不能用于决定。"}, {"text": "这件衣服不许尺码。", "explanation": "这里应该用〈不符合〉。不许表示禁止，不表示与标准不一致。"}, {"text": "这家店的菜不许那家好。", "explanation": "这里应该用〈不如〉。不许表示禁止，不表示比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长不许着学生在走廊里跑。", "corrected_sentence": "校长不许学生在走廊里跑。", "error_description": "「着」表示持续的状态，不能加在「不许」后面；应删去「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆里不许过大声讲话。", "corrected_sentence": "图书馆里不许大声讲话。", "error_description": "「过」表示经历，不能加在「不许」后面；应删去「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfc4315-cda3-4a13-8154-597d107ef41e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
