INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94339, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中午是一天里太阳最高的时候，大约在十二点。", "primary_collocate": null, "pronunciation": "zhōng wǔ", "ipa": "ʈʂʊŋ˥ u˨˩˦", "syllable_count": 2, "sentences": [{"text": "中午太阳很高，外面特别热。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午的太阳照在身上，非常热。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午天气太热，孩子们都不想出去玩。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午阳光太强，你最好戴上帽子。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午的时候，街上的人很少。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的中午，我喜欢待在家里。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午太阳最高，影子变得很短。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天中午都要睡一会儿。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天中午我没有吃饭，现在很饿。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们中午在学校吃饭。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大中午", "label": "复合"}], "register": "中性", "sense_fingerprint": "一天里太阳最高的时候，约十二点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94339, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中午", "is_correct": true, "explanation": "中午（zhōng wǔ）指一天里十二点前后的时段，是正确答案。"}, {"text": "中雨", "is_correct": false, "explanation": "wǔ 与 yǔ 韵母不同（u 与 ü），中雨指中等程度的降雨，不是中午。"}, {"text": "中古", "is_correct": false, "explanation": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），中古指历史上的中世纪，不是中午。"}, {"text": "中土", "is_correct": false, "explanation": "第二音节 wǔ 与 tǔ 声母不同（w 与 t），中土指中原地区，不是中午。"}, {"text": "钟鼓", "is_correct": false, "explanation": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），钟鼓指钟和鼓，不是中午。"}], "explanations": {"中午": "中午（zhōng wǔ）指一天里十二点前后的时段，是正确答案。", "中雨": "wǔ 与 yǔ 韵母不同（u 与 ü），中雨指中等程度的降雨，不是中午。", "中古": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），中古指历史上的中世纪，不是中午。", "中土": "第二音节 wǔ 与 tǔ 声母不同（w 与 t），中土指中原地区，不是中午。", "钟鼓": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），钟鼓指钟和鼓，不是中午。"}, "sentence_index": null, "correct_answer": "中午"}, "level_3": {"options": [{"text": "中午", "is_correct": true, "explanation": "正确：中午指一天里太阳最高的时候，与“太阳很高”相符。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：傍晚时太阳快要落山，与“太阳很高”矛盾。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜没有太阳，与“太阳很高、外面特别热”矛盾。"}, {"text": "冬天", "is_correct": false, "explanation": "搭配：“冬天”与“外面特别热”搭配不当，冬天一般说“外面很冷”。"}], "explanations": {"中午": "正确：中午指一天里太阳最高的时候，与“太阳很高”相符。", "傍晚": "语义：傍晚时太阳快要落山，与“太阳很高”矛盾。", "深夜": "语义：深夜没有太阳，与“太阳很高、外面特别热”矛盾。", "冬天": "搭配：“冬天”与“外面特别热”搭配不当，冬天一般说“外面很冷”。"}, "sentence_index": 0, "correct_answer": "中午"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们中午三点在学校开会。", "explanation": "这里应该用〈下午〉。中午指十二点前后，三点要说下午。"}, {"text": "我每天中午七点起床。", "explanation": "这里应该用〈早上〉。中午指十二点前后，七点起床要说早上。"}, {"text": "妈妈中午十点关灯睡觉。", "explanation": "这里应该用〈晚上〉。中午指十二点前后，十点关灯睡觉要说晚上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中午", "is_correct": true, "explanation": "正确：中午指一天里太阳最高的时候，与“太阳最高，影子变短”相符。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：黎明时太阳刚升起，还没有到最高，与“太阳最高”矛盾。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚没有太阳，影子也看不出长短，与“太阳最高”矛盾。"}, {"text": "日落", "is_correct": false, "explanation": "搭配：“日落”指太阳落下的时候，与“太阳最高”搭配不通。"}], "explanations": {"中午": "正确：中午指一天里太阳最高的时候，与“太阳最高，影子变短”相符。", "黎明": "语义：黎明时太阳刚升起，还没有到最高，与“太阳最高”矛盾。", "夜晚": "语义：夜晚没有太阳，影子也看不出长短，与“太阳最高”矛盾。", "日落": "搭配：“日落”指太阳落下的时候，与“太阳最高”搭配不通。"}, "sentence_index": 6, "correct_answer": "中午"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的中午很好吃。", "explanation": "这里应该用〈午饭〉。中午是时间词，指吃的饭要说午饭。"}, {"text": "我们每天中午四点起床。", "explanation": "这里应该用〈凌晨〉。中午指十二点前后，四点起床要说凌晨。"}, {"text": "中午六点我们吃饭。", "explanation": "这里应该用〈傍晚〉。中午指十二点前后，六点吃饭要说傍晚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我全个中午都在图书馆看书。", "corrected_sentence": "我整个中午都在图书馆看书。", "error_description": "错误：修饰“中午”时要用“整个”，“全个”不能这样用。应说“整个中午”，不能说“全个中午”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他全个中午都在操场踢球。", "corrected_sentence": "他整个中午都在操场踢球。", "error_description": "错误：修饰“中午”时要用“整个”，“全个”不能这样用。应说“整个中午”，不能说“全个中午”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
