INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "白天十二点前后的一段时间。", "primary_collocate": null, "pronunciation": "zhōng wǔ", "ipa": "ʈʂʊŋ˥ u˨˩˦", "syllable_count": 2, "sentences": [{"text": "中午十二点，我们一起去吃饭。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他中午休息两个小时。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天中午你有空吗？", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议中午十二点开始，一点结束。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈中午常常给我打电话。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午公司旁边的饭馆人很多。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午吃完饭，我们去公园走走。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天中午我在图书馆看书。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上我喝了咖啡，中午喝了茶。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午的休息时间只有一个小时。", "target_word": "中午", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大中午", "label": "复合"}], "register": "中性", "sense_fingerprint": "白天十二点前后的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94340, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中午", "is_correct": true, "explanation": "中午（zhōng wǔ）指白天十二点前后的一段时间，是正确答案。"}, {"text": "中雨", "is_correct": false, "explanation": "wǔ 与 yǔ 韵母不同（u 与 ü），中雨指中等程度的降雨，不是中午。"}, {"text": "中古", "is_correct": false, "explanation": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），中古指历史上的中世纪，不是中午。"}, {"text": "中土", "is_correct": false, "explanation": "第二音节 wǔ 与 tǔ 声母不同（w 与 t），中土指中原地区，不是中午。"}, {"text": "钟鼓", "is_correct": false, "explanation": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），钟鼓指钟和鼓，不是中午。"}], "explanations": {"中午": "中午（zhōng wǔ）指白天十二点前后的一段时间，是正确答案。", "中雨": "wǔ 与 yǔ 韵母不同（u 与 ü），中雨指中等程度的降雨，不是中午。", "中古": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），中古指历史上的中世纪，不是中午。", "中土": "第二音节 wǔ 与 tǔ 声母不同（w 与 t），中土指中原地区，不是中午。", "钟鼓": "第二音节 wǔ 与 gǔ 声母不同（w 与 g），钟鼓指钟和鼓，不是中午。"}, "sentence_index": null, "correct_answer": "中午"}, "level_3": {"options": [{"text": "中午", "is_correct": true, "explanation": "正确：中午指十二点前后，与“十二点”相符。"}, {"text": "早上", "is_correct": false, "explanation": "语义：早上一般指清晨到上午，不是十二点，与“十二点”矛盾。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨指天刚亮的时候，与“十二点”矛盾。"}, {"text": "下午", "is_correct": false, "explanation": "搭配：“下午十二点”搭配不通，十二点应说“中午”。"}], "explanations": {"中午": "正确：中午指十二点前后，与“十二点”相符。", "早上": "语义：早上一般指清晨到上午，不是十二点，与“十二点”矛盾。", "清晨": "语义：清晨指天刚亮的时候，与“十二点”矛盾。", "下午": "搭配：“下午十二点”搭配不通，十二点应说“中午”。"}, "sentence_index": 0, "correct_answer": "中午"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议中午七点开始，九点结束。", "explanation": "这里应该用〈晚上〉。中午指十二点前后，七点开会要说晚上。"}, {"text": "我中午八点上班。", "explanation": "这里应该用〈早上〉。中午指十二点前后，八点上班要说早上。"}, {"text": "他中午三点还在工作。", "explanation": "这里应该用〈下午〉。中午指十二点前后，三点还在工作要说下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中午", "is_correct": true, "explanation": "正确：中午指十二点前后，吃完饭的时间与这一语境相符。"}, {"text": "深夜", "is_correct": false, "explanation": "搭配：深夜吃完饭再去公园，与“去公园走走”搭配不当，公园通常已关门。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：凌晨人大多还在睡觉，不会刚吃完饭就去公园走走。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：黎明时天刚亮，不会在这个时候吃完饭后去公园，与语境不符。"}], "explanations": {"中午": "正确：中午指十二点前后，吃完饭的时间与这一语境相符。", "深夜": "搭配：深夜吃完饭再去公园，与“去公园走走”搭配不当，公园通常已关门。", "凌晨": "语义：凌晨人大多还在睡觉，不会刚吃完饭就去公园走走。", "黎明": "语义：黎明时天刚亮，不会在这个时候吃完饭后去公园，与语境不符。"}, "sentence_index": 6, "correct_answer": "中午"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的中午很丰盛。", "explanation": "这里应该用〈午饭〉。中午是时间词，指吃的饭要说午饭。"}, {"text": "中午三点的会议推迟了。", "explanation": "这里应该用〈下午〉。中午指十二点前后，三点要说下午。"}, {"text": "我中午十点写作业。", "explanation": "这里应该用〈上午〉。中午指十二点前后，十点写作业要说上午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天全个中午我都在门口等你。", "corrected_sentence": "明天整个中午我都在门口等你。", "error_description": "错误：修饰“中午”时要用“整个”，“全个”不能这样用。应说“整个中午”，不能说“全个中午”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她全个中午都在办公室工作。", "corrected_sentence": "她整个中午都在办公室工作。", "error_description": "错误：修饰“中午”时要用“整个”，“全个”不能这样用。应说“整个中午”，不能说“全个中午”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
