INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里悲痛难过。", "primary_collocate": null, "pronunciation": "shāng xīn", "ipa": "ʂaŋ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "奶奶去世后，全家人都很伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说起那件往事，仍然伤心不已。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友离开了，他伤心了很久。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到家乡被大水淹了，大家都很伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一提到儿子，就伤心起来。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个让人伤心的消息。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伤心地离开了这座城市。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去工作的那天，爸爸特别伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让她再想起伤心的事了。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说老师生病了，同学们都很伤心。", "target_word": "伤心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伤心事", "label": "复合"}, {"form": "傷心", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到不幸或损失而心里悲痛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9550a99-05ab-43a0-8580-e05f022f057f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤心", "is_correct": true, "explanation": "“伤心”表示遇到不幸而心里悲痛，与“奶奶去世后”的语境相符。"}, {"text": "满意", "is_correct": false, "explanation": "语义：“满意”表示称心，与“奶奶去世”的悲痛语境冲突。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”表示自豪或称心，与“奶奶去世”不相容。"}, {"text": "调皮", "is_correct": false, "explanation": "搭配：“调皮”形容顽皮的行为，不用来形容全家人在丧事后的状态。"}], "explanations": {"伤心": "“伤心”表示遇到不幸而心里悲痛，与“奶奶去世后”的语境相符。", "满意": "语义：“满意”表示称心，与“奶奶去世”的悲痛语境冲突。", "得意": "语义：“得意”表示自豪或称心，与“奶奶去世”不相容。", "调皮": "搭配：“调皮”形容顽皮的行为，不用来形容全家人在丧事后的状态。"}, "sentence_index": 0, "correct_answer": "伤心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶病好了，全家人都很伤心。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，病好了应该高兴。"}, {"text": "同学还了我钱，我很伤心地道了谢。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，同学还钱后道谢应是高兴。"}, {"text": "听到雷声，他很伤心地跳起来欢呼。", "explanation": "这里应该用〈兴奋〉。〈伤心〉表示悲痛，跳起来欢呼应是兴奋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤心", "is_correct": true, "explanation": "“伤心”表示心里悲痛，与“他离开这座城市”的悲伤语境相符。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指物质丰足，不能用来形容离开的方式。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不描述人离开时的样子。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”形容缺少水分，不能描述人离开时的样子。"}], "explanations": {"伤心": "“伤心”表示心里悲痛，与“他离开这座城市”的悲伤语境相符。", "富裕": "语义：“富裕”指物质丰足，不能用来形容离开的方式。", "热闹": "搭配：“热闹”形容场面或气氛，不描述人离开时的样子。", "干燥": "语义：“干燥”形容缺少水分，不能描述人离开时的样子。"}, "sentence_index": 6, "correct_answer": "伤心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们跑完了操场，同学们都很伤心。", "explanation": "这里应该用〈累〉。〈伤心〉是心里难过，不形容身体疲劳。"}, {"text": "老师走进教室，同学们伤心地愣住了。", "explanation": "这里应该用〈惊讶〉。〈伤心〉表示悲痛，愣住的样子应是惊讶。"}, {"text": "我得了第一名，伤心得蹦蹦跳跳。", "explanation": "这里应该用〈高兴〉。〈伤心〉表示悲痛，得了第一名蹦蹦跳跳应是高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人说起往事，伤心的哭了。", "corrected_sentence": "老人说起往事，伤心地哭了。", "error_description": "“伤心”修饰动词“哭”时应用“地”，不能用“的”：应说“伤心地哭了”，把“的”改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他伤心很哭了一整天。", "corrected_sentence": "他伤心得哭了一整天。", "error_description": "“伤心”引出动作的程度或结果时应用“得”，不能用“很”：“很”只修饰形容词，不能放在动词“哭”前。应说“伤心得哭了一整天”，把“很”改为“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
