INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "剧情是电影、电视或戏里讲的那个故事。", "primary_collocate": null, "pronunciation": "jù qíng", "ipa": "tɕy˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我很喜欢这部电影的剧情。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢这种太简单的剧情。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到剧情最难过的地方，她哭了。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视剧的剧情让我很感动。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我讲了一下剧情。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电影前，请不要告诉我剧情。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧情太慢，我看着看着就睡着了。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧的剧情我已经忘了。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢和朋友一起聊剧情。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都喜欢剧情简单的动画片。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剧情简介", "label": "复合"}], "register": "中性", "sense_fingerprint": "剧情：电影、电视剧或戏里所讲的故事内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧情", "is_correct": true, "explanation": "剧情：电影、电视剧里讲的故事，符合“我很喜欢这部电影的”这一语境。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人，不能说电影的身高。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气象状况，不是电影的组成部分，“这部电影的天气”没有意义。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能说电影的体重。"}], "explanations": {"剧情": "剧情：电影、电视剧里讲的故事，符合“我很喜欢这部电影的”这一语境。", "身高": "搭配：“身高”只用于人，不能说电影的身高。", "天气": "语义：天气指气象状况，不是电影的组成部分，“这部电影的天气”没有意义。", "体重": "搭配：“体重”只用于人或动物，不能说电影的体重。"}, "sentence_index": 0, "correct_answer": "剧情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的剧情一张一百块钱。", "explanation": "这里应该用〈票〉。剧情是故事内容，不能用“一张”来数，也没有价钱。"}, {"text": "这部新片吸引了很多剧情。", "explanation": "这里应该用〈观众〉。剧情不能被“吸引”，吸引的是观众。"}, {"text": "墙上贴着一张剧情，很漂亮。", "explanation": "这里应该用〈海报〉。剧情是故事内容，没有实体，不能贴在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧情", "is_correct": true, "explanation": "剧情：故事情节，“太慢”指情节推进得缓慢，符合语境。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间没有快慢之分，“太慢”不能用来形容房间。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“慢”能形容进度或节奏，不能用来形容颜料。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，说它“太慢”没有意义。"}], "explanations": {"剧情": "剧情：故事情节，“太慢”指情节推进得缓慢，符合语境。", "房间": "语义：房间没有快慢之分，“太慢”不能用来形容房间。", "颜料": "搭配：“慢”能形容进度或节奏，不能用来形容颜料。", "钥匙": "语义：钥匙是开锁的工具，说它“太慢”没有意义。"}, "sentence_index": 6, "correct_answer": "剧情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们都想扮演动画片里的剧情。", "explanation": "这里应该用〈角色〉。“扮演”的对象是人物角色，剧情是故事内容，不能被扮演。"}, {"text": "这位歌手的剧情很好听。", "explanation": "这里应该用〈嗓音〉。剧情不是声音，“好听”形容的是嗓音。"}, {"text": "我给他讲了一只剧情。", "explanation": "量词错误：剧情应用〈段〉，〈只〉用于动物等，不能用来修饰剧情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很喜欢这本剧情。", "corrected_sentence": "我很喜欢这段剧情。", "error_description": "量词错误：“剧情”的量词应用“段”，“本”用于书籍，不能用来修饰剧情。正确说法是“这段剧情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那几段剧情们我都看过了。", "corrected_sentence": "那几段剧情我都看过了。", "error_description": "词形错误：“剧情”是抽象名词，不能加“们”表示复数。正确说法是“那几段剧情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
