INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏剧、电影、电视剧等作品中的故事情节。", "primary_collocate": null, "pronunciation": "jù qíng", "ipa": "tɕy˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影的剧情非常精彩。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧情发展得太快，我没看懂。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画片的剧情有很多变化。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后的剧情让大家都很意外。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视剧的剧情很真实。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧情里的两个人最后结婚了。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演把剧情拍得很紧张。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢剧情复杂的推理电影。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家正在写新电视剧的剧情。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧情太老套了，我早就猜到了。", "target_word": "剧情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剧情片", "label": "复合"}], "register": "中性", "sense_fingerprint": "剧情：戏剧、影视作品中的故事情节及其发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧情", "is_correct": true, "explanation": "剧情：作品中的故事情节，正符合“这部电影的……非常精彩”的语境。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：“精彩”形容内容或表演，不能用来形容票价。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气象状况，不是电影的组成部分，“这部电影的天气”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人，不能说电影的身高。"}], "explanations": {"剧情": "剧情：作品中的故事情节，正符合“这部电影的……非常精彩”的语境。", "票价": "搭配：“精彩”形容内容或表演，不能用来形容票价。", "天气": "语义：天气指气象状况，不是电影的组成部分，“这部电影的天气”说不通。", "身高": "搭配：“身高”只用于人，不能说电影的身高。"}, "sentence_index": 0, "correct_answer": "剧情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个女孩的剧情很漂亮。", "explanation": "这里应该用〈长相〉。剧情没有外貌，“漂亮”形容的是人的长相。"}, {"text": "她在台上唱了一段很动听的剧情。", "explanation": "这里应该用〈歌〉。剧情是故事内容，不能被“唱”，“唱”的对象是歌。"}, {"text": "这部电影的剧情很高，大家都很惊讶。", "explanation": "这里应该用〈票房〉。剧情没有高低之分，“很高”形容的是票房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧情", "is_correct": true, "explanation": "剧情：作品中的故事情节，能被导演拍得紧张，符合语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不能被拍得紧张，语义不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“紧张”形容场面或人的情绪，不能用于形容花瓶。"}, {"text": "台阶", "is_correct": false, "explanation": "语义：台阶是可以踩踏的建筑部件，没有紧张的属性，“把台阶拍得很紧张”不通。"}], "explanations": {"剧情": "剧情：作品中的故事情节，能被导演拍得紧张，符合语境。", "窗户": "语义：窗户是建筑构件，不能被拍得紧张，语义不通。", "花瓶": "搭配：“紧张”形容场面或人的情绪，不能用于形容花瓶。", "台阶": "语义：台阶是可以踩踏的建筑部件，没有紧张的属性，“把台阶拍得很紧张”不通。"}, "sentence_index": 6, "correct_answer": "剧情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首剧情很有意思，大家都在讨论。", "explanation": "量词错误：剧情应用〈段〉，〈首〉用于歌或诗，不能修饰剧情。"}, {"text": "她在剧中扮演一个剧情。", "explanation": "这里应该用〈角色〉。“扮演”的对象是人物角色，剧情不能被扮演。"}, {"text": "她的剧情有一米七。", "explanation": "这里应该用〈身高〉。剧情没有长度，“一米七”只用于身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗剧情让我想起了童年。", "corrected_sentence": "这段剧情让我想起了童年。", "error_description": "量词错误：“颗”用于小而圆的东西，不能修饰剧情。正确说法是“这段剧情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几段剧情们我都记得很清楚。", "corrected_sentence": "这几段剧情我都记得很清楚。", "error_description": "词形错误：“剧情”是抽象名词，不能加“们”表示复数。正确说法是“这几段剧情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
