INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94350, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "化学工业的简称，利用化学方法加工原料、制造产品。", "primary_collocate": null, "pronunciation": "huà gōng", "ipa": "xwa⁵¹ kʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "化工是一个很大的行业。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的化工很发达。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有很多做化工的公司。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对化工很有兴趣。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视化工的发展。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化工需要很多水和电。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两年，我们这儿的化工越来越好。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司做的是化工，不是食品。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化工和石油的关系很密切。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年他离开了学校，进了化工这一行。", "target_word": "化工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "化工厂", "label": "复合词"}, {"form": "化工产品", "label": "复合词"}, {"form": "化工原料", "label": "复合词"}], "register": "中性", "sense_fingerprint": "化学工业的简称，一个行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b63a56-8ab2-40e1-be94-f37f7483128e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化工", "is_correct": true, "explanation": "正确：化工指化学工业，可以作“行业”，符合“是一个很大的行业”。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是机构，不是行业，与“是一个很大的行业”不符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是场所，不能被称为“行业”。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”不能说成“一个很大的行业”，与“行业”搭配不当。"}], "explanations": {"化工": "正确：化工指化学工业，可以作“行业”，符合“是一个很大的行业”。", "学校": "语义：学校是机构，不是行业，与“是一个很大的行业”不符。", "医院": "语义：医院是场所，不能被称为“行业”。", "感情": "搭配：“感情”不能说成“一个很大的行业”，与“行业”搭配不当。"}, "sentence_index": 0, "correct_answer": "化工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天去化工看看。", "explanation": "这里把〈化工〉当成了场所。化工指化学工业，是行业名，不是工厂；去的地方应说〈化工厂〉。"}, {"text": "他是一个很好的化工。", "explanation": "这里把〈化工〉当成了指人的名词。化工是行业名，不指从业者；指人要说〈化工工程师〉。"}, {"text": "他找到了一条化工。", "explanation": "量词误用：〈化工〉作行业讲，应说〈一行〉或〈一个行业〉，“条”用于细长的东西，不能用于行业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化工", "is_correct": true, "explanation": "正确：“越来越好”可以用来评价化工行业的发展，符合语境。"}, {"text": "恐龙", "is_correct": false, "explanation": "语义：恐龙已经灭绝，不会“越来越好”，与“这两年”的发展描述不符。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不能用“越来越好”来评价。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用“越来越好”来评价，与“越来越好”搭配不当。"}], "explanations": {"化工": "正确：“越来越好”可以用来评价化工行业的发展，符合语境。", "恐龙": "语义：恐龙已经灭绝，不会“越来越好”，与“这两年”的发展描述不符。", "地震": "语义：地震是自然灾害，不能用“越来越好”来评价。", "年龄": "搭配：“年龄”不能用“越来越好”来评价，与“越来越好”搭配不当。"}, "sentence_index": 6, "correct_answer": "化工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的化工很好吃。", "explanation": "语义：化工是行业，不是食物，不能说“好吃”。"}, {"text": "化工今天穿了一件红衣服。", "explanation": "语义：〈化工〉是一个行业，不是人，不能穿衣服。"}, {"text": "他把化工送给了朋友。", "explanation": "语义：〈化工〉是行业，不是可以赠送的物品，不能被“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司很化工。", "corrected_sentence": "这家公司做化工。", "error_description": "词性错误：“化工”是名词，不能受程度副词“很”修饰；“很化工”不成句，应说“做化工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，我们城市的化工们发展得很快。", "corrected_sentence": "这几年，我们城市的化工发展得很快。", "error_description": "错误形式：“化工们”；“化工”是行业名，不指人，不能加“们”；正确形式：“化工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
