INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94351, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "区号是打电话时，放在前面的那几个数字，告诉别人你在哪个地方。", "primary_collocate": null, "pronunciation": "qū hào", "ipa": "tɕʰy˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "你打电话前，要先拨北京的区号。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了奶奶家的区号，打不通电话。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打长途电话时，别忘了加区号。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问成都的区号是多少？", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机号码不用加区号，座机要加。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把区号写在电话号码前面。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过区号，我知道朋友住在哪个城市。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我一张写着区号的纸。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道广州的区号吗？", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的区号是010，上海的是021。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个区号", "label": "量词"}, {"form": "區號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打电话时放在号码前、表示地区的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地址", "is_correct": false, "explanation": "搭配：“拨”后接的是电话号码，不能拨“地址”。"}, {"text": "区号", "is_correct": true, "explanation": "正确。“拨北京的区号”指打电话前先拨打的北京地区数字代码。"}, {"text": "密码", "is_correct": false, "explanation": "语义：密码是登录用的口令，不是打电话时要拨的数字。"}, {"text": "区域", "is_correct": false, "explanation": "搭配：“拨”不能接“区域”，地方范围不能拨打。"}], "explanations": {"地址": "搭配：“拨”后接的是电话号码，不能拨“地址”。", "区号": "正确。“拨北京的区号”指打电话前先拨打的北京地区数字代码。", "密码": "语义：密码是登录用的口令，不是打电话时要拨的数字。", "区域": "搭配：“拨”不能接“区域”，地方范围不能拨打。"}, "sentence_index": 0, "correct_answer": "区号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机区号是13812345678。", "explanation": "这里应该用〈号码〉。手机号是一整串号码，区号只是号码前表示地区的几位数字，不能指整个手机号。"}, {"text": "我每天骑车去这个区号上学。", "explanation": "这里应该用〈学校〉。学校是上课的地方；区号只是电话前的数字，不能用来上学。"}, {"text": "寄信时，信封上要写清楚区号，信才能送到。", "explanation": "这里应该用〈邮编〉。寄信要写的是邮政编码，区号是打电话用的，不能用来寄信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：名字不能说明朋友住在哪个城市。"}, {"text": "区号", "is_correct": true, "explanation": "正确。“通过区号”指凭地区代码判断朋友所在的城市。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与所在城市无关，不能据此知道朋友住在哪里。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“通过”后接的是途径或手段，“心情”不是途径，不能说“通过心情”。"}], "explanations": {"名字": "语义：名字不能说明朋友住在哪个城市。", "区号": "正确。“通过区号”指凭地区代码判断朋友所在的城市。", "年龄": "语义：年龄与所在城市无关，不能据此知道朋友住在哪里。", "心情": "搭配：“通过”后接的是途径或手段，“心情”不是途径，不能说“通过心情”。"}, "sentence_index": 6, "correct_answer": "区号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的区号是上海。", "explanation": "这里应该用〈城市名〉。区号是电话前的数字代码，不是城市的名字；应说“上海的区号是021”。"}, {"text": "老师按照区号点名，我是第15号。", "explanation": "这里应该用〈学号〉。点名用的是学生的编号，区号是打电话时表示地区的数字。"}, {"text": "这封信的区号是北京市朝阳区。", "explanation": "这里应该用〈地址〉。北京市朝阳区是地名，区号是打电话前的数字代码，不能用来写地址。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "给朋友打电话前，先拿一下上海的区号。", "corrected_sentence": "给朋友打电话前，先拨一下上海的区号。", "error_description": "“区号”是要拨出的号码，应说“拨”，不能说“拿”。“拿”只用于实物，不能用来指拨打的区号。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请问天津的区号在多少？", "corrected_sentence": "请问天津的区号是多少？", "error_description": "问区号要用“是”连接答案，不能用“在”。“在”表示位置，不能接“多少”来询问区号。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
