INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94352, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电话号码前表示所在地区的数字代码。", "primary_collocate": null, "pronunciation": "qū hào", "ipa": "tɕʰy˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "国内的座机号码前面有区号。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打电话给外地的朋友，要先拨区号。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我查了一下，杭州的区号是0571。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张名片上没有写区号。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区号一般有三四位数字。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他记得电话号码，却不记得区号。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个城市的区号都是一样的。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把区号和电话号码都告诉我。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从上海打到深圳，要加深圳的区号。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了看区号，就知道电话是哪里来的。", "target_word": "区号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个区号", "label": "量词"}, {"form": "區號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电话号码前表示地区的数字代码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "号码", "is_correct": false, "explanation": "语义：“号码”指整串电话号，区号只是其中一段，说“前面有号码”不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“有”后接的是可见的数字或代码，“时间”不能放在号码前面表示地区。"}, {"text": "区号", "is_correct": true, "explanation": "正确。区号是座机号码前面表示所在地区的数字代码。"}, {"text": "国家", "is_correct": false, "explanation": "语义：国内拨打不需要国家，“国家”不是地区代码，与“国内”矛盾。"}], "explanations": {"号码": "语义：“号码”指整串电话号，区号只是其中一段，说“前面有号码”不通。", "时间": "搭配：“有”后接的是可见的数字或代码，“时间”不能放在号码前面表示地区。", "区号": "正确。区号是座机号码前面表示所在地区的数字代码。", "国家": "语义：国内拨打不需要国家，“国家”不是地区代码，与“国内”矛盾。"}, "sentence_index": 0, "correct_answer": "区号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把他的区号吃进了肚子里。", "explanation": "这里应该用〈饭菜〉。区号是电话前的数字，不能吃。"}, {"text": "这次考试我得了全班第一个区号。", "explanation": "这里应该用〈名次〉。考试的排位要说名次，区号是电话前表示地区的数字。"}, {"text": "寄包裹要先填好区号。", "explanation": "这里应该用〈邮编〉。寄包裹要填的是邮政编码，区号是打电话用的，不能用来寄东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性别", "is_correct": false, "explanation": "语义：同一个城市的人性别各不相同，“都是一样的”说不通。"}, {"text": "区号", "is_correct": true, "explanation": "正确。同一城市共用同一个区号，所以“都是一样的”成立。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“同一个城市的”修饰的是可以共有的地区属性，“年代”不是这类属性，不搭配。"}, {"text": "电话", "is_correct": false, "explanation": "语义：同一城市的电话各不相同，“都是一样的”说不通。"}], "explanations": {"性别": "语义：同一个城市的人性别各不相同，“都是一样的”说不通。", "区号": "正确。同一城市共用同一个区号，所以“都是一样的”成立。", "年代": "搭配：“同一个城市的”修饰的是可以共有的地区属性，“年代”不是这类属性，不搭配。", "电话": "语义：同一城市的电话各不相同，“都是一样的”说不通。"}, "sentence_index": 6, "correct_answer": "区号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杭州的区号是城市里的一条街。", "explanation": "这里应该用〈街道〉。区号是电话前的数字，不是可以走的街道。"}, {"text": "我的手机区号是13812345678。", "explanation": "这里应该用〈号码〉。手机号是一整串完整的号码，区号只是号码前表示地区的几位数字。"}, {"text": "我找到了一个区号，它原来是我的生日。", "explanation": "这里应该用〈日期〉。区号是电话前表示地区的数字，不是某一天，不能说它是某个日期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "打长途时，要先拿杭州的区号。", "corrected_sentence": "打长途时，要先拨杭州的区号。", "error_description": "“拨”才能与“区号”搭配，表示拨出这个号码；“拿”只用于实物，不能用于区号。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "广州的区号有020。", "corrected_sentence": "广州的区号是020。", "error_description": "“区号”后应用“是”说明号码，不能用“有”。“有”表示拥有，不用于说明区号是多少。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
