INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94353, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每一个层级都有，或每一个层级都要做某事（常与“都”连用）。", "primary_collocate": null, "pronunciation": "gè jí", "ipa": "kɤ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这家银行的各级都有专门的培训课程。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛分初级、中级和高级，各级都有冠军。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司各级都要写工作报告。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试很难，各级的题目都不容易。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里各级都有自己的学生会。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织各级都设有办公室。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "武术班各级都有专门的老师。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司各级都有女同事。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院各级都有值班医生。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语考试各级都要考听力。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各級", "label": "繁体"}], "register": "书面", "sense_fingerprint": "强调每一个层级都有或都要做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94353, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各级", "is_correct": true, "explanation": "“各级”指所有层级，表示银行的每一层都有专门的培训课程，与句意相符。"}, {"text": "各界", "is_correct": false, "explanation": "搭配：“各界”指社会各行业，不指银行内部的层级。"}, {"text": "各派", "is_correct": false, "explanation": "语义：“各派”指学派或党派，与银行内部的培训无关。"}, {"text": "各路", "is_correct": false, "explanation": "语义：“各路”指各个方面、各方的人马，不指银行内部的层级。"}], "explanations": {"各级": "“各级”指所有层级，表示银行的每一层都有专门的培训课程，与句意相符。", "各界": "搭配：“各界”指社会各行业，不指银行内部的层级。", "各派": "语义：“各派”指学派或党派，与银行内部的培训无关。", "各路": "语义：“各路”指各个方面、各方的人马，不指银行内部的层级。"}, "sentence_index": 0, "correct_answer": "各级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店卖各级饮料。", "explanation": "这里应该用〈各种〉。各级指层级，饮料按种类划分，要用各种。"}, {"text": "这座公园的各级花都开了。", "explanation": "这里应该用〈各色〉。花按颜色、品种区分，不分层级，要用各色。"}, {"text": "我们班的各级同学都来了。", "explanation": "这里应该用〈各位〉。同学是一个个人，同一个班不分层级，要用各位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各级", "is_correct": true, "explanation": "“各级”指所有层级，表示武术班的每一层都有专门的老师，与句意相符。"}, {"text": "各色", "is_correct": false, "explanation": "语义：“各色”多指颜色或“各色人等”，不能直接修饰“武术班”。"}, {"text": "各界", "is_correct": false, "explanation": "搭配：“各界”指社会各行业的人士，武术班不是社会行业，不能说“武术班各界都有专门的老师”。"}, {"text": "各国", "is_correct": false, "explanation": "语义：“各国”指各个国家，武术班不是国家，句意说不通。"}], "explanations": {"各级": "“各级”指所有层级，表示武术班的每一层都有专门的老师，与句意相符。", "各色": "语义：“各色”多指颜色或“各色人等”，不能直接修饰“武术班”。", "各界": "搭配：“各界”指社会各行业的人士，武术班不是社会行业，不能说“武术班各界都有专门的老师”。", "各国": "语义：“各国”指各个国家，武术班不是国家，句意说不通。"}, "sentence_index": 6, "correct_answer": "各级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "期末考试要考各级科目。", "explanation": "这里应该用〈各科〉。科目是一门门的课，要用各科，各级指层级。"}, {"text": "各级国家都派了代表来访问。", "explanation": "这里应该用〈各国〉。国家是并列的个体，不分层级，要用各国。"}, {"text": "街上挂着各级灯笼。", "explanation": "这里应该用〈各色〉。各级指层级，灯笼按颜色或样式区分，要用各色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所医院的一个各级都有图书室。", "corrected_sentence": "这所医院的各级都有图书室。", "error_description": "“各级”前不能加数量词“一个”。“各级”本身表示所有层级，应直接说“各级都有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学各级有都奖学金。", "corrected_sentence": "这所大学各级都有奖学金。", "error_description": "副词“都”位置错误：应说“各级都有”，“都”要放在动词“有”之前，不能说“有都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
