INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "各个层级，所有等级。", "primary_collocate": null, "pronunciation": "gè jí", "ipa": "kɤ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "各级政府都要认真落实这项新政策。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议要求各级干部提前做好准备。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各级学校今天都收到了教育部的通知。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的各级领导都参加了今天的大会。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各级医院都要保证病人的安全。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件已经发给了各级部门。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各级法院都必须按照法律办案。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请各级管理人员明天上午来开会。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要求各级政府帮助农民。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各级领导都很关心这件事。", "target_word": "各级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各級", "label": "繁体"}], "register": "书面", "sense_fingerprint": "指一个体系中的各个层级，如各级政府、各级干部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各级", "is_correct": true, "explanation": "“各级”指各个层级，修饰“政府”表示每一层级的政府都要落实这项政策，与句意相符。"}, {"text": "各界", "is_correct": false, "explanation": "搭配：“各界”指社会各行业的人士，不能修饰“政府”。"}, {"text": "各位", "is_correct": false, "explanation": "语义：“各位”指一个个人，用于称呼或指代人，不指机构。"}, {"text": "各项", "is_correct": false, "explanation": "搭配：“各项”修饰工作、措施等事项，不能修饰“政府”。"}], "explanations": {"各级": "“各级”指各个层级，修饰“政府”表示每一层级的政府都要落实这项政策，与句意相符。", "各界": "搭配：“各界”指社会各行业的人士，不能修饰“政府”。", "各位": "语义：“各位”指一个个人，用于称呼或指代人，不指机构。", "各项": "搭配：“各项”修饰工作、措施等事项，不能修饰“政府”。"}, "sentence_index": 0, "correct_answer": "各级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次展览吸引了各级行业的人参观。", "explanation": "这里应该用〈各个〉。各级指层级高低，行业是按领域并列划分的，要说“各个行业”。"}, {"text": "这座古城吸引了各级游客。", "explanation": "这里应该用〈各地〉。各级指层级高低，游客要按来源地区划分，要用各地。"}, {"text": "我们买了各级家具。", "explanation": "这里应该用〈各式〉。各级指层级高低，家具要按样式区分，要用各式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各级", "is_correct": true, "explanation": "“各级”指各个层级，修饰“法院”表示每一层级的法院都必须依法办案，与句意相符。"}, {"text": "各路", "is_correct": false, "explanation": "搭配：“各路”指各方人马，如“各路英雄”，不能修饰“法院”。"}, {"text": "各派", "is_correct": false, "explanation": "搭配：“各派”指学派或党派，不能修饰“法院”。"}, {"text": "各校", "is_correct": false, "explanation": "语义：“各校”指各所学校，法院不是学校。"}], "explanations": {"各级": "“各级”指各个层级，修饰“法院”表示每一层级的法院都必须依法办案，与句意相符。", "各路": "搭配：“各路”指各方人马，如“各路英雄”，不能修饰“法院”。", "各派": "搭配：“各派”指学派或党派，不能修饰“法院”。", "各校": "语义：“各校”指各所学校，法院不是学校。"}, "sentence_index": 6, "correct_answer": "各级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "展厅里摆着各级花瓶。", "explanation": "这里应该用〈各式〉。各级指层级，花瓶按样式区分，要用各式。"}, {"text": "各级国家都派了代表参加这次会议。", "explanation": "这里应该用〈各国〉。国家是并列的个体，不分层级，要用各国。"}, {"text": "欢迎各级朋友光临本店。", "explanation": "这里应该用〈各位〉。招呼的是一个个人，要用各位，各级指层级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个各级政府都很重视这件事。", "corrected_sentence": "各级政府都很重视这件事。", "error_description": "“各级”是复数性的限定词，前面不能加数量词“一个”。应说“各级政府”，去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每各级学校都要做好安全检查。", "corrected_sentence": "各级学校都要做好安全检查。", "error_description": "“各”和“每”都表示“各个”，不能同时使用。应删去“每”，说“各级学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
