INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94355, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "喂是打电话或叫人时，先喊的一个字。", "primary_collocate": null, "pronunciation": "wèi", "ipa": "weɪ˥˩", "syllable_count": 1, "sentences": [{"text": "喂，你好，请问王老师在吗？", "target_word": "喂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "喂，我是小李，你现在有空吗？", "target_word": "喂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喂，你的手机响了！", "target_word": "喂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喂，前面的人，请等一下！", "target_word": "喂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "喂，你在哪儿？我听不到你说话。", "target_word": "喂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喂，是我，我到家了。", "target_word": "喂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喂，你的书掉在地上了。", "target_word": "喂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喂，我听不清，请你大点儿声。", "target_word": "喂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿起电话说：“喂，你找谁？”", "target_word": "喂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喂，等等我，我们一起走！", "target_word": "喂", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "喂喂", "label": "重叠"}], "register": "口语", "sense_fingerprint": "喂：打电话或叫人时先喊的招呼声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ce9a55-ce32-4de2-b1f7-ff56f8f8bde6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94355, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喂", "is_correct": true, "explanation": "喂：打电话或叫人时先喊的招呼声，属叹词用法。"}, {"text": "危", "is_correct": false, "explanation": "wēi（第一声）与 wèi（第四声）声调不同，意思是危险。"}, {"text": "问", "is_correct": false, "explanation": "wèn 与 wèi 韵母不同（en 与 ei），意思是询问。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 wèi 声母不同（f 与 w），意思是花费。"}, {"text": "尾", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是尾巴。"}, {"text": "内", "is_correct": false, "explanation": "nèi 与 wèi 声母不同（n 与 w），意思是里面、内部。"}], "explanations": {"喂": "喂：打电话或叫人时先喊的招呼声，属叹词用法。", "危": "wēi（第一声）与 wèi（第四声）声调不同，意思是危险。", "问": "wèn 与 wèi 韵母不同（en 与 ei），意思是询问。", "费": "fèi 与 wèi 声母不同（f 与 w），意思是花费。", "尾": "wěi（第三声）与 wèi（第四声）声调不同，意思是尾巴。", "内": "nèi 与 wèi 声母不同（n 与 w），意思是里面、内部。"}, "sentence_index": null, "correct_answer": "喂"}, "level_3": {"options": [{"text": "喂", "is_correct": true, "explanation": "正确：“喂”是打电话或叫人时的招呼声，用于开头，符合句意。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，与“你好，请问王老师在吗”的礼貌问候语境不符。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示轻蔑或不满，与礼貌的问候语境冲突。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是粗俗的斥责声，不适合用于礼貌的电话问候。"}], "explanations": {"喂": "正确：“喂”是打电话或叫人时的招呼声，用于开头，符合句意。", "哇": "语义：“哇”表示惊叹，与“你好，请问王老师在吗”的礼貌问候语境不符。", "哼": "语义：“哼”表示轻蔑或不满，与礼貌的问候语境冲突。", "呸": "语域：“呸”是粗俗的斥责声，不适合用于礼貌的电话问候。"}, "sentence_index": 0, "correct_answer": "喂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喂一封信寄给家里。", "explanation": "这里应该用〈写〉。“喂”作叹词时不表示写信；它的动词义只指给人或动物吃东西，写信要用“写”。"}, {"text": "尊敬的各位来宾，喂，欢迎大家光临！", "explanation": "这里应该用〈请注意〉。“喂”是随意的招呼声，用于打电话或叫人；正式致辞应先说“请大家注意”，再欢迎来宾。"}, {"text": "我昨天喂了一个电话给他。", "explanation": "这里应该用〈打〉。打电话要说“打”；“喂”作叹词时只是接电话或叫人时的招呼声，不表示打电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94355, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喂", "is_correct": true, "explanation": "喂：打电话或叫人时先喊的招呼声，属叹词用法。"}, {"text": "闻", "is_correct": false, "explanation": "wén 与 wèi 韵母不同（en 与 ei），意思是闻到或听到。"}, {"text": "围", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，意思是包围或围绕。"}, {"text": "背", "is_correct": false, "explanation": "bèi 与 wèi 声母不同（b 与 w），意思是背部或背诵。"}, {"text": "维", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，意思是维护或维持。"}], "explanations": {"喂": "喂：打电话或叫人时先喊的招呼声，属叹词用法。", "闻": "wén 与 wèi 韵母不同（en 与 ei），意思是闻到或听到。", "围": "wéi（第二声）与 wèi（第四声）声调不同，意思是包围或围绕。", "背": "bèi 与 wèi 声母不同（b 与 w），意思是背部或背诵。", "维": "wéi（第二声）与 wèi（第四声）声调不同，意思是维护或维持。"}, "sentence_index": null, "correct_answer": "喂"}, "level_3": {"options": [{"text": "喂", "is_correct": true, "explanation": "正确：“喂”是叫人时的招呼声，用于提醒对方，符合句意。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示不满或轻蔑，与好心提醒对方书掉了的语境不符。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”是让人安静的声音，与提醒对方书掉落的语境不符。"}, {"text": "啧", "is_correct": false, "explanation": "语义：“啧”表示不满或责备，与中性提醒的语境不协调。"}], "explanations": {"喂": "正确：“喂”是叫人时的招呼声，用于提醒对方，符合句意。", "哼": "语义：“哼”表示不满或轻蔑，与好心提醒对方书掉了的语境不符。", "嘘": "语义：“嘘”是让人安静的声音，与提醒对方书掉落的语境不符。", "啧": "语义：“啧”表示不满或责备，与中性提醒的语境不协调。"}, "sentence_index": 6, "correct_answer": "喂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小王在旁边喂了句话。", "explanation": "这里应该用〈说〉。“喂”不能作动词表示说话，说话要用“说”。"}, {"text": "他喂起电话，说：“你好，请问哪位？”", "explanation": "这里应该用〈接〉。接电话要说“接”；“喂”作叹词时只是接电话时的招呼语，不表示接的动作。"}, {"text": "他每晚给孩子喂故事。", "explanation": "这里应该用〈讲〉。讲故事要说“讲”；“喂”的动词义只指给人或动物吃东西，不能用于讲故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喂了，你在哪儿？我到车站了。", "corrected_sentence": "喂，你在哪儿？我到车站了。", "error_description": "“喂”是叹词，后面不能加“了”；正确应直接用“喂”作开头的招呼声，正确为“喂，你在哪儿？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听见了你的喂，声音很大。", "corrected_sentence": "我听见了你在喊“喂”，声音很大。", "error_description": "“喂”是叹词，不能直接作名词并接“的”；应说“你在喊‘喂’”，用“喊”引出这个招呼声。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73d35cb1-715a-4954-9221-161735cab75f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
