INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94357, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "喔是听懂了、明白了的时候发出的声音。", "primary_collocate": null, "pronunciation": "ò", "ipa": "ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "喔，我听懂了，谢谢你。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，原来你是他的哥哥。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲完以后，他说：“喔，我明白了。”", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，这个字是这样写的。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“明天不上课。”“喔，我知道了。”", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，这个词是这个意思。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，你是说我们坐地铁去吧？", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听她解释完，我才“喔”了一声。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，原来今天是你的生日。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，这样做就对了。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "喔：听懂、明白时发出的应答声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94357, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喔", "is_correct": true, "explanation": "喔（ò，第四声）是听懂、明白时发出的应答声。"}, {"text": "鹅", "is_correct": false, "explanation": "鹅（é，第二声）是一种家禽，与 ò 声调不同，意义无关。"}, {"text": "额", "is_correct": false, "explanation": "额（é，第二声）指额头或数量，与 ò 声调不同，意义无关。"}, {"text": "饿", "is_correct": false, "explanation": "è 与 ò 韵母不同（e 与 o），意思是饿，指肚子空想吃东西。"}], "explanations": {"喔": "喔（ò，第四声）是听懂、明白时发出的应答声。", "鹅": "鹅（é，第二声）是一种家禽，与 ò 声调不同，意义无关。", "额": "额（é，第二声）指额头或数量，与 ò 声调不同，意义无关。", "饿": "è 与 ò 韵母不同（e 与 o），意思是饿，指肚子空想吃东西。"}, "sentence_index": null, "correct_answer": "喔"}, "level_3": {"options": [{"text": "喔", "is_correct": true, "explanation": "喔：表示听懂、明白的应答声，正合“我听懂了，谢谢你”的语境。"}, {"text": "唉", "is_correct": false, "explanation": "语义：唉表示叹息或懊恼，与“听懂了、谢谢你”的语境不合。"}, {"text": "哇", "is_correct": false, "explanation": "语义：哇表示惊叹或赞美，不表示领会，与“听懂了”不合。"}, {"text": "哼", "is_correct": false, "explanation": "搭配：“哼”表示不满，后面不能接“我听懂了，谢谢你”这样的感谢语。"}], "explanations": {"喔": "喔：表示听懂、明白的应答声，正合“我听懂了，谢谢你”的语境。", "唉": "语义：唉表示叹息或懊恼，与“听懂了、谢谢你”的语境不合。", "哇": "语义：哇表示惊叹或赞美，不表示领会，与“听懂了”不合。", "哼": "搭配：“哼”表示不满，后面不能接“我听懂了，谢谢你”这样的感谢语。"}, "sentence_index": 0, "correct_answer": "喔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喔，真恶心，快拿走！", "explanation": "这里应该用〈呸〉。喔表示领会醒悟，不表示厌恶，厌恶时要用呸。"}, {"text": "我的手被针扎了，忍不住喔了一声。", "explanation": "这里应该用〈哎哟〉。喔表示领会、醒悟，不表示疼痛，疼痛时才用哎哟。"}, {"text": "喔，我好怕黑，快开灯！", "explanation": "这里应该用〈妈呀〉。喔表示领会醒悟，不表示害怕，害怕时要用妈呀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喔", "is_correct": true, "explanation": "喔：表示领会、确认对方意思的应答声，正合“你是说我们坐地铁去吧”的语境。"}, {"text": "啧", "is_correct": false, "explanation": "语义：啧表示不满或不耐烦，与平和地确认对方的意思不合。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示唾弃、鄙视，语境中没有这种情绪。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：哎哟表示疼痛或吃惊，与平和地确认对方意思不合。"}], "explanations": {"喔": "喔：表示领会、确认对方意思的应答声，正合“你是说我们坐地铁去吧”的语境。", "啧": "语义：啧表示不满或不耐烦，与平和地确认对方的意思不合。", "呸": "语义：呸表示唾弃、鄙视，语境中没有这种情绪。", "哎哟": "语义：哎哟表示疼痛或吃惊，与平和地确认对方意思不合。"}, "sentence_index": 6, "correct_answer": "喔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喔，又下雨了，真讨厌！", "explanation": "这里应该用〈唉〉。喔表示领会醒悟，不表示懊恼或抱怨，懊恼时要用唉。"}, {"text": "喔，这个蛋糕真漂亮！", "explanation": "这里应该用〈哇〉。喔表示领会醒悟，不表示赞叹，赞叹时要用哇。"}, {"text": "喔，你过来一下！", "explanation": "这里应该用〈喂〉。喔表示领会醒悟，不用来招呼人，叫人时要用喂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喔了，我明白了，谢谢你。", "corrected_sentence": "喔，我明白了，谢谢你。", "error_description": "词形错误：“喔”是叹词，不能带“了”。正确说法是“喔，我明白了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听完以后，只喔了一个。", "corrected_sentence": "他听完以后，只喔了一声。", "error_description": "量词错误：“喔了一声”中，“喔”表示发出的声音，量词应用“声”，“一个”不能用来修饰声音。正确说法是“喔了一声”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
