INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94358, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "叹词，表示领会、醒悟。", "primary_collocate": null, "pronunciation": "ò", "ipa": "ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "喔，我想起来了，钥匙在桌子上。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，我忘了今天要交作业。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了想，说：“喔，我懂了。”", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，怪不得你不愿意去。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，我这才明白是我错了。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，原来这条路不能走。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了朋友的话，他“喔”了一声，点点头。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“他不是老师，是医生。”“喔，我搞错了。”", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，原来你早就知道了。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喔，怪不得楼下这么吵，原来在搬家。", "target_word": "喔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "喔：表示领会、醒悟的叹词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94358, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喔", "is_correct": true, "explanation": "喔（ò，第四声）是表示领会、醒悟的叹词。"}, {"text": "鹅", "is_correct": false, "explanation": "鹅（é，第二声）是一种家禽，与 ò 声调不同，意义无关。"}, {"text": "额", "is_correct": false, "explanation": "额（é，第二声）指额头或数量，与 ò 声调不同，意义无关。"}, {"text": "恶", "is_correct": false, "explanation": "è 与 ò 韵母不同（e 与 o），意思是恶，指坏或令人厌恶。"}], "explanations": {"喔": "喔（ò，第四声）是表示领会、醒悟的叹词。", "鹅": "鹅（é，第二声）是一种家禽，与 ò 声调不同，意义无关。", "额": "额（é，第二声）指额头或数量，与 ò 声调不同，意义无关。", "恶": "è 与 ò 韵母不同（e 与 o），意思是恶，指坏或令人厌恶。"}, "sentence_index": null, "correct_answer": "喔"}, "level_3": {"options": [{"text": "喔", "is_correct": true, "explanation": "喔：表示领会、醒悟的叹词，正合“我想起来了”的语境。"}, {"text": "哇", "is_correct": false, "explanation": "语义：哇表示惊叹，与“想起来了”的醒悟语气不合。"}, {"text": "哼", "is_correct": false, "explanation": "搭配：“哼”表示不满，后面不接“钥匙在桌子上”这样的平和陈述。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示唾弃、鄙视，与“我想起来了”的醒悟语气毫不相合。"}], "explanations": {"喔": "喔：表示领会、醒悟的叹词，正合“我想起来了”的语境。", "哇": "语义：哇表示惊叹，与“想起来了”的醒悟语气不合。", "哼": "搭配：“哼”表示不满，后面不接“钥匙在桌子上”这样的平和陈述。", "呸": "语义：呸表示唾弃、鄙视，与“我想起来了”的醒悟语气毫不相合。"}, "sentence_index": 0, "correct_answer": "喔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喔，真臭，快关窗！", "explanation": "这里应该用〈呸〉。喔表示领会醒悟，不表示厌恶，厌恶时要用呸。"}, {"text": "不小心碰到桌角，我忍不住喔了一声。", "explanation": "这里应该用〈哎哟〉。喔表示领会醒悟，不表示疼痛，疼痛时才用哎哟。"}, {"text": "喔，这道菜太辣了，快给我水！", "explanation": "这里应该用〈嘶〉。喔表示领会醒悟，不表示辣或烫，辣得吸气时要用嘶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喔", "is_correct": true, "explanation": "喔：表示领会的叹词，“点点头”说明他接受并明白了朋友的话。"}, {"text": "啧", "is_correct": false, "explanation": "语义：啧表示不满，与听完朋友的话后点头认同的态度不合。"}, {"text": "嘁", "is_correct": false, "explanation": "语义：嘁表示轻蔑、不屑，与“点点头”的认同态度相冲突。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：哎哟表示疼痛或吃惊，与听完话后点头认同的语境不合。"}], "explanations": {"喔": "喔：表示领会的叹词，“点点头”说明他接受并明白了朋友的话。", "啧": "语义：啧表示不满，与听完朋友的话后点头认同的态度不合。", "嘁": "语义：嘁表示轻蔑、不屑，与“点点头”的认同态度相冲突。", "哎哟": "语义：哎哟表示疼痛或吃惊，与听完话后点头认同的语境不合。"}, "sentence_index": 6, "correct_answer": "喔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喔，吓死我了！", "explanation": "这里应该用〈天哪〉。喔表示领会醒悟，不表示惊吓，惊吓时要用天哪。"}, {"text": "喔，你过来一下！", "explanation": "这里应该用〈喂〉。喔表示领会醒悟，不用来招呼人，叫人时要用喂。"}, {"text": "喔，这个蛋糕真漂亮！", "explanation": "这里应该用〈哇〉。喔表示领会醒悟，不表示赞叹，赞叹时要用哇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喔了，钥匙原来在桌子上。", "corrected_sentence": "喔，钥匙原来在桌子上。", "error_description": "词形错误：“喔”是叹词，不能带“了”。正确说法是“喔，钥匙原来在桌子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听完，只喔了一个，就走了。", "corrected_sentence": "他听完，只喔了一声，就走了。", "error_description": "量词错误：“喔了一声”中，“喔”表示发出的声音，量词应用“声”，“一个”不能用来修饰声音。正确说法是“喔了一声”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
