INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本国内部和其他国家，即国内与国外。", "primary_collocate": null, "pronunciation": "guó nèi wài", "ipa": "kwo³⁵ nei⁵¹ wai⁵¹", "syllable_count": 3, "sentences": [{"text": "国内外的专家都在谈这个问题。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的名字，国内外的人都知道。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛吸引了国内外的很多人。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书在国内外都有人读。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的产品在国内外都卖得很好。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内外的大学都想请他去上课。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想在国内外找好人才。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内外的游客夏天都来这里玩。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国内外拿过很多奖。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内外的人都喜欢这首歌。", "target_word": "国内外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本国内部和其他国家，即国内与国外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b63a56-8ab2-40e1-be94-f37f7483128e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内外", "is_correct": true, "explanation": "正确：“国内外的专家”指国内和国外的专家，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是专家的范围，与“国内外”所指不符。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是时间，不能指专家的范围。"}, {"text": "白天", "is_correct": false, "explanation": "搭配：“白天的专家”不成词，与“都在谈这个问题”搭配不当。"}], "explanations": {"国内外": "正确：“国内外的专家”指国内和国外的专家，符合句意。", "冰箱": "语义：冰箱不是专家的范围，与“国内外”所指不符。", "夏天": "语义：夏天是时间，不能指专家的范围。", "白天": "搭配：“白天的专家”不成词，与“都在谈这个问题”搭配不当。"}, "sentence_index": 0, "correct_answer": "国内外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在国内外那所学校读书。", "explanation": "语义：〈国内外〉是范围，不是具体的学校，不能指称某所学校。"}, {"text": "他是我的国内外。", "explanation": "语义：〈国内外〉不指人，不能用在“我的”后面作人称。"}, {"text": "这家餐厅的国内外很辣。", "explanation": "语义：〈国内外〉是范围词，不能用“辣”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内外", "is_correct": true, "explanation": "正确：“在国内外找人才”指在国内外各地寻找，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是找人才的地点，与句意不合。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是找人才的范围，与句意不合。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“垃圾桶”不能作“找人才”的处所，搭配不当。"}], "explanations": {"国内外": "正确：“在国内外找人才”指在国内外各地寻找，符合句意。", "冰箱": "语义：冰箱不是找人才的地点，与句意不合。", "鱼": "语义：鱼不是找人才的范围，与句意不合。", "垃圾桶": "搭配：“垃圾桶”不能作“找人才”的处所，搭配不当。"}, "sentence_index": 6, "correct_answer": "国内外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我送给妈妈一份国内外。", "explanation": "语义：〈国内外〉是范围，不是可以送人的东西。"}, {"text": "他把国内外打开了。", "explanation": "语义：〈国内外〉不是可以打开的东西。"}, {"text": "他每天早上都喝国内外。", "explanation": "语义：〈国内外〉是范围，不是饮料，不能被“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的品牌的国内外都很有名。", "corrected_sentence": "我们的品牌在国内外都很有名。", "error_description": "介词错误：“国内外”作状语表示范围，前面要用介词“在”，不能用结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方法从国内外都有人在用。", "corrected_sentence": "这个方法在国内外都有人在用。", "error_description": "介词错误：表示范围用“在”，“从”表示起点；“国内外”作范围状语应用“在”，不能说“从国内外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963e0405-6f1f-4934-be2d-8a2b79d8d2ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94361, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外行", "is_correct": true, "explanation": "外行指对某事不懂、不熟练，与“在行”意思相反。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：“高兴”说心情，与“在行”指做事能力无关。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”说卫生状况，与“在行”的意思不构成反义。"}, {"text": "便宜", "is_correct": false, "explanation": "无反义关系：“便宜”说价格，与“在行”不构成反义。"}], "correct_answer": "外行", "explanations": {"外行": "外行指对某事不懂、不熟练，与“在行”意思相反。", "高兴": "无反义关系：“高兴”说心情，与“在行”指做事能力无关。", "干净": "无反义关系：“干净”说卫生状况，与“在行”的意思不构成反义。", "便宜": "无反义关系：“便宜”说价格，与“在行”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94361, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外行", "is_correct": true, "explanation": "外行指对某事不懂、不熟练，与“在行”意思相反。"}, {"text": "热闹", "is_correct": false, "explanation": "无反义关系：“热闹”形容场面，与“在行”指人的懂行不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线或颜色，与“在行”不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "无反义关系：“柔软”形容质地，与“在行”不构成反义。"}], "correct_answer": "外行", "explanations": {"外行": "外行指对某事不懂、不熟练，与“在行”意思相反。", "热闹": "无反义关系：“热闹”形容场面，与“在行”指人的懂行不构成反义。", "明亮": "无反义关系：“明亮”形容光线或颜色，与“在行”不构成反义。", "柔软": "无反义关系：“柔软”形容质地，与“在行”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94361, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在行是对某件事很懂，做得很好。", "primary_collocate": null, "pronunciation": "zài háng", "ipa": "tsaɪ˥˩ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他对修电脑很在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到做饭，我妈妈最在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对买衣服不太在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对养花很在行，家里的花开得特别好。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥对汽车很在行，一听声音就知道哪里坏了。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对音乐很在行，帮我选一首歌吧。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做菜一点儿也不在行，常常把菜烧糊了。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要买手机的话，问小王吧，他最在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对跳舞不在行，只会跳几步。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李下棋很在行，大家都下不过他。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不在行", "label": "否定式"}], "register": "口语", "sense_fingerprint": "对某事很懂、做得好；常说“对……很在行”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在行", "is_correct": true, "explanation": "正确：“在行”表示对某事很懂、做得好，与“对修电脑很”搭配，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材，不能用来说对修电脑的懂行程度。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容环境或声音，不能说“对修电脑很吵闹”。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”说的是情绪，不能描述对修电脑的熟悉和能力。"}], "explanations": {"在行": "正确：“在行”表示对某事很懂、做得好，与“对修电脑很”搭配，符合句意。", "高大": "体貌：“高大”形容人的身材，不能用来说对修电脑的懂行程度。", "吵闹": "搭配：“吵闹”形容环境或声音，不能说“对修电脑很吵闹”。", "悲伤": "语义：“悲伤”说的是情绪，不能描述对修电脑的熟悉和能力。"}, "sentence_index": 0, "correct_answer": "在行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机很在行，能自己判断衣服的材质。", "explanation": "这里应该用〈先进〉。“在行”说的是人对某事懂、做得好，只用于人；形容洗衣机的功能要用“先进”。"}, {"text": "这份计划很在行，大家都觉得它很有道理。", "explanation": "这里应该用〈合理〉。“在行”说的是人对某事懂、做得好，计划不是人，不能用来说计划有道理。"}, {"text": "这篇文章对语法很在行，一个错别字都没有。", "explanation": "这里应该用〈规范〉。“在行”说的是人对某事懂、做得好，只用于人；形容文章的语法正确要用“规范”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在行", "is_correct": true, "explanation": "正确：“在行”与“一点儿也不”搭配，表示做菜能力差，与后句“烧糊了”相合。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说年龄，不能说“做菜一点儿也不年轻”。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能用来说做菜。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：“晴朗”说天气，与做菜的能力无关。"}], "explanations": {"在行": "正确：“在行”与“一点儿也不”搭配，表示做菜能力差，与后句“烧糊了”相合。", "年轻": "搭配：“年轻”说年龄，不能说“做菜一点儿也不年轻”。", "清澈": "搭配：“清澈”形容水或眼神，不能用来说做菜。", "晴朗": "语义：“晴朗”说天气，与做菜的能力无关。"}, "sentence_index": 6, "correct_answer": "在行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雨下得很在行，正好解了旱。", "explanation": "这里应该用〈及时〉。“在行”说的是人对某事懂、做得好，只用于人；形容雨下得正好要用“及时”。"}, {"text": "这个小区的门禁很在行，每次都能认出住户的脸。", "explanation": "这里应该用〈智能〉。“在行”只用于人对某事懂、做得好；形容门禁认人的功能要用“智能”。"}, {"text": "这座桥很在行，能承受很重的货车。", "explanation": "这里应该用〈结实〉。“在行”说的是人对某事懂、做得好，只用于人；形容桥能承重要用“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给做饭很在行，朋友都爱吃我做的菜。", "corrected_sentence": "我对做饭很在行，朋友都爱吃我做的菜。", "error_description": "介词错误：“在行”引出的对象要用介词“对”，应说“对做饭很在行”，不能用“给”说“给做饭很在行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老李给下棋很在行，大家都下不过他。", "corrected_sentence": "老李对下棋很在行，大家都下不过他。", "error_description": "介词错误：“在行”引出的对象要用介词“对”，应说“对下棋很在行”，不能用“给”说“给下棋很在行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94362, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外行", "is_correct": true, "explanation": "外行指对某种工作不熟悉、没有经验，与“在行”意思相反。"}, {"text": "轻松", "is_correct": false, "explanation": "无反义关系：“轻松”说心情或做事的难易，与“在行”不构成反义。"}, {"text": "干燥", "is_correct": false, "explanation": "无反义关系：“干燥”形容物体的湿度，与“在行”不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "无反义关系：“粗糙”形容质地，与“在行”不构成反义。"}], "correct_answer": "外行", "explanations": {"外行": "外行指对某种工作不熟悉、没有经验，与“在行”意思相反。", "轻松": "无反义关系：“轻松”说心情或做事的难易，与“在行”不构成反义。", "干燥": "无反义关系：“干燥”形容物体的湿度，与“在行”不构成反义。", "粗糙": "无反义关系：“粗糙”形容质地，与“在行”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94362, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外行", "is_correct": true, "explanation": "外行指对某种工作不熟悉、没有经验，与“在行”意思相反。"}, {"text": "热情", "is_correct": false, "explanation": "无反义关系：“热情”形容待人的态度，与“在行”不构成反义。"}, {"text": "温暖", "is_correct": false, "explanation": "无反义关系：“温暖”形容温度或感受，与“在行”不构成反义。"}, {"text": "尖锐", "is_correct": false, "explanation": "无反义关系：“尖锐”形容形状或言辞，与“在行”不构成反义。"}], "correct_answer": "外行", "explanations": {"外行": "外行指对某种工作不熟悉、没有经验，与“在行”意思相反。", "热情": "无反义关系：“热情”形容待人的态度，与“在行”不构成反义。", "温暖": "无反义关系：“温暖”形容温度或感受，与“在行”不构成反义。", "尖锐": "无反义关系：“尖锐”形容形状或言辞，与“在行”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94362, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对某种事情或工作很熟悉、有经验。", "primary_collocate": null, "pronunciation": "zài háng", "ipa": "tsaɪ˥˩ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他做了十年销售，对这一行很在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王师傅修了三十年车，对修车很在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你去找李经理，他最在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当过老师，对教孩子很在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚来公司，对这里的工作还不在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意他很在行，一眼就看出哪个货好。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张在工厂干了一辈子，对机器非常在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对写文章不在行，但对画画很在行。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找人帮忙装修，一定要找在行的人。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对股票在行吗？我想听听你的看法。", "target_word": "在行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不在行", "label": "否定式"}], "register": "口语", "sense_fingerprint": "对某种工作很熟悉、有经验", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在行", "is_correct": true, "explanation": "正确：“在行”表示对这一行很熟悉、有经验，与“做了十年销售”相合。"}, {"text": "年幼", "is_correct": false, "explanation": "语义：“年幼”说年纪小，与“做了十年销售”矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容环境，不能说“对这一行很吵闹”。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”说的是情绪，不能描述对行业的熟悉程度。"}], "explanations": {"在行": "正确：“在行”表示对这一行很熟悉、有经验，与“做了十年销售”相合。", "年幼": "语义：“年幼”说年纪小，与“做了十年销售”矛盾。", "吵闹": "搭配：“吵闹”形容环境，不能说“对这一行很吵闹”。", "悲伤": "语义：“悲伤”说的是情绪，不能描述对行业的熟悉程度。"}, "sentence_index": 0, "correct_answer": "在行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座工厂对生产很在行，产量每年都翻一番。", "explanation": "这里应该用〈高效〉。“在行”说的是人对某种工作有经验，只用于人；形容工厂的生产效率要用“高效”。"}, {"text": "这个方案对市场很在行，但是没人愿意用。", "explanation": "这里应该用〈切合实际〉。“在行”说的是人对某种工作有经验，方案不是人，不能用来说方案切合市场。"}, {"text": "这把刀用来切肉很在行，切出的肉片又薄又整齐。", "explanation": "这里应该用〈锋利〉。“在行”说的是人对某种工作有经验，只用于人，不能用来形容刀的好用程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在行", "is_correct": true, "explanation": "正确：“在行”表示对机器很熟悉、有经验，与“干了一辈子”相合。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年纪，与“干了一辈子”矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的性格，不能用来说对机器的熟悉程度。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能说“对机器非常清澈”。"}], "explanations": {"在行": "正确：“在行”表示对机器很熟悉、有经验，与“干了一辈子”相合。", "年轻": "语义：“年轻”说年纪，与“干了一辈子”矛盾。", "幽默": "语义：“幽默”形容人的性格，不能用来说对机器的熟悉程度。", "清澈": "搭配：“清澈”形容水或眼神，不能说“对机器非常清澈”。"}, "sentence_index": 6, "correct_answer": "在行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视很在行，能自动调到你想看的频道。", "explanation": "这里应该用〈智能〉。“在行”说的是人对某种工作有经验，只用于人；形容电视的功能要用“智能”。"}, {"text": "我的身体很在行，每天都能跑步。", "explanation": "这里应该用〈健康〉。“在行”说的是人对某种工作有经验，不能用来说身体的状况。"}, {"text": "这辆公交车很在行，每个站都停得很准。", "explanation": "这里应该用〈准确〉。“在行”说的是人对某种工作有经验，公交车是物，不能用来说它停得准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他修过很多车，给汽车很在行，朋友都找他帮忙。", "corrected_sentence": "他修过很多车，对汽车很在行，朋友都找他帮忙。", "error_description": "介词错误：“在行”的对象要用介词“对”引出，应说“对汽车很在行”，不能用“给”说“给汽车很在行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老张把机器非常在行，朋友都找他帮忙。", "corrected_sentence": "老张对机器非常在行，朋友都找他帮忙。", "error_description": "介词错误：“在行”的对象要用介词“对”引出，应说“对机器非常在行”，不能用“把”说“把机器非常在行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
