INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自愿登记姓名，参加某项活动或学习。", "primary_collocate": null, "pronunciation": "bào míng", "ipa": "pɑʊ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我想报名参加下个月的汉语考试。", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你报名了吗？", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经报了名，明天就开始上课。", "target_word": "报了名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上报名参加了游泳班。", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名要带身份证。", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天去学校报名了。", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天是最后一天报名。", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想报名学画画吗？", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有报过名，所以不能参加。", "target_word": "报过名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟哭着要报名踢足球。", "target_word": "报名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "報名", "label": "繁体"}, {"form": "报了名", "label": "完成体"}, {"form": "报过名", "label": "经历体"}], "register": "通用", "sense_fingerprint": "登记姓名以参加活动、比赛、考试或学习班", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报名", "is_correct": true, "explanation": "“报名”指登记姓名以参加考试，与“参加下个月的汉语考试”搭配，句意通顺。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要文字类宾语，不能以“参加”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“参加考试”搭配，“我想吃参加……”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能用于“参加考试”，“我想洗参加……”无意义。"}], "explanations": {"报名": "“报名”指登记姓名以参加考试，与“参加下个月的汉语考试”搭配，句意通顺。", "写": "配价：“写”需要文字类宾语，不能以“参加”作宾语。", "吃": "搭配：“吃”不能与“参加考试”搭配，“我想吃参加……”不成立。", "洗": "搭配：“洗”不能用于“参加考试”，“我想洗参加……”无意义。"}, "sentence_index": 0, "correct_answer": "报名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天去超市报名，买了两斤苹果。", "explanation": "这里应该用〈购买〉。报名指登记参加活动或学习，买东西要用购买。"}, {"text": "我昨天去派出所报名，说钱包丢了。", "explanation": "这里应该用〈报案〉。报名指自愿登记参加活动，报告丢失要用报案。"}, {"text": "我今天去快递站报名，把包裹寄走了。", "explanation": "这里应该用〈寄〉。报名指登记参加活动，寄包裹要用寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报名", "is_correct": true, "explanation": "“报名”指登记参加，用于“最后一天”，表示报名截止日期，句意通顺。"}, {"text": "开始", "is_correct": false, "explanation": "语义：“开始”与“最后一天”矛盾，“明天是最后一天开始”说不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”与报名期限无关，不能说“最后一天迟到”指报名截止。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”需要宾语，“明天是最后一天挂”缺少宾语，不成立。"}], "explanations": {"报名": "“报名”指登记参加，用于“最后一天”，表示报名截止日期，句意通顺。", "开始": "语义：“开始”与“最后一天”矛盾，“明天是最后一天开始”说不通。", "迟到": "语义：“迟到”与报名期限无关，不能说“最后一天迟到”指报名截止。", "挂": "配价：“挂”需要宾语，“明天是最后一天挂”缺少宾语，不成立。"}, "sentence_index": 6, "correct_answer": "报名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天去医院报名看医生。", "explanation": "这里应该用〈挂号〉。报名指登记参加活动或学习，看病前登记要用挂号。"}, {"text": "我们昨天去饭店报名，订了两间房。", "explanation": "这里应该用〈预订〉。报名指登记参加活动，订房间要用预订。"}, {"text": "他每年都去税务局报名。", "explanation": "这里应该用〈报税〉。报名指登记参加活动，向税务局申报收入要用报税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没报了名参加汉语班。", "corrected_sentence": "他没报名参加汉语班。", "error_description": "否定与“了”冲突：用“没”否定时不能再加表示完成的“了”，应说“他没报名参加汉语班”。（肯定句可以说“报了名”。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天了报名，下周开始上课。", "corrected_sentence": "我今天报了名，下周开始上课。", "error_description": "“了”应插在离合词“报”和“名”之间，说“报了名”；“了报名”位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
