INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大哥是家里年纪最大的哥哥。", "primary_collocate": null, "pronunciation": "dà gē", "ipa": "ta⁵¹ kɤ⁵⁵", "syllable_count": 2, "sentences": [{"text": "我大哥比我大十岁。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家三个孩子，年纪最大的是大哥。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥在北京工作，一年只回家一次。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有三个哥哥，大哥排行最大。", "target_word": "大哥", "complexity_tier": "T3", "furigana": "dà gē", "sentence_source": "generated"}, {"text": "大哥常常帮妈妈做饭。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，大哥给我买了新衣服。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥已经结婚了，住在上海。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，大哥每天送我去学校。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不在家时，大哥照顾着我们。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥说，弟弟妹妹要好好学习。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "家里年纪最大的哥哥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89da991-ce23-4a2a-800d-16d17cb3d807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弟弟", "is_correct": false, "explanation": "语义：弟弟比“我”年纪小，说“比我大十岁”语义矛盾。"}, {"text": "妹妹", "is_correct": false, "explanation": "语义：妹妹一般比“我”年纪小，与“比我大十岁”相矛盾。"}, {"text": "大哥", "is_correct": true, "explanation": "正确：“大哥”指家中年纪比“我”大的哥哥，符合“比我大十岁”。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“比我大十岁”只能用于人，不说小猫的年龄比人大。"}], "explanations": {"弟弟": "语义：弟弟比“我”年纪小，说“比我大十岁”语义矛盾。", "妹妹": "语义：妹妹一般比“我”年纪小，与“比我大十岁”相矛盾。", "大哥": "正确：“大哥”指家中年纪比“我”大的哥哥，符合“比我大十岁”。", "小猫": "搭配：“比我大十岁”只能用于人，不说小猫的年龄比人大。"}, "sentence_index": 0, "correct_answer": "大哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家三个孩子，最小的那个是大哥，今年才五岁。", "explanation": "这里应该用〈小弟〉。“大哥”指家中年纪最大的哥哥，不能指最小的孩子。"}, {"text": "我的大哥比我小三岁，每天都跟我一起上学。", "explanation": "这里应该用〈弟弟〉。“大哥”指年纪比自己大的哥哥，不能用来称呼比自己小的弟弟。"}, {"text": "我家三个孩子，大哥是长女，最懂事。", "explanation": "这里应该用〈大姐〉。“大哥”指男性哥哥，不能指姐姐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小孩", "is_correct": false, "explanation": "语义：小孩不会结婚，与句中“已经结婚了”相矛盾。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生不会结婚，与“已经结婚了”语义不合。"}, {"text": "大哥", "is_correct": true, "explanation": "正确：“大哥”指家中年长的哥哥，能够结婚并住在上海。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：结婚的主语只能是人，“冰箱”不能作为“结婚”的主语。"}], "explanations": {"小孩": "语义：小孩不会结婚，与句中“已经结婚了”相矛盾。", "小学生": "语义：小学生不会结婚，与“已经结婚了”语义不合。", "大哥": "正确：“大哥”指家中年长的哥哥，能够结婚并住在上海。", "冰箱": "搭配：结婚的主语只能是人，“冰箱”不能作为“结婚”的主语。"}, "sentence_index": 6, "correct_answer": "大哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我最小的大哥今年五岁，正在上幼儿园。", "explanation": "这里应该用〈弟弟〉。“大哥”是家中年纪最大的哥哥，不能指家里最小的孩子。"}, {"text": "我爸爸是我的大哥，每天都带我去学校。", "explanation": "这里应该用〈父亲〉。“大哥”指家中年纪最大的哥哥，不能用来指父亲。"}, {"text": "我的大哥是爸爸的弟弟，常来我家吃饭。", "explanation": "这里应该用〈叔叔〉。“大哥”是自己的哥哥，父亲的弟弟应称“叔叔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有两个大哥，大哥在北京工作。", "corrected_sentence": "我家有两个孩子，大哥在北京工作。", "error_description": "错误在于“两个大哥”。“大哥”指家中年纪最大的哥哥，全家只有一个，不能说“两个大哥”，应说“两个孩子”或“两个哥哥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我大大哥刚搬到广州，工作很忙。", "corrected_sentence": "我大哥刚搬到广州，工作很忙。", "error_description": "错误在于多加了一个“大”。“大哥”是一个固定称呼，前面不能再加“大”，应说“我大哥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
