INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来称呼年纪比自己大的男子（多为非亲属）。", "primary_collocate": null, "pronunciation": "dà gē", "ipa": "ta⁵¹ kɤ⁵⁵", "syllable_count": 2, "sentences": [{"text": "大哥，请问去火车站怎么走？", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大哥帮我提了很重的行李。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大哥，你的钱包掉在地上了。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在队里年纪最大，大家都叫他大哥。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥，谢谢你送我回家。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥，前面路口是不是要左转？", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开出租车的大哥一路上都在和我们聊天。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在隔壁的大哥比我大很多岁。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥，你的车不能停在这儿。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖水果的大哥多送了我两个苹果。", "target_word": "大哥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "对年纪比自己大的男子的称呼，多为非亲属，口语招呼用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89da991-ce23-4a2a-800d-16d17cb3d807') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能用来招呼路人问路，句子不通。"}, {"text": "火车", "is_correct": false, "explanation": "语义：“火车”是交通工具，不能用来称呼问路的人，句子不通。"}, {"text": "大哥", "is_correct": true, "explanation": "正确：“大哥”是对年长男子的称呼，用于句首招呼路人。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：对陌生人称“小猫”，语义不通，句子无法成立。"}], "explanations": {"桌子": "语义：“桌子”是家具，不能用来招呼路人问路，句子不通。", "火车": "语义：“火车”是交通工具，不能用来称呼问路的人，句子不通。", "大哥": "正确：“大哥”是对年长男子的称呼，用于句首招呼路人。", "小猫": "语义：对陌生人称“小猫”，语义不通，句子无法成立。"}, "sentence_index": 0, "correct_answer": "大哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在车站见到一个大哥，他只有五岁。", "explanation": "这里应该用〈小朋友〉。“大哥”指年纪比自己大的男子，不能用来称呼五岁的孩子。"}, {"text": "那位大哥比我年轻，看起来只有十五岁。", "explanation": "这里应该用〈小兄弟〉。“大哥”用于称呼年纪比自己大的男子，称呼比自己年轻的人应说“小兄弟”。"}, {"text": "我向一位老奶奶问路，先叫了她一声“大哥”。", "explanation": "这里应该用〈奶奶〉。“大哥”只用来称呼年纪比自己大的男子，不能称呼女性长辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不会开出租车，句子语义不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不会开出租车，句子语义不通。"}, {"text": "大哥", "is_correct": true, "explanation": "正确：“大哥”指开出租车的年长男子，符合句中的情境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不会开出租车，句子语义不通。"}], "explanations": {"冰箱": "语义：“冰箱”不会开出租车，句子语义不通。", "石头": "语义：“石头”不会开出租车，句子语义不通。", "大哥": "正确：“大哥”指开出租车的年长男子，符合句中的情境。", "窗户": "语义：“窗户”不会开出租车，句子语义不通。"}, "sentence_index": 6, "correct_answer": "大哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路边的小男孩才六岁，我叫他“大哥”问路。", "explanation": "这里应该用〈小朋友〉。“大哥”称呼比自己年纪大的男子，不能称呼小孩。"}, {"text": "这位卖水果的女士，大家都叫她大哥。", "explanation": "这里应该用〈大姐〉。“大哥”指男性，称呼女性要用“大姐”。"}, {"text": "我对着一条小狗说：“大哥，请让一让。”", "explanation": "这里不该用〈大哥〉。“大哥”是对人的称呼，不能用来称呼动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站门口有一只热心的大哥。", "corrected_sentence": "车站门口有一位热心的大哥。", "error_description": "错误在于量词“只”。“大哥”指人，量词应用“位”或“个”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那天我在工地上遇到了三大哥，他们都很热情。", "corrected_sentence": "那天我在工地上遇到了三位大哥，他们都很热情。", "error_description": "错误在于数词与“大哥”之间缺少量词。“三大哥”应为“三位大哥”或“三个大哥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93cbdbdf-3edb-4a6b-9b0e-bf7fd691bc5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94371, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义：难受与好受相反，指身心不舒服。"}, {"text": "舒适", "is_correct": false, "explanation": "近义：舒适与好受意思相近，不是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：清楚指明白或分明，不是“好受”的反义词。"}, {"text": "热情", "is_correct": false, "explanation": "无关：热情指态度亲切积极，与“好受”不构成反义。"}], "correct_answer": "难受", "explanations": {"难受": "反义：难受与好受相反，指身心不舒服。", "舒适": "近义：舒适与好受意思相近，不是反义词。", "清楚": "无关：清楚指明白或分明，不是“好受”的反义词。", "热情": "无关：热情指态度亲切积极，与“好受”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94371, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义：难受与好受相反，指身心不舒服。"}, {"text": "舒服", "is_correct": false, "explanation": "近义：舒服与好受意思相近，不是反义词。"}, {"text": "轻松", "is_correct": false, "explanation": "无关：轻松指心情放松或不费力，与“好受”不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静指声音小或心神平静，与“好受”不构成反义。"}], "correct_answer": "难受", "explanations": {"难受": "反义：难受与好受相反，指身心不舒服。", "舒服": "近义：舒服与好受意思相近，不是反义词。", "轻松": "无关：轻松指心情放松或不费力，与“好受”不构成反义。", "安静": "无关：安静指声音小或心神平静，与“好受”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94371, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好受是身体或心里舒服，不难过。", "primary_collocate": null, "pronunciation": "hǎo shòu", "ipa": "xɑʊ˨˩˦ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "听你这么说，我心里好受一点了。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，他心里不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说出来以后，她心里好受多了。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到朋友难过，我也不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评了他，他心里很不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭了一场，心里好受了很多。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错了事，我一直不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别哭了，这样我更不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟妈妈聊了聊，我好受些了。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷生病了，全家人心里都不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不好受", "label": "否定式"}], "register": "口语", "sense_fingerprint": "身体或心里舒服，不难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94371, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好受", "is_correct": true, "explanation": "好受（hǎo shòu）指心里舒服、不难过，是正确答案。"}, {"text": "好手", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，好手指技艺高超的人，不是好受。"}, {"text": "好透", "is_correct": false, "explanation": "sh 与 t 声母不同，tòu（第四声）意思是彻底，不是好受。"}, {"text": "好肉", "is_correct": false, "explanation": "sh 与 r 声母不同，ròu（第四声）指好的肉，不是好受。"}], "explanations": {"好受": "好受（hǎo shòu）指心里舒服、不难过，是正确答案。", "好手": "shǒu（第三声）与 shòu（第四声）声调不同，好手指技艺高超的人，不是好受。", "好透": "sh 与 t 声母不同，tòu（第四声）意思是彻底，不是好受。", "好肉": "sh 与 r 声母不同，ròu（第四声）指好的肉，不是好受。"}, "sentence_index": null, "correct_answer": "好受"}, "level_3": {"options": [{"text": "好受", "is_correct": true, "explanation": "正确：好受表示心里舒服、不难过，与“听你这么说”的安慰语境相符。"}, {"text": "难过", "is_correct": false, "explanation": "语义：“心里难过一点了”与“听你这么说”的安慰语境相反。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：伤心加重，与“听你这么说”的安慰语境矛盾。"}, {"text": "烦躁", "is_correct": false, "explanation": "语义：烦躁指心里急躁不安，与“听你这么说”的安慰语境相反。"}], "explanations": {"好受": "正确：好受表示心里舒服、不难过，与“听你这么说”的安慰语境相符。", "难过": "语义：“心里难过一点了”与“听你这么说”的安慰语境相反。", "伤心": "语义：伤心加重，与“听你这么说”的安慰语境矛盾。", "烦躁": "语义：烦躁指心里急躁不安，与“听你这么说”的安慰语境相反。"}, "sentence_index": 0, "correct_answer": "好受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题很好受。", "explanation": "这里应该用〈容易〉。好受形容身心感受，形容题目难易要说容易。"}, {"text": "这张木桌很好受。", "explanation": "这里应该用〈结实〉。好受形容身心感受，形容桌子坚固要说结实。"}, {"text": "他写的字很好受。", "explanation": "这里应该用〈好看〉。好受形容身心感受，形容字迹美观要说好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好受", "is_correct": true, "explanation": "正确：“不好受”表示心里难过、不舒服，与“做错了事”的语境相符。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌或样子，不能用来说心里的感受。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”只用于食物，不能用来形容心里的感受。"}, {"text": "好笑", "is_correct": false, "explanation": "语义：“不好笑”与“做错了事”后的懊悔语境不符，句意不通。"}], "explanations": {"好受": "正确：“不好受”表示心里难过、不舒服，与“做错了事”的语境相符。", "好看": "搭配：“好看”形容外貌或样子，不能用来说心里的感受。", "好吃": "搭配：“好吃”只用于食物，不能用来形容心里的感受。", "好笑": "语义：“不好笑”与“做错了事”后的懊悔语境不符，句意不通。"}, "sentence_index": 6, "correct_answer": "好受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很好受。", "explanation": "这里应该用〈好吃〉。好受形容身心感受，形容味道要说好吃。"}, {"text": "这间房子很好受。", "explanation": "这里应该用〈宽敞〉。好受形容身心感受，形容房间大小要说宽敞。"}, {"text": "他的文章写得很好受。", "explanation": "这里应该用〈精彩〉。好受形容身心感受，形容文章好坏要说精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把事情讲出来，心里好受的很多。", "corrected_sentence": "他把事情讲出来，心里好受了很多。", "error_description": "错误：“好受”后面的“了”不能换成“的”。应说“心里好受了很多”，不能说“心里好受的很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哭了一场以后，他心里好受多多了。", "corrected_sentence": "哭了一场以后，他心里好受多了。", "error_description": "错误：“多了”是固定的补语，不能重复“多”。应说“好受多了”，不能说“好受多多了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94372, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义：难受与好受相反，指身心不舒服。"}, {"text": "舒服", "is_correct": false, "explanation": "近义：舒服与好受意思相近，不是反义词。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：高兴指心情愉快，不是“好受”的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静指声音小或心神平静，与“好受”不构成反义。"}], "correct_answer": "难受", "explanations": {"难受": "反义：难受与好受相反，指身心不舒服。", "舒服": "近义：舒服与好受意思相近，不是反义词。", "高兴": "无关：高兴指心情愉快，不是“好受”的反义词。", "安静": "无关：安静指声音小或心神平静，与“好受”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94372, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义：难受与好受相反，指身心不舒服。"}, {"text": "舒适", "is_correct": false, "explanation": "近义：舒适与好受意思相近，不是反义词。"}, {"text": "清醒", "is_correct": false, "explanation": "无关：清醒指头脑明白，不是“好受”的反义词。"}, {"text": "轻松", "is_correct": false, "explanation": "无关：轻松指心情放松或不费力，与“好受”不构成反义。"}], "correct_answer": "难受", "explanations": {"难受": "反义：难受与好受相反，指身心不舒服。", "舒适": "近义：舒适与好受意思相近，不是反义词。", "清醒": "无关：清醒指头脑明白，不是“好受”的反义词。", "轻松": "无关：轻松指心情放松或不费力，与“好受”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94372, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身心感到舒适，不难受。", "primary_collocate": null, "pronunciation": "hǎo shòu", "ipa": "xɑʊ˨˩˦ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "吃了药以后，他好受多了。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发烧的时候，身体一点也不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了热水，胃里好受些了。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热了，坐在车里真不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休息一会儿，你就会好受一点。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿受伤了，走路很不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打了针，她觉得好受多了。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里太闷，大家都不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗了热水澡，我身上好受了。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咳嗽得很厉害，他一晚上都不好受。", "target_word": "好受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不好受", "label": "否定式"}], "register": "口语", "sense_fingerprint": "身心感到舒适，不难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94372, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好受", "is_correct": true, "explanation": "好受（hǎo shòu）指身心舒服、不难受，是正确答案。"}, {"text": "好手", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，好手指技艺高超的人，不是好受。"}, {"text": "好透", "is_correct": false, "explanation": "sh 与 t 声母不同，tòu（第四声）意思是彻底，不是好受。"}, {"text": "好肉", "is_correct": false, "explanation": "sh 与 r 声母不同，ròu（第四声）指好的肉，不是好受。"}], "explanations": {"好受": "好受（hǎo shòu）指身心舒服、不难受，是正确答案。", "好手": "shǒu（第三声）与 shòu（第四声）声调不同，好手指技艺高超的人，不是好受。", "好透": "sh 与 t 声母不同，tòu（第四声）意思是彻底，不是好受。", "好肉": "sh 与 r 声母不同，ròu（第四声）指好的肉，不是好受。"}, "sentence_index": null, "correct_answer": "好受"}, "level_3": {"options": [{"text": "好受", "is_correct": true, "explanation": "正确：好受表示身体舒服，与“吃了药以后”后的状态相符。"}, {"text": "难受", "is_correct": false, "explanation": "语义：吃了药后“难受多了”与药效的语境相反，句意矛盾。"}, {"text": "严重", "is_correct": false, "explanation": "搭配：“严重”多用于病情，不说人“严重多了”。"}, {"text": "无力", "is_correct": false, "explanation": "语义：吃药后“无力多了”与好转的语境相反。"}], "explanations": {"好受": "正确：好受表示身体舒服，与“吃了药以后”后的状态相符。", "难受": "语义：吃了药后“难受多了”与药效的语境相反，句意矛盾。", "严重": "搭配：“严重”多用于病情，不说人“严重多了”。", "无力": "语义：吃药后“无力多了”与好转的语境相反。"}, "sentence_index": 0, "correct_answer": "好受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌很好受。", "explanation": "这里应该用〈好听〉。好受形容身心感受，形容歌曲要说好听。"}, {"text": "这个苹果很好受。", "explanation": "这里应该用〈甜〉。好受形容身心感受，形容水果味道要说甜。"}, {"text": "他的作业很好受。", "explanation": "这里应该用〈工整〉。好受形容身心感受，形容作业书写要说工整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好受", "is_correct": true, "explanation": "正确：好受表示身心舒服，与“打了针，她觉得好受多了”的语境相符。"}, {"text": "痛苦", "is_correct": false, "explanation": "语义：打针后“痛苦多了”与“觉得好受”的语境相反。"}, {"text": "难看", "is_correct": false, "explanation": "搭配：“难看”形容外貌，不能说感觉“难看多了”。"}, {"text": "烦躁", "is_correct": false, "explanation": "语义：“烦躁多了”与打针后好转的语境矛盾。"}], "explanations": {"好受": "正确：好受表示身心舒服，与“打了针，她觉得好受多了”的语境相符。", "痛苦": "语义：打针后“痛苦多了”与“觉得好受”的语境相反。", "难看": "搭配：“难看”形容外貌，不能说感觉“难看多了”。", "烦躁": "语义：“烦躁多了”与打针后好转的语境矛盾。"}, "sentence_index": 6, "correct_answer": "好受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布很好受。", "explanation": "这里应该用〈柔软〉。好受形容身心感受，形容布料要说柔软。"}, {"text": "这条路很好受。", "explanation": "这里应该用〈平坦〉。好受形容身心感受，形容路面要说平坦。"}, {"text": "这把刀很好受。", "explanation": "这里应该用〈锋利〉。好受形容身心感受，形容刀刃要说锋利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他躺下歇了会儿，觉得好受得些了。", "corrected_sentence": "他躺下歇了会儿，觉得好受些了。", "error_description": "错误：“好受”后面直接接“些”，中间不能加“得”。应说“好受些了”，不能说“好受得些了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
