INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94373, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姐妹是同一个家里的姐姐和妹妹。", "primary_collocate": null, "pronunciation": "jiě mèi", "ipa": "tɕjɛ˨˩ meɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们家有两个孩子，是一对姐妹。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是亲姐妹，长得很像。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对姐妹从小一起长大。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹两个常常在一起写作业。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个姐姐，我们姐妹感情很好。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们姐妹三人都住在北京。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，姐妹俩常常抢着吃糖。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对姐妹长得很像，我常常分不清。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是同一个妈妈生的姐妹。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和妹妹是姐妹，我们长得不太像。", "target_word": "姐妹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "姐妹俩", "label": "复合词"}, {"form": "姐妹们", "label": "复数"}, {"form": "一对姐妹", "label": "量词"}], "register": "中性", "sense_fingerprint": "同一个家里的姐姐和妹妹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d2d70b6-ac57-4e79-91fc-40c06fd2346c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94373, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "姐妹", "is_correct": true, "explanation": "正确：“姐妹”指同一家里的姐姐和妹妹，与“一对”搭配，符合句意。"}, {"text": "耳环", "is_correct": false, "explanation": "语义：“耳环”是首饰，不能指家里的两个孩子。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“一对”用于成双成对的东西，“空气”不能说“一对空气”。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：“筷子”是餐具，与“我们家有两个孩子”的句意不合。"}], "explanations": {"姐妹": "正确：“姐妹”指同一家里的姐姐和妹妹，与“一对”搭配，符合句意。", "耳环": "语义：“耳环”是首饰，不能指家里的两个孩子。", "空气": "搭配：“一对”用于成双成对的东西，“空气”不能说“一对空气”。", "筷子": "语义：“筷子”是餐具，与“我们家有两个孩子”的句意不合。"}, "sentence_index": 0, "correct_answer": "姐妹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥哥和弟弟是姐妹，他们常常一起打篮球。", "explanation": "这里应该用〈兄弟〉。“姐妹”只指女性的姐姐和妹妹，两个男孩是兄弟。"}, {"text": "妈妈和女儿是姐妹，她们常常一起去逛街。", "explanation": "这里应该用〈母女〉。“姐妹”指同辈的姐姐和妹妹，妈妈和女儿不是同辈。"}, {"text": "我和舅舅是姐妹，我们常常一起去钓鱼。", "explanation": "这里应该用〈舅甥〉。“姐妹”只指同一家里的姐姐和妹妹，舅舅是男性长辈，不能用“姐妹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94373, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "姐妹", "is_correct": true, "explanation": "正确：“姐妹俩”指两个姐妹，与“小时候”的语境相合。"}, {"text": "夫妻", "is_correct": false, "explanation": "语义：“夫妻”是成年人的婚姻关系，与“小时候”不合。"}, {"text": "同事", "is_correct": false, "explanation": "语义：“同事”指工作中的关系，与“小时候”不合。"}, {"text": "老头", "is_correct": false, "explanation": "语义：“老头”指一位老年男性，不能说“老头俩”，也与“小时候”不合。"}], "explanations": {"姐妹": "正确：“姐妹俩”指两个姐妹，与“小时候”的语境相合。", "夫妻": "语义：“夫妻”是成年人的婚姻关系，与“小时候”不合。", "同事": "语义：“同事”指工作中的关系，与“小时候”不合。", "老头": "语义：“老头”指一位老年男性，不能说“老头俩”，也与“小时候”不合。"}, "sentence_index": 6, "correct_answer": "姐妹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸和儿子是姐妹，他们每天一起去公园。", "explanation": "这里应该用〈父子〉。“姐妹”指同辈的女性亲属，父亲与儿子不是姐妹。"}, {"text": "张先生和张太太是姐妹，他们结婚二十年了。", "explanation": "这里应该用〈夫妻〉。“姐妹”只指同一家里的姐姐和妹妹，不指婚姻关系。"}, {"text": "叔叔和侄女是姐妹，他们常常一起去看电影。", "explanation": "这里应该用〈叔侄〉。“姐妹”指同辈的女性，叔叔与侄女不是同辈姐妹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94373, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有两个女孩，是一条姐妹。", "corrected_sentence": "我家有两个女孩，是一对姐妹。", "error_description": "量词错误：“条”用于细长的物件，不能搭配“姐妹”；指两个女孩应说“一对姐妹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94373, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楼下住着一张姐妹，她们长得很像。", "corrected_sentence": "楼下住着一对姐妹，她们长得很像。", "error_description": "量词错误：“张”用于平面的东西，如纸、桌子，不能搭配“姐妹”；指两个姐妹应说“一对姐妹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f2b96e-2640-4894-9b82-5b27da690f02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
