INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94375, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94375, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "孩子们是很多个小孩子。", "primary_collocate": null, "pronunciation": "hái zi men", "ipa": "xaɪ̯˧˥ tsɹ̩ mən", "syllable_count": 3, "sentences": [{"text": "孩子们在公园里玩得很开心。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着孩子们去参观博物馆。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都喜欢吃冰淇淋。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课了，孩子们跑出教室。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在院子里踢足球。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给孩子们讲了一个故事。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，孩子们都收到了红包。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们唱着歌走进了学校。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下得很大，孩子们高兴地堆雪人。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都睡着了，房子里很安静。", "target_word": "孩子们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孩子們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多个孩子（复数）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "搭配：“们”多用于人，不能说“课本们”。"}, {"text": "孩子们", "is_correct": true, "explanation": "正确。“孩子们”指很多个小孩子，可以作“玩”的主语。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会玩，不能“在公园里玩得很开心”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感受，不能“玩得很开心”。"}], "explanations": {"课本": "搭配：“们”多用于人，不能说“课本们”。", "孩子们": "正确。“孩子们”指很多个小孩子，可以作“玩”的主语。", "桌子": "语义：桌子不会玩，不能“在公园里玩得很开心”。", "石头": "语义：石头没有感受，不能“玩得很开心”。"}, "sentence_index": 0, "correct_answer": "孩子们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天娶了孩子们。", "explanation": "这里应该用〈妻子〉。“孩子们”指很多个小孩子，不能作为结婚的对象，“娶”应搭配“妻子”。"}, {"text": "这家餐厅的孩子们很好吃。", "explanation": "这里应该用〈菜〉。“孩子们”指小孩子，不能用来说食物好不好吃。"}, {"text": "这辆车的孩子们很便宜。", "explanation": "这里应该用〈价钱〉。“孩子们”指小孩子，不能用来说明汽车的价钱高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小狗们", "is_correct": false, "explanation": "语义：小狗不会收红包，不能说“小狗们都收到了红包”。"}, {"text": "孩子们", "is_correct": true, "explanation": "正确。“孩子们”是多个孩子，过年时收到红包的正是他们。"}, {"text": "书包们", "is_correct": false, "explanation": "搭配：“们”一般用于人或动物，不用于“书包”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能收红包，与“都收到了”搭配不通。"}], "explanations": {"小狗们": "语义：小狗不会收红包，不能说“小狗们都收到了红包”。", "孩子们": "正确。“孩子们”是多个孩子，过年时收到红包的正是他们。", "书包们": "搭配：“们”一般用于人或动物，不用于“书包”。", "电脑": "语义：电脑不能收红包，与“都收到了”搭配不通。"}, "sentence_index": 6, "correct_answer": "孩子们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的孩子们很厚。", "explanation": "这里应该用〈页数〉。“孩子们”指小孩子，不能用来说明书的厚薄。"}, {"text": "这首歌的孩子们很好听。", "explanation": "这里应该用〈旋律〉。“孩子们”指小孩子，不能用来评价歌曲好听不好听。"}, {"text": "他家的孩子们只有一个。", "explanation": "这里应该用〈孩子〉。“孩子们”指多个孩子，“只有一个”要用单数的“孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们们在河边钓鱼。", "corrected_sentence": "孩子们在河边钓鱼。", "error_description": "“们”是复数后缀，只加一次。“孩子们们”重复了“们”，应改为“孩子们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "过年时，城里得孩子们都收到了红包。", "corrected_sentence": "过年时，城里的孩子们都收到了红包。", "error_description": "修饰“孩子们”的助词应是“的”，不能用“得”。“得”用于动词后作补语，不能放在“城里”和“孩子们”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
