INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94383, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "平安是没有出事，人好好的。", "primary_collocate": null, "pronunciation": "píng ān", "ipa": "pʰiŋ˧˥ an˥", "syllable_count": 2, "sentences": [{"text": "孩子们都平安，请你不要担心。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到你平安到家，我就放心了。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，他给家人打电话说自己很平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸平安回来了，妈妈笑了。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要家人平安，我就很高兴。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们都平安吗？奶奶一直在问。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他前几天遇到车祸，幸好人很平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人希望孩子们一年到头都平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他在山里迷过路，但人很平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大雨，村里的人都平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平平安安", "label": "重叠"}, {"form": "平安夜", "label": "复合"}], "register": "中性", "sense_fingerprint": "人没有出事、身体好好的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，与“请你不要担心”的语境没有关系，句意不通。"}, {"text": "平安", "is_correct": true, "explanation": "平安指没有出事、人好好的，符合“孩子们都……，请你不要担心”的句意。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能说“孩子们都热闹”。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外貌，与后句安心的语境不相关，句意不通。"}], "explanations": {"高大": "体貌：“高大”形容身材或外形，与“请你不要担心”的语境没有关系，句意不通。", "平安": "平安指没有出事、人好好的，符合“孩子们都……，请你不要担心”的句意。", "热闹": "搭配：“热闹”形容场面或气氛，不能说“孩子们都热闹”。", "漂亮": "语义：“漂亮”说外貌，与后句安心的语境不相关，句意不通。"}, "sentence_index": 0, "correct_answer": "平安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片湖的水面很平安，一点波纹也没有。", "explanation": "这里应该用〈平静〉。平静指水面、心情没有波动，可以说“水面很平静”；平安指人或事没有出事，不能用来形容水面。"}, {"text": "这张桌子的桌面很平安，适合写字。", "explanation": "这里应该用〈平坦〉。平坦指表面没有起伏，可以说“桌面很平坦”；平安指人没有出事，不能形容桌面。"}, {"text": "他的心跳很平安，医生说没有问题。", "explanation": "这里应该用〈平稳〉。平稳指心跳、速度等没有起伏，可以说“心跳很平稳”；平安指人没有出事，不能形容心跳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严重", "is_correct": false, "explanation": "搭配：“严重”形容伤势或事故，不说“人很严重”。"}, {"text": "平安", "is_correct": true, "explanation": "平安指没有出事、人没有受伤，符合“遇到车祸，幸好”的语境。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”说家境，与“遇到车祸，幸好”的语境不相关，句意不通。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，与车祸、幸好的语境无关。"}], "explanations": {"严重": "搭配：“严重”形容伤势或事故，不说“人很严重”。", "平安": "平安指没有出事、人没有受伤，符合“遇到车祸，幸好”的语境。", "富裕": "语义：“富裕”说家境，与“遇到车祸，幸好”的语境不相关，句意不通。", "矮小": "体貌：“矮小”形容身材，与车祸、幸好的语境无关。"}, "sentence_index": 6, "correct_answer": "平安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听了音乐，他的心情很平安。", "explanation": "这里应该用〈平静〉。平静指心情没有波动，可以说“心情很平静”；平安指人没有出事，不能形容心情。"}, {"text": "他的性格很平安，从不跟人争吵。", "explanation": "这里应该用〈平和〉。平和指性情温和，可以说“性格很平和”；平安指人没有出事，不能形容性格。"}, {"text": "这台机器运转得很平安，没有噪音。", "explanation": "这里应该用〈平顺〉。平顺指运转、行进流畅，可以说“运转很平顺”；平安指人没有出事，不能形容机器运转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从医院出来以后，人得平安。", "corrected_sentence": "他从医院出来以后，人很平安。", "error_description": "程度副词误用：“得”不能修饰形容词“平安”，应改为“很”，说“人很平安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们很都平安，别担心。", "corrected_sentence": "孩子们都很平安，别担心。", "error_description": "副词语序错误：应说“都很平安”，“都”在前、“很”在后，不能说“很都平安”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94384, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危险", "is_correct": true, "explanation": "危险与“平安”构成反义，指有事故或威胁，与没有危险的“平安”相对。"}, {"text": "寂静", "is_correct": false, "explanation": "寂静指非常安静，与“平安”不是反义关系。"}, {"text": "清爽", "is_correct": false, "explanation": "清爽指干净舒服，与“平安”不是反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙指事情很多，与“平安”不是反义关系。"}], "correct_answer": "危险", "explanations": {"危险": "危险与“平安”构成反义，指有事故或威胁，与没有危险的“平安”相对。", "寂静": "寂静指非常安静，与“平安”不是反义关系。", "清爽": "清爽指干净舒服，与“平安”不是反义关系。", "繁忙": "繁忙指事情很多，与“平安”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94384, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危险", "is_correct": true, "explanation": "危险与“平安”构成反义，指有事故或威胁，与没有危险的“平安”相对。"}, {"text": "富足", "is_correct": false, "explanation": "富足指物质充裕，与“平安”不是反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情指待人亲切积极，与“平安”不是反义关系。"}, {"text": "便利", "is_correct": false, "explanation": "便利指方便、容易办事，与“平安”不是反义关系。"}], "correct_answer": "危险", "explanations": {"危险": "危险与“平安”构成反义，指有事故或威胁，与没有危险的“平安”相对。", "富足": "富足指物质充裕，与“平安”不是反义关系。", "热情": "热情指待人亲切积极，与“平安”不是反义关系。", "便利": "便利指方便、容易办事，与“平安”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94384, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有事故，没有危险，安全。", "primary_collocate": null, "pronunciation": "píng ān", "ipa": "pʰiŋ˧˥ an˥", "syllable_count": 2, "sentences": [{"text": "祝你一路平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行很平安，路上没出什么事。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车要小心，这样才能一路平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去一年，工厂没出过事故，很平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年春运很平安，没有发生事故。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在海上走了三天，一直很平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车一路平安地到达了北京。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你们新的一年出入平安。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机最重要的是平安到达。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，奶奶总叮嘱我们“路上要平安”。", "target_word": "平安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平平安安", "label": "重叠"}, {"form": "平安夜", "label": "复合"}], "register": "中性", "sense_fingerprint": "路途、地方、过程没有事故和危险，安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所或场面没有人气，说“一路冷清”句意不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或东西好看，不能用来祝“一路”的状态。"}, {"text": "平安", "is_correct": true, "explanation": "平安指一路上没有事故、没有危险，符合祝福语的语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，不能用于一路的状态。"}], "explanations": {"冷清": "语义：“冷清”形容场所或场面没有人气，说“一路冷清”句意不通。", "漂亮": "搭配：“漂亮”形容外貌或东西好看，不能用来祝“一路”的状态。", "平安": "平安指一路上没有事故、没有危险，符合祝福语的语境。", "高大": "体貌：“高大”形容身材或外形，不能用于一路的状态。"}, "sentence_index": 0, "correct_answer": "平安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的物价很平安，大家生活很踏实。", "explanation": "这里应该用〈平稳〉。平稳指价格没有大起大落，可以说“物价很平稳”；平安指没有事故或危险，不用于形容物价。"}, {"text": "这部电影的节奏很平安，观众不会觉得累。", "explanation": "这里应该用〈平淡〉。平淡指没有起伏、不够精彩，可以说“节奏很平淡”；平安指没有事故，不能形容节奏。"}, {"text": "他说话的语气很平安，一点也不生气。", "explanation": "这里应该用〈平和〉。平和指语气、性情温和，可以说“语气很平和”；平安指没有事故或危险，不能形容语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荒凉", "is_correct": false, "explanation": "语义：“荒凉”形容地方没有人烟，不能修饰“到达”，“一路荒凉地到达”不成立。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：“陌生”表示不熟悉，不能修饰“到达”。"}, {"text": "平安", "is_correct": true, "explanation": "平安指一路没有事故、没有危险，“一路平安地到达”句意通顺。"}, {"text": "简陋", "is_correct": false, "explanation": "语义：“简陋”形容房屋或设施粗糙，不能修饰“到达”。"}], "explanations": {"荒凉": "语义：“荒凉”形容地方没有人烟，不能修饰“到达”，“一路荒凉地到达”不成立。", "陌生": "搭配：“陌生”表示不熟悉，不能修饰“到达”。", "平安": "平安指一路没有事故、没有危险，“一路平安地到达”句意通顺。", "简陋": "语义：“简陋”形容房屋或设施粗糙，不能修饰“到达”。"}, "sentence_index": 6, "correct_answer": "平安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面墙的表面很平安，刷漆很方便。", "explanation": "这里应该用〈平整〉。平整指表面没有凹凸，可以说“墙面很平整”；平安指没有事故或危险，不能形容墙面。"}, {"text": "这段坡路很平安，老人走起来不累。", "explanation": "这里应该用〈平缓〉。平缓指坡度不陡，可以说“坡路很平缓”；平安指没有事故或危险，不能形容坡度。"}, {"text": "这篇文章读起来很平安。", "explanation": "这里应该用〈通顺〉。通顺指文章语句流畅，可以说“读起来很通顺”；平安指没有事故或危险，不能形容文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次出行一路比平安。", "corrected_sentence": "这次出行一路很平安。", "error_description": "程度副词用错：“比”表示比较，需要比较对象，单独说“一路比平安”不通；此处应用程度副词“很”，说“一路很平安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行我们走很平安。", "corrected_sentence": "这次旅行我们走得很平安。", "error_description": "补语标记缺失：动词后接状态补语要用“得”，应说“走得很平安”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94387, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
