INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94387, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "打小是从小的时候起。", "primary_collocate": null, "pronunciation": "dǎ xiǎo", "ipa": "ta˨˩˦ ɕiau˨˩˦", "syllable_count": 2, "sentences": [{"text": "他打小就爱画画。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打小就住在这个城市。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹打小身体不太好。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打小就是好朋友。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打小喜欢吃妈妈做的面。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷打小就不怕冷。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路我打小就走。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打小就会游泳。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打小没离开过家。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打小爱听故事。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "从小时候起就一直如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94387, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打小", "is_correct": true, "explanation": "打小：从小时候起。"}, {"text": "大小", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是大小（尺寸）。"}, {"text": "打下", "is_correct": false, "explanation": "xià（第四声）与 xiǎo 的韵母和声调都不同，意思是打下（攻取或奠定）。"}, {"text": "打鸟", "is_correct": false, "explanation": "niǎo 与 xiǎo 声母不同，意思是打鸟（猎取鸟类）。"}, {"text": "大笑", "is_correct": false, "explanation": "dà 与 dǎ、xiào 与 xiǎo 声调不同，意思是大笑。"}, {"text": "打消", "is_correct": false, "explanation": "xiāo（第一声）与 xiǎo（第三声）声调不同，意思是打消（放弃某个念头）。"}], "explanations": {"打小": "打小：从小时候起。", "大小": "dà（第四声）与 dǎ（第三声）声调不同，意思是大小（尺寸）。", "打下": "xià（第四声）与 xiǎo 的韵母和声调都不同，意思是打下（攻取或奠定）。", "打鸟": "niǎo 与 xiǎo 声母不同，意思是打鸟（猎取鸟类）。", "大笑": "dà 与 dǎ、xiào 与 xiǎo 声调不同，意思是大笑。", "打消": "xiāo（第一声）与 xiǎo（第三声）声调不同，意思是打消（放弃某个念头）。"}, "sentence_index": null, "correct_answer": "打小"}, "level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成，与“就爱画画”这种长期习惯不搭配。"}, {"text": "打小", "is_correct": true, "explanation": "打小表示从小时候起，与句中“他……就爱画画”的语境相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久之前，不能表示从童年起的长期习惯。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“爱画画”的长期习惯相矛盾。"}], "explanations": {"已经": "搭配：“已经”表示已经完成，与“就爱画画”这种长期习惯不搭配。", "打小": "打小表示从小时候起，与句中“他……就爱画画”的语境相符。", "刚刚": "语义：“刚刚”指不久之前，不能表示从童年起的长期习惯。", "偶尔": "语义：“偶尔”表示不常发生，与“爱画画”的长期习惯相矛盾。"}, "sentence_index": 0, "correct_answer": "打小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我打小在上海工作，后来调走了。", "explanation": "这里应该用〈以前〉。“打小”指从童年起，不能用于成年后的工作经历，说过去的工作要用“以前”。"}, {"text": "打小，我们只是普通同事。", "explanation": "这里应该用〈起初〉。“打小”指从童年起，不能用来说明后来才有的关系。"}, {"text": "打小，我正在厨房做饭。", "explanation": "这里应该用〈当时〉。“打小”只指从童年起的情况，不能指某一刻的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“打小就走”的长期经历相矛盾。"}, {"text": "打小", "is_correct": true, "explanation": "打小表示从小时候起，与句中“这条路我……就走”的语境相符。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于祈使句，不能修饰“就走”这样的陈述。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，与这句口语化的叙述不符。"}], "explanations": {"偶尔": "语义：“偶尔”表示不常发生，与“打小就走”的长期经历相矛盾。", "打小": "打小表示从小时候起，与句中“这条路我……就走”的语境相符。", "千万": "搭配：“千万”多用于祈使句，不能修饰“就走”这样的陈述。", "业已": "语域：“业已”是书面语，与这句口语化的叙述不符。"}, "sentence_index": 6, "correct_answer": "打小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "打小他当上了经理。", "explanation": "这里应该用〈后来〉。“打小”指从童年起，小孩子不会当上经理，不能用来说成年后的职位变化。"}, {"text": "他打小结过两次婚。", "explanation": "这里应该用〈曾经〉。“打小”指从童年起的状态，不能用来说成年后的经历，这类经历要用“曾经”。"}, {"text": "打小，他们结婚时很穷。", "explanation": "这里应该用〈当初〉。“打小”指从童年起，不能用来指结婚这样的具体时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹打小了爱跳舞。", "corrected_sentence": "我妹妹打小爱跳舞。", "error_description": "错误：“打小了”；正确：“打小”。“打小”是时间副词，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我奶奶打小了就在这个村里长大。", "corrected_sentence": "我奶奶打小就在这个村里长大。", "error_description": "错误：“打小了”；正确：“打小”。“打小”是时间副词，不能带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
