INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94388, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "方言，从小时候起。", "primary_collocate": null, "pronunciation": "dǎ xiǎo", "ipa": "ta˨˩˦ ɕiau˨˩˦", "syllable_count": 2, "sentences": [{"text": "俺打小就在村里长大。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打小就怕黑，现在也是。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打小就能吃苦。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱打小一块儿玩儿。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子打小就聪明。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张打小在北京长大。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打小就爱唱歌。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打小就跟着爷爷下地。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那小子打小就淘气。", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您打小就这么爱笑吗？", "target_word": "打小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "方言", "sense_fingerprint": "方言里表示从小时候起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打小", "is_correct": true, "explanation": "打小：方言，从小时候起。"}, {"text": "大小", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是大小（尺寸）。"}, {"text": "打鸟", "is_correct": false, "explanation": "niǎo 与 xiǎo 声母不同，意思是打鸟（猎取鸟类）。"}, {"text": "大笑", "is_correct": false, "explanation": "dà 与 dǎ、xiào 与 xiǎo 声调不同，意思是大笑。"}, {"text": "打消", "is_correct": false, "explanation": "xiāo（第一声）与 xiǎo（第三声）声调不同，意思是打消（放弃某个念头）。"}], "explanations": {"打小": "打小：方言，从小时候起。", "大小": "dà（第四声）与 dǎ（第三声）声调不同，意思是大小（尺寸）。", "打鸟": "niǎo 与 xiǎo 声母不同，意思是打鸟（猎取鸟类）。", "大笑": "dà 与 dǎ、xiào 与 xiǎo 声调不同，意思是大笑。", "打消": "xiāo（第一声）与 xiǎo（第三声）声调不同，意思是打消（放弃某个念头）。"}, "sentence_index": null, "correct_answer": "打小"}, "level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成，与“就在村里长大”这种持续的经历不搭配。"}, {"text": "打小", "is_correct": true, "explanation": "打小是方言，表示从小时候起，与句中“俺……就在村里长大”相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久之前，不能表示从童年起一直如此。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“在村里长大”的事实相矛盾。"}], "explanations": {"已经": "搭配：“已经”表示已经完成，与“就在村里长大”这种持续的经历不搭配。", "打小": "打小是方言，表示从小时候起，与句中“俺……就在村里长大”相符。", "刚刚": "语义：“刚刚”指不久之前，不能表示从童年起一直如此。", "从不": "语义：“从不”表示从来没有，与“在村里长大”的事实相矛盾。"}, "sentence_index": 0, "correct_answer": "打小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "打小咱俩一块儿结过婚。", "explanation": "这里应该用〈当年〉。“打小”指从童年起，不能用来说明成年后的婚姻经历，要用“当年”。"}, {"text": "打小他是村里的会计。", "explanation": "这里应该用〈原先〉。“打小”指从童年起，不能用来说明后来的职务，过去的职务要用“原先”。"}, {"text": "打小我在县城当兵。", "explanation": "这里应该用〈那会儿〉。“打小”指从童年起，不能用来说明成年后某段时间的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“爱唱歌”这种长期习惯相矛盾。"}, {"text": "打小", "is_correct": true, "explanation": "打小是方言，表示从小时候起，与句中“她……就爱唱歌”相符。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于祈使句，不能修饰“就爱唱歌”这样的陈述。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，与这句口语化的叙述不符。"}], "explanations": {"偶尔": "语义：“偶尔”表示不常发生，与“爱唱歌”这种长期习惯相矛盾。", "打小": "打小是方言，表示从小时候起，与句中“她……就爱唱歌”相符。", "千万": "搭配：“千万”多用于祈使句，不能修饰“就爱唱歌”这样的陈述。", "业已": "语域：“业已”是书面语，与这句口语化的叙述不符。"}, "sentence_index": 6, "correct_answer": "打小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "打小他在外地做生意。", "explanation": "这里应该用〈早年〉。“打小”指从童年起，不能用来说明成年后的经商经历，较早的时期要用“早年”。"}, {"text": "打小我们在山里修路。", "explanation": "这里应该用〈那年〉。“打小”指从童年起，不能用来说明某一年的具体事情。"}, {"text": "打小他大学毕业后进了工厂。", "explanation": "这里应该用〈后来〉。“打小”指从童年起，不能与“大学毕业”这类成年经历同用，应改用“后来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "咱俩打小了就认识。", "corrected_sentence": "咱俩打小就认识。", "error_description": "错误：“打小了”；正确：“打小”。“打小”是副词，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她打小了就会做饭。", "corrected_sentence": "她打小就会做饭。", "error_description": "错误：“打小了”；正确：“打小”。“打小”是时间副词，不能带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
