INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94389, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把玩是拿在手里看，喜欢地摸来摸去。", "primary_collocate": null, "pronunciation": "bǎ wán", "ipa": "pa˨˩˦ wan˧˥", "syllable_count": 2, "sentences": [{"text": "他坐在桌前，手里把玩着一块小石头。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢把玩那两个旧核桃。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿起玉镯，在手里慢慢把玩。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子把玩了一会儿新买的小汽车。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边听音乐，一边把玩手里的打火机。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块老砚台，他每天都要拿出来把玩一下。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把玩过很多古钱币，最喜欢这一枚。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常拿着那只小木鸟，反复把玩。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友送我一枚印章，我天天把玩，舍不得放下。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在树下，手里把玩着两颗光滑的玉球。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把玩着", "label": "体标：着"}, {"form": "把玩了", "label": "体标：了"}, {"form": "把玩过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "拿在手里反复地看，喜爱地摸来摸去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 镯 (Zipf 2.13)']::text[], 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "把玩", "is_correct": true, "explanation": "把玩：拿在手里看、喜欢地摸，正是本词的意思。"}, {"text": "打完", "is_correct": false, "explanation": "dǎwán（第三声）与 bǎwán 的声母不同（d 与 b），意思是打完，不是拿在手里玩。"}, {"text": "扒完", "is_correct": false, "explanation": "bāwán（第一声）与 bǎwán 声调不同，意思是扒完（饭）。"}, {"text": "拔完", "is_correct": false, "explanation": "báwán（第二声）与 bǎwán 声调不同，意思是拔完（草）。"}], "explanations": {"把玩": "把玩：拿在手里看、喜欢地摸，正是本词的意思。", "打完": "dǎwán（第三声）与 bǎwán 的声母不同（d 与 b），意思是打完，不是拿在手里玩。", "扒完": "bāwán（第一声）与 bǎwán 声调不同，意思是扒完（饭）。", "拔完": "báwán（第二声）与 bǎwán 声调不同，意思是拔完（草）。"}, "sentence_index": null, "correct_answer": "把玩"}, "level_3": {"options": [{"text": "把玩", "is_correct": true, "explanation": "把玩：拿在手里反复看、摸，与「手里……着一块小石头」相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」的对象是衣物，小石头不能穿。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写」的对象须是文字，不能说「写着一块小石头」。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象须是食物，小石头不能吃。"}], "explanations": {"把玩": "把玩：拿在手里反复看、摸，与「手里……着一块小石头」相合。", "穿": "搭配：「穿」的对象是衣物，小石头不能穿。", "写": "搭配：「写」的对象须是文字，不能说「写着一块小石头」。", "吃": "搭配：「吃」的对象须是食物，小石头不能吃。"}, "sentence_index": 0, "correct_answer": "把玩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在展厅里把玩那幅名画。", "explanation": "这里应该用〈欣赏〉。把玩指拿在手里摸着看，挂在墙上的名画不能拿在手里把玩。"}, {"text": "孩子们在操场上把玩滑梯。", "explanation": "这里应该用〈玩耍〉。把玩只用于可以拿在手里的小物件，滑梯是大型器械，不能拿在手里把玩。"}, {"text": "大家坐在看台上把玩那场比赛。", "explanation": "这里应该用〈观看〉。把玩只用于小物件，比赛只能观看，不能拿在手里把玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "把玩", "is_correct": true, "explanation": "把玩：拿在手里摸着看，「过」表示的经历正是这个动作。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食材，古钱币不能煮。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，古钱币不能唱。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：「吞」的对象是可以咽下的东西，不能用于收藏古钱币。"}], "explanations": {"把玩": "把玩：拿在手里摸着看，「过」表示的经历正是这个动作。", "煮": "搭配：「煮」的对象是食材，古钱币不能煮。", "唱": "搭配：「唱」的对象是歌曲，古钱币不能唱。", "吞": "搭配：「吞」的对象是可以咽下的东西，不能用于收藏古钱币。"}, "sentence_index": 6, "correct_answer": "把玩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在院子里把玩那棵大树。", "explanation": "这里应该用〈修剪〉。把玩指拿在手里看、摸的小物件，大树不能拿在手里把玩。"}, {"text": "工人在车间把玩那台机床。", "explanation": "这里应该用〈操作〉。把玩指拿在手里玩赏的小件，机床是大型机器，要操作，不能拿在手里把玩。"}, {"text": "他把玩着一辆旧摩托车，准备出门。", "explanation": "这里应该用〈驾驶〉。把玩只用于小物件，摩托车是交通工具，不能拿在手里把玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她坐在窗边，正在把玩了一枚旧硬币。", "corrected_sentence": "她坐在窗边，正在把玩着一枚旧硬币。", "error_description": "「正在」表示动作进行中，应与「着」搭配，写作「正在把玩着一枚旧硬币」；「了」表示动作已完成，与「正在」相矛盾，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥把玩过一会儿新买的手表。", "corrected_sentence": "哥哥把玩了一会儿新买的手表。", "error_description": "「过」表示经历，不能与表示时段的「一会儿」连用；应说「把玩了一会儿」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
