INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿在手里玩赏。", "primary_collocate": null, "pronunciation": "bǎ wán", "ipa": "pa˨˩˦ wan˧˥", "syllable_count": 2, "sentences": [{"text": "他有一把旧折扇，闲时常拿出来把玩。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "收藏家小心地把玩着刚买来的紫砂壶。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件玉器值得慢慢把玩。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在手心里反复把玩那枚古币。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在店里把玩了半天，还是没舍得买。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很爱把玩手串，珠子都磨亮了。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里的文物只能看，不能拿起来把玩。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢把玩老怀表，听里面滴答的声音。", "target_word": "把玩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块石头他把玩过很多年了。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨天没事做，他就坐在窗边把玩那些旧邮票。", "target_word": "把玩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把玩着", "label": "体标：着"}, {"form": "把玩了", "label": "体标：了"}, {"form": "把玩过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "把小巧的玩物或藏品拿在手中欣赏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "把玩", "is_correct": true, "explanation": "把玩：拿在手里玩赏，正是本词的意思。"}, {"text": "打完", "is_correct": false, "explanation": "dǎwán（第三声）与 bǎwán 的声母不同（d 与 b），意思是打完，不是拿在手里玩。"}, {"text": "扒完", "is_correct": false, "explanation": "bāwán（第一声）与 bǎwán 声调不同，意思是扒完（饭）。"}, {"text": "拔完", "is_correct": false, "explanation": "báwán（第二声）与 bǎwán 声调不同，意思是拔完（草）。"}], "explanations": {"把玩": "把玩：拿在手里玩赏，正是本词的意思。", "打完": "dǎwán（第三声）与 bǎwán 的声母不同（d 与 b），意思是打完，不是拿在手里玩。", "扒完": "bāwán（第一声）与 bǎwán 声调不同，意思是扒完（饭）。", "拔完": "báwán（第二声）与 bǎwán 声调不同，意思是拔完（草）。"}, "sentence_index": null, "correct_answer": "把玩"}, "level_3": {"options": [{"text": "把玩", "is_correct": true, "explanation": "把玩：拿在手里欣赏、摸玩，符合「闲时常拿出来」的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，折扇不能吃。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食材，折扇不能煮。"}, {"text": "睡", "is_correct": false, "explanation": "配价：「睡」不能带「折扇」这样的宾语，「拿出来睡」句子不通。"}], "explanations": {"把玩": "把玩：拿在手里欣赏、摸玩，符合「闲时常拿出来」的语境。", "吃": "搭配：「吃」的对象是食物，折扇不能吃。", "煮": "搭配：「煮」的对象是食材，折扇不能煮。", "睡": "配价：「睡」不能带「折扇」这样的宾语，「拿出来睡」句子不通。"}, "sentence_index": 0, "correct_answer": "把玩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家站在山顶把玩日出。", "explanation": "这里应该用〈观赏〉。把玩指拿在手里看、摸，日出无法拿在手里，只能观赏。"}, {"text": "他坐在客厅里把玩电视节目。", "explanation": "这里应该用〈观看〉。把玩指拿在手里看、摸的小物件，电视节目不能拿在手里把玩。"}, {"text": "大家在展厅里把玩那幅油画。", "explanation": "这里应该用〈欣赏〉。油画挂在墙上，不能拿在手里把玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "把玩", "is_correct": true, "explanation": "把玩：拿起来看、摸，与「只能看，不能拿起来」形成对照。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，文物不能拿起来唱。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮品，文物不能拿起来喝。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：「跳」多带舞、绳等活动类对象，文物不能拿起来跳。"}], "explanations": {"把玩": "把玩：拿起来看、摸，与「只能看，不能拿起来」形成对照。", "唱": "搭配：「唱」的对象是歌曲，文物不能拿起来唱。", "喝": "搭配：「喝」的对象是饮品，文物不能拿起来喝。", "跳": "搭配：「跳」多带舞、绳等活动类对象，文物不能拿起来跳。"}, "sentence_index": 6, "correct_answer": "把玩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师在车间把玩那台大型发电机。", "explanation": "这里应该用〈检修〉。把玩指拿在手里玩赏的小件，发电机体积庞大，不能拿在手里把玩。"}, {"text": "工匠在把玩一座古塔。", "explanation": "这里应该用〈修复〉。把玩指拿在手里玩赏，古塔体积庞大，不能拿在手里把玩。"}, {"text": "他在草原上把玩一辆越野车。", "explanation": "这里应该用〈驾驶〉。把玩只用于小物件，越野车是交通工具，不能拿在手里把玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
