INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94391, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "投降是打不过了，就举起手不再打。", "primary_collocate": null, "pronunciation": "tóu xiáng", "ipa": "tʰoʊ˧˥ ɕiɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小明打不过哥哥，只好举手投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好了好了，我投降，不打了！", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷看见警察，马上举起手投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟玩游戏输了，笑着说他投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一直追着小猫，小猫最后举起小爪子投降了。", "target_word": "投降", "complexity_tier": "T3", "furigana": "xiǎo gǒu yìzhí zhuīzhe xiǎo māo, xiǎo māo zuìhòu jǔ qǐ xiǎo zhuǎzi tóuxiáng le.", "sentence_source": "generated"}, {"text": "你力气太大，我投降了。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩比赛掰手腕，我先投降了。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹跟我打枕头仗，她很快就投降了。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我投降，这道题我真的不会做。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被朋友挠得受不了，大声喊投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投降了", "label": "完成体"}, {"form": "投降过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "打不过对方时举手表示不再打，认输", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投降", "is_correct": true, "explanation": "正确：打不过时举手表示认输，就是“举手投降”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：打不过哥哥时举手，与“唱歌”毫无关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：这里是认输的动作，“吃饭”与打不过的语境不符。"}, {"text": "打招呼", "is_correct": false, "explanation": "搭配：“只好”后接的是不情愿的行为，“打招呼”与之不搭配。"}], "explanations": {"投降": "正确：打不过时举手表示认输，就是“举手投降”。", "唱歌": "语义：打不过哥哥时举手，与“唱歌”毫无关系。", "吃饭": "语义：这里是认输的动作，“吃饭”与打不过的语境不符。", "打招呼": "搭配：“只好”后接的是不情愿的行为，“打招呼”与之不搭配。"}, "sentence_index": 0, "correct_answer": "投降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和弟弟各让一步，最后投降了。", "explanation": "这里应该用〈妥协〉。投降是一方认输，双方各让一步要用妥协。"}, {"text": "他把硬币投降进了存钱罐。", "explanation": "这里应该用〈投〉。投降是打不过而认输，把硬币放进存钱罐应说投。"}, {"text": "他把论文投降到了期刊编辑部。", "explanation": "这里应该用〈投稿〉。投降是认输、停止抵抗，向期刊寄送稿件应说投稿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投降", "is_correct": true, "explanation": "正确：比赛输了、不再比下去，就是“投降”。"}, {"text": "散步", "is_correct": false, "explanation": "语义：掰手腕比输赢，“我先散步了”与比赛语境无关。"}, {"text": "读书", "is_correct": false, "explanation": "语义：比赛正在进行，“读书”与掰手腕的语境不符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：掰手腕比输赢，“我先游泳了”与比赛语境无关。"}], "explanations": {"投降": "正确：比赛输了、不再比下去，就是“投降”。", "散步": "语义：掰手腕比输赢，“我先散步了”与比赛语境无关。", "读书": "语义：比赛正在进行，“读书”与掰手腕的语境不符。", "游泳": "语义：掰手腕比输赢，“我先游泳了”与比赛语境无关。"}, "sentence_index": 6, "correct_answer": "投降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写错了一个字，大方地投降。", "explanation": "这里应该用〈认错〉。投降是在较量中认输，写错字只需要认错，不能说投降。"}, {"text": "老师提问，他很快举手投降。", "explanation": "这里应该用〈回答〉。投降是打不过就认输、不再打，课堂上想回答问题而抬手，不能说投降。"}, {"text": "他把宣传单投降到了每一户的门口。", "explanation": "这里应该用〈投放〉。投降是认输、停止抵抗，把宣传单投放到各户应说投放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这局我输定了，只好向他投降了了。", "corrected_sentence": "这局我输定了，只好向他投降了。", "error_description": "错误：“投降”后的“了”重复出现，应只用一个“了”，说“向他投降了”；“投降了了”多出一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一看见作业就举手了投降。", "corrected_sentence": "我一看见作业就举手投降。", "error_description": "错误：“举手投降”是固定说法，“了”不能插在“举手”和“投降”之间，应说“举手投降”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
