INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94392, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "停止抵抗，向对方认输屈服。", "primary_collocate": null, "pronunciation": "tóu xiáng", "ipa": "tʰoʊ˧˥ ɕiɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "敌人被包围了，最后只好投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打了三天，终于向我们投降了。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们放下枪，向对方投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对敌人，士兵们绝不投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家宣布投降了。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想投降，还想再打一次。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人被打败后举着白旗投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察喊他投降，他没有动。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军决定带着士兵投降。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的队伍从没向敌人投降过。", "target_word": "投降", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投降了", "label": "完成体"}, {"form": "投降过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "战争或对抗中停止抵抗，向对方认输屈服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fce33b4-294a-4fde-8b73-031a7542de3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投降", "is_correct": true, "explanation": "正确：走投无路、只能认输时，说“只好投降”。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”指迎接客人或来访者，不能用来形容被包围的敌人。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：敌人被包围、无路可走，与“庆祝”的欢喜语境矛盾。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：在被包围的紧急局面下，“结婚”与语境毫不相干。"}], "explanations": {"投降": "正确：走投无路、只能认输时，说“只好投降”。", "欢迎": "搭配：“欢迎”指迎接客人或来访者，不能用来形容被包围的敌人。", "庆祝": "语义：敌人被包围、无路可走，与“庆祝”的欢喜语境矛盾。", "结婚": "语义：在被包围的紧急局面下，“结婚”与语境毫不相干。"}, "sentence_index": 0, "correct_answer": "投降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "双方经过长时间谈判，终于投降了。", "explanation": "这里应该用〈妥协〉。投降是一方停止抵抗、认输，谈判中双方各让一步要用妥协。"}, {"text": "今天股价突然投降了。", "explanation": "这里应该用〈下降〉。投降是停止抵抗、认输，股价下跌要用下降。"}, {"text": "他把钥匙投降进了信箱。", "explanation": "这里应该用〈投进〉。投降指打仗时停止抵抗、屈服，把东西扔进信箱应说投进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投降", "is_correct": true, "explanation": "正确：举白旗表示认输，只能接“投降”。"}, {"text": "进攻", "is_correct": false, "explanation": "语义：举白旗是认输的信号，与“进攻”的意思矛盾。"}, {"text": "冲锋", "is_correct": false, "explanation": "语义：举白旗表示求和，不能用来形容“冲锋”。"}, {"text": "宣战", "is_correct": false, "explanation": "语义：举白旗是认输的信号，“宣战”是宣布开始打仗，意思正好相反。"}], "explanations": {"投降": "正确：举白旗表示认输，只能接“投降”。", "进攻": "语义：举白旗是认输的信号，与“进攻”的意思矛盾。", "冲锋": "语义：举白旗表示求和，不能用来形容“冲锋”。", "宣战": "语义：举白旗是认输的信号，“宣战”是宣布开始打仗，意思正好相反。"}, "sentence_index": 6, "correct_answer": "投降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们和对方投降，共同完成了这个项目。", "explanation": "这里应该用〈合作〉。投降是一方向对方认输，不能和对方一起完成事情。"}, {"text": "两国领导人在会议厅握手，签完协议后，双方很体面地投降。", "explanation": "这里应该用〈签约〉。投降指一方停止抵抗、屈服，双方签订协议应说签约。"}, {"text": "这家工厂今年陆续投降了三条生产线。", "explanation": "这里应该用〈投产〉。投降是停止抵抗、认输，生产线投入使用应说投产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那支军队最后还是向敌人很投降了。", "corrected_sentence": "那支军队最后还是向敌人投降了。", "error_description": "程度副词位置错误：“很”只能修饰形容词或状态，不能修饰动作动词“投降”；应说“向敌人投降了”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们最后还是被投降了。", "corrected_sentence": "他们最后还是投降了。", "error_description": "错误：“投降”是不及物动词，没有被动用法，前面不能加“被”。应改为“他们最后还是投降了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70843424-3a98-4c16-8363-24defb94f3d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
