INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94393, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "月老是故事里帮男女牵红线、让他们成为一家人的老人。", "primary_collocate": null, "pronunciation": "yuè lǎo", "ipa": "ɥɛ˥˩ lau˨˩˦", "syllable_count": 2, "sentences": [{"text": "故事里的月老用红线把两个人连在一起。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说月老手里有一根红线。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我讲了月老的故事。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月老坐在月光下，手里拿着红线。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的月老头发白白的，笑得很开心。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在画里看到了一位月老。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月老会把红线系在两个人的脚上。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月老找到了一对有缘的年轻人。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的月老很有意思。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的月老给他们牵了红线。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位月老", "label": "量词"}], "register": "中性", "sense_fingerprint": "故事里用红线把男女连在一起的老人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责牵红线，句中讲的是神话里牵线的老人。"}, {"text": "月老", "is_correct": true, "explanation": "月老是神话故事里牵红线的老人，与句中“用红线把两个人连在一起”相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能用红线把两个人连在一起，这一句写的是神话人物。"}, {"text": "阁下", "is_correct": false, "explanation": "语域：“阁下”是对听话人的书面敬称，不能充当童话叙述的主语。"}], "explanations": {"厨师": "语义：厨师不负责牵红线，句中讲的是神话里牵线的老人。", "月老": "月老是神话故事里牵红线的老人，与句中“用红线把两个人连在一起”相符。", "汽车": "语义：汽车不能用红线把两个人连在一起，这一句写的是神话人物。", "阁下": "语域：“阁下”是对听话人的书面敬称，不能充当童话叙述的主语。"}, "sentence_index": 0, "correct_answer": "月老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月老手里拿着弓箭，专门向人射去，让人相爱。", "explanation": "这里应该用〈丘比特〉。丘比特用箭射人，使人相爱；月老管牵红线，不射箭。"}, {"text": "她结婚多年没有孩子，天天去庙里拜月老，求个孩子。", "explanation": "这里应该用〈送子观音〉。送子观音管求子，月老管婚姻、牵红线，求孩子不能拜月老。"}, {"text": "月老手里拿着一袋金元宝，给穷人送去。", "explanation": "这里应该用〈财神〉。财神掌管财富，常被画成手拿元宝；月老只管牵红线，与财富无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医生", "is_correct": false, "explanation": "语义：医生不做牵红线、系脚的事，与神话里的婚姻之神不符。"}, {"text": "月老", "is_correct": true, "explanation": "月老是神话中牵红线的神，“会把红线系在两个人的脚上”正是他的做法。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能主动把红线系在人的脚上，句子需要有意识的施事。"}, {"text": "足下", "is_correct": false, "explanation": "语域：“足下”是书面敬称，只用于称呼对方，不能作叙述句的主语。"}], "explanations": {"医生": "语义：医生不做牵红线、系脚的事，与神话里的婚姻之神不符。", "月老": "月老是神话中牵红线的神，“会把红线系在两个人的脚上”正是他的做法。", "石头": "语义：石头不能主动把红线系在人的脚上，句子需要有意识的施事。", "足下": "语域：“足下”是书面敬称，只用于称呼对方，不能作叙述句的主语。"}, "sentence_index": 6, "correct_answer": "月老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村口来了一头月老，大家都围过去看。", "explanation": "这里应该用〈位〉。月老指神或人，计量用“位”；“头”只用于牛、猪等牲畜，不能用于神。"}, {"text": "我在路边遇见一棵月老。", "explanation": "这里应该用〈位〉。“棵”用于树木，不能用来计量神或人。"}, {"text": "桌上放着一把月老，旁边还有一杯茶。", "explanation": "这里应该用〈位〉。“把”用于有柄的器具，不能用来计量神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "故事里有一只月老，帮男女牵红线。", "corrected_sentence": "故事里有一位月老，帮男女牵红线。", "error_description": "错误：“一只月老”；正确：“一位月老”。“只”用于动物，指人或神要用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "传说里有一头月老，专管给人牵红线。", "corrected_sentence": "传说里有一位月老，专管给人牵红线。", "error_description": "错误：“一头月老”；正确：“一位月老”。“头”用于牲畜，指神或人要用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
