INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神话传说中掌管婚姻的神，也指媒人。", "primary_collocate": null, "pronunciation": "yuè lǎo", "ipa": "ɥɛ˥˩ lau˨˩˦", "syllable_count": 2, "sentences": [{"text": "中国人说月老管人间的婚姻。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人去庙里拜月老，希望找到爱人。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“你来当我们的月老吧！”", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友介绍他们认识，大家都叫他月老。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月老是神话里管婚姻的神。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他结婚时，特别感谢当月老的王阿姨。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想请姐姐给她当月老。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "七夕那天，不少女孩向月老许愿。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张老师做了一回月老，两个同事成了一家。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩能结婚，多亏了月老。", "target_word": "月老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位月老", "label": "量词"}], "register": "中性", "sense_fingerprint": "神话中掌管婚姻的神，也比喻媒人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "龙王", "is_correct": false, "explanation": "语义：龙王管水域，不管婚姻，句中“管人间的婚姻”只适合月老。"}, {"text": "月老", "is_correct": true, "explanation": "民间说月老管婚姻，与句中“管人间的婚姻”相符。"}, {"text": "老板", "is_correct": false, "explanation": "语义：老板管生意，不管婚姻，句子说的是管婚姻的神或媒人。"}, {"text": "陛下", "is_correct": false, "explanation": "语域：“陛下”是对帝王的尊称，不能用来指神或媒人。"}], "explanations": {"龙王": "语义：龙王管水域，不管婚姻，句中“管人间的婚姻”只适合月老。", "月老": "民间说月老管婚姻，与句中“管人间的婚姻”相符。", "老板": "语义：老板管生意，不管婚姻，句子说的是管婚姻的神或媒人。", "陛下": "语域：“陛下”是对帝王的尊称，不能用来指神或媒人。"}, "sentence_index": 0, "correct_answer": "月老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村里来了一头月老，大家都围过去看。", "explanation": "这里应该用〈位〉。月老指人或神，计量用“位”或“个”；“头”只用于牲畜，不能用于人。"}, {"text": "我家门口有一棵月老，人们常去拜。", "explanation": "这里应该用〈位〉。“棵”用于树木，不能用来计量人。"}, {"text": "他是一把月老，专门给人介绍对象。", "explanation": "这里应该用〈位〉。“把”用于有柄的器具，不能用来计量人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能给人做媒，句中的“当”要求能承担说媒角色的人。"}, {"text": "月老", "is_correct": true, "explanation": "月老在民间指做媒牵线的人，与“请姐姐给她当”的语境相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能帮人牵线，句子说的是请人做媒。"}, {"text": "足下", "is_correct": false, "explanation": "语域：“足下”是书面敬称，不能用作口语句中“当”的对象。"}], "explanations": {"石头": "语义：石头不能给人做媒，句中的“当”要求能承担说媒角色的人。", "月老": "月老在民间指做媒牵线的人，与“请姐姐给她当”的语境相符。", "课本": "语义：课本不能帮人牵线，句子说的是请人做媒。", "足下": "语域：“足下”是书面敬称，不能用作口语句中“当”的对象。"}, "sentence_index": 6, "correct_answer": "月老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村里的人在村口拜月老，求一年平安。", "explanation": "这里应该用〈土地公〉。土地公管一方平安，月老管婚姻、牵红线，求平安不能拜月老。"}, {"text": "孩子出生后，大家都去庙里拜月老。", "explanation": "这里应该用〈送子观音〉。送子观音管求子，月老管婚姻，不能用来求子。"}, {"text": "做生意的人都去庙里求月老保佑。", "explanation": "这里应该用〈财神〉。财神管财运，月老管婚姻，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "张阿姨是一条有名的月老，帮很多人找到了对象。", "corrected_sentence": "张阿姨是一位有名的月老，帮很多人找到了对象。", "error_description": "错误：“一条月老”；正确：“一位月老”。“条”用于细长的东西，指人要用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他帮朋友撮合了一对恋人，大家都说他是一只月老。", "corrected_sentence": "他帮朋友撮合了一对恋人，大家都说他是一位月老。", "error_description": "错误：“一只月老”；正确：“一位月老”。“只”用于动物，指人要用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94395, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无力", "is_correct": true, "explanation": "反义：“无力”是“有力”的反义词，指没有力气。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外表好看，与“有力”不构成反义。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：“寒冷”形容温度低，与“有力”不构成反义。"}, {"text": "清脆", "is_correct": false, "explanation": "无关：“清脆”形容声音清亮爽利，与“有力”不构成反义。"}], "correct_answer": "无力", "explanations": {"无力": "反义：“无力”是“有力”的反义词，指没有力气。", "漂亮": "无关：“漂亮”形容外表好看，与“有力”不构成反义。", "寒冷": "无关：“寒冷”形容温度低，与“有力”不构成反义。", "清脆": "无关：“清脆”形容声音清亮爽利，与“有力”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94395, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无力", "is_correct": true, "explanation": "反义：“无力”是“有力”的反义词，指没有力气。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”形容心情好，与“有力”不构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容智力高，与“有力”不构成反义。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：“便宜”形容价格低，与“有力”不构成反义。"}], "correct_answer": "无力", "explanations": {"无力": "反义：“无力”是“有力”的反义词，指没有力气。", "高兴": "无关：“高兴”形容心情好，与“有力”不构成反义。", "聪明": "无关：“聪明”形容智力高，与“有力”不构成反义。", "便宜": "无关：“便宜”形容价格低，与“有力”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94395, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有力是有很大的力气，很强。", "primary_collocate": null, "pronunciation": "yǒu lì", "ipa": "joʊ˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸的手又大又有力。", "target_word": "有力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这匹马的腿很有力。", "target_word": "有力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看起来很瘦，但是很有力。", "target_word": "有力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李的拳头很有力。", "target_word": "有力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，游泳时蹬腿要有力。", "target_word": "有力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个工人的肩膀宽而有力。", "target_word": "有力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用有力的手抱起了箱子。", "target_word": "有力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸟的翅膀非常有力。", "target_word": "有力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的每一步都走得很有力。", "target_word": "有力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动以后，我的身体更有力了。", "target_word": "有力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有力地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "身体或动作有很大的力气，很强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c3029d-e96d-4c4c-b73a-e938db1d64bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94395, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有力", "is_correct": true, "explanation": "正确答案：有力（yǒu lì），身体或动作有很大力气的意思。"}, {"text": "有礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，有礼是有礼貌的意思。"}, {"text": "有理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，有理是有道理的意思。"}, {"text": "有益", "is_correct": false, "explanation": "yì 与 lì 的声母不同（yì 没有声母 l），有益是有好处的意思。"}, {"text": "有意", "is_correct": false, "explanation": "yì 与 lì 的声母不同（yì 没有声母 l），有意是故意的意思。"}], "explanations": {"有力": "正确答案：有力（yǒu lì），身体或动作有很大力气的意思。", "有礼": "lǐ（第三声）与 lì（第四声）声调不同，有礼是有礼貌的意思。", "有理": "lǐ（第三声）与 lì（第四声）声调不同，有理是有道理的意思。", "有益": "yì 与 lì 的声母不同（yì 没有声母 l），有益是有好处的意思。", "有意": "yì 与 lì 的声母不同（yì 没有声母 l），有意是故意的意思。"}, "sentence_index": null, "correct_answer": "有力"}, "level_3": {"options": [{"text": "有力", "is_correct": true, "explanation": "有力：形容手有很大的力气，符合“又大又”的句意。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容土地、天空、海面广大，不用来形容手。"}, {"text": "雄伟", "is_correct": false, "explanation": "语义：“雄伟”形容山川、建筑庞大壮观，不能用来形容手。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼睛，不用来形容手的样子。"}], "explanations": {"有力": "有力：形容手有很大的力气，符合“又大又”的句意。", "辽阔": "语义：“辽阔”形容土地、天空、海面广大，不用来形容手。", "雄伟": "语义：“雄伟”形容山川、建筑庞大壮观，不能用来形容手。", "明亮": "搭配：“明亮”形容光线或眼睛，不用来形容手的样子。"}, "sentence_index": 0, "correct_answer": "有力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很有力。", "explanation": "这里应该用〈好吃〉。有力形容力气大，不用来形容菜的味道。"}, {"text": "屋子里很有力。", "explanation": "这里应该用〈温暖〉。有力说的是力气，不用来形容屋子的冷暖。"}, {"text": "教室里很有力。", "explanation": "这里应该用〈安静〉。有力形容力气大，不用来形容教室里的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94395, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有力", "is_correct": true, "explanation": "正确答案：有力（yǒu lì），身体或动作有很大力气的意思。"}, {"text": "有事", "is_correct": false, "explanation": "shì 与 lì 的声母不同（sh 与 l），有事是有事情要做的意思。"}, {"text": "有志", "is_correct": false, "explanation": "zhì 与 lì 的声母不同（zh 与 l），有志是有志向的意思。"}, {"text": "有戏", "is_correct": false, "explanation": "xì 与 lì 的声母不同（x 与 l），有戏是有希望、有可能的意思。"}, {"text": "有气", "is_correct": false, "explanation": "qì 与 lì 的声母不同（q 与 l），有气是有气息、有脾气的意思。"}], "explanations": {"有力": "正确答案：有力（yǒu lì），身体或动作有很大力气的意思。", "有事": "shì 与 lì 的声母不同（sh 与 l），有事是有事情要做的意思。", "有志": "zhì 与 lì 的声母不同（zh 与 l），有志是有志向的意思。", "有戏": "xì 与 lì 的声母不同（x 与 l），有戏是有希望、有可能的意思。", "有气": "qì 与 lì 的声母不同（q 与 l），有气是有气息、有脾气的意思。"}, "sentence_index": null, "correct_answer": "有力"}, "level_3": {"options": [{"text": "有力", "is_correct": true, "explanation": "有力：形容手有很大的力气，符合“用……的手抱起”的句意。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味，不能用来修饰手。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，手不能是甜的。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”形容味道或生活处境，不能用来描述手的力气。"}], "explanations": {"有力": "有力：形容手有很大的力气，符合“用……的手抱起”的句意。", "香": "搭配：“香”形容气味，不能用来修饰手。", "甜": "语义：“甜”形容味道，手不能是甜的。", "苦": "语义：“苦”形容味道或生活处境，不能用来描述手的力气。"}, "sentence_index": 6, "correct_answer": "有力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房间里更有力了。", "explanation": "这里应该用〈凉快〉。有力形容力气，不用来形容房间的凉热。"}, {"text": "书架更有力了。", "explanation": "这里应该用〈整齐〉。有力说的是力量，不用来形容书架摆放得整不整齐。"}, {"text": "花更有力了。", "explanation": "这里应该用〈鲜艳〉。有力形容力气大，不用来形容花的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他踢球踢很有力。", "corrected_sentence": "他踢球踢得很有力。", "error_description": "错误：“踢很有力”，漏掉了“得”。正确：“踢得很有力”。说动作达到的程度，要在动词后加“得”再接补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有力的抱着孩子。", "corrected_sentence": "他有力地抱着孩子。", "error_description": "错误：“有力的抱着”。正确：“有力地抱着”。修饰动词要用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173f4866-edbc-467b-8230-6737b11fb272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94397, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无能", "is_correct": true, "explanation": "“无能”与“有能力”相对，表示没有做事的本领。"}, {"text": "危险", "is_correct": false, "explanation": "“危险”说有可能受伤或出事，与做事能力无关，不是反义词。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”说容易做，与人的能力无关，不是“有能力”的反义词。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容地势，与做事能力无关，不是“有能力”的反义词。"}], "correct_answer": "无能", "explanations": {"无能": "“无能”与“有能力”相对，表示没有做事的本领。", "危险": "“危险”说有可能受伤或出事，与做事能力无关，不是反义词。", "方便": "“方便”说容易做，与人的能力无关，不是“有能力”的反义词。", "陡峭": "“陡峭”形容地势，与做事能力无关，不是“有能力”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94397, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无能", "is_correct": true, "explanation": "“无能”与“有能力”相对，表示没有做事的本领。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与人的能力无关，不是反义词。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度低，与人的能力无关，不是反义词。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧闹，与人的能力无关，不是反义词。"}], "correct_answer": "无能", "explanations": {"无能": "“无能”与“有能力”相对，表示没有做事的本领。", "明亮": "“明亮”形容光线或颜色，与人的能力无关，不是反义词。", "寒冷": "“寒冷”形容温度低，与人的能力无关，不是反义词。", "热闹": "“热闹”形容场面喧闹，与人的能力无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94397, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有能力是会做事，做得好。", "primary_collocate": null, "pronunciation": "yǒu néng lì", "ipa": "iou˨˩˦ nɤŋ˧˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "他是个很有能力的人。", "target_word": "有能力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新来的经理非常有能力。", "target_word": "有能力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都说她做事很有能力。", "target_word": "有能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司需要有能力的年轻人。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年纪不大，但是很有能力。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板喜欢聪明又有能力的员工。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不但漂亮，而且很有能力。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事认真，也很有能力，大家都信任他。", "target_word": "有能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有能力的人总能找到好工作。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师很有能力，学生们都很喜欢她。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容人会做事、做得好，常说很有能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有能力", "is_correct": true, "explanation": "正确答案。“很有能力的人”指做事能干、做得好。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”形容环境安静，不用来形容人，“很寂静的人”不通。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音，不能用来形容人，“很沙哑的人”说的是嗓子。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容天气或地面，不用来形容人。"}], "explanations": {"有能力": "正确答案。“很有能力的人”指做事能干、做得好。", "寂静": "搭配：“寂静”形容环境安静，不用来形容人，“很寂静的人”不通。", "沙哑": "语义：“沙哑”形容嗓音，不能用来形容人，“很沙哑的人”说的是嗓子。", "潮湿": "搭配：“潮湿”形容天气或地面，不用来形容人。"}, "sentence_index": 0, "correct_answer": "有能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很有能力，每天都有人来打扫。", "explanation": "这里应该用〈干净〉。“有能力”指人做事能干，形容房间整洁要用“干净”。"}, {"text": "这种药很有能力，吃两天就好了。", "explanation": "这里应该用〈有效〉。“有能力”指人做事能干，形容药物见效要用“有效”。"}, {"text": "他今天很有能力，早上七点就精神饱满地去跑步。", "explanation": "这里应该用〈有精神〉。“有能力”指做事的本领，形容精神饱满要用“有精神”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有能力", "is_correct": true, "explanation": "正确答案。“很有能力”说人做事能干，符合句意。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气或食物，不用来形容人的能力。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容面积大，与做事能力无关。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来形容人。"}], "explanations": {"有能力": "正确答案。“很有能力”说人做事能干，符合句意。", "干燥": "搭配：“干燥”形容空气或食物，不用来形容人的能力。", "辽阔": "语义：“辽阔”形容面积大，与做事能力无关。", "清脆": "搭配：“清脆”形容声音，不用来形容人。"}, "sentence_index": 6, "correct_answer": "有能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这周很有能力，可以陪你去逛街。", "explanation": "这里应该用〈有空〉。“有能力”指做事能干，表示有没有时间要用“有空”。"}, {"text": "你说的很有能力。", "explanation": "这里应该用〈有道理〉。“有能力”用于人，不能用来形容说的内容。"}, {"text": "这份报告很有能力，写得非常清楚。", "explanation": "“有能力”只用于能做事的人，报告不能说有能力，应说写得好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她做事非常很有能力，老板很放心。", "corrected_sentence": "她做事非常有能力，老板很放心。", "error_description": "程度副词重复：“有能力”前只能用一个程度副词，“非常很有能力”不对，应说“非常有能力”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位工程师很不有能力，大家都很佩服他。", "corrected_sentence": "这位工程师很有能力，大家都很佩服他。", "error_description": "否定词误用：“有”前不能加“不”，应说“很有能力”，去掉“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94398, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无能", "is_correct": true, "explanation": "“无能”与“有能力”相对，表示没有做事的本领。"}, {"text": "健康", "is_correct": false, "explanation": "“健康”说身体状况，与本领无关，不是“有能力”的反义词。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价格低，与本领无关，不是“有能力”的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”说明白、不模糊，与本领无关，不是“有能力”的反义词。"}], "correct_answer": "无能", "explanations": {"无能": "“无能”与“有能力”相对，表示没有做事的本领。", "健康": "“健康”说身体状况，与本领无关，不是“有能力”的反义词。", "便宜": "“便宜”说价格低，与本领无关，不是“有能力”的反义词。", "清楚": "“清楚”说明白、不模糊，与本领无关，不是“有能力”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94398, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无能", "is_correct": true, "explanation": "“无能”与“有能力”相对，表示没有做事的本领。"}, {"text": "安全", "is_correct": false, "explanation": "“安全”说没有危险，与本领无关，不是“有能力”的反义词。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”说没有污物，与本领无关，不是“有能力”的反义词。"}, {"text": "遥远", "is_correct": false, "explanation": "“遥远”说距离远，与本领无关，不是“有能力”的反义词。"}], "correct_answer": "无能", "explanations": {"无能": "“无能”与“有能力”相对，表示没有做事的本领。", "安全": "“安全”说没有危险，与本领无关，不是“有能力”的反义词。", "干净": "“干净”说没有污物，与本领无关，不是“有能力”的反义词。", "遥远": "“遥远”说距离远，与本领无关，不是“有能力”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94398, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具备做某事的本领和条件。", "primary_collocate": null, "pronunciation": "yǒu néng lì", "ipa": "iou˨˩˦ nɤŋ˧˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "他有能力完成这个任务。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有能力一个人照顾两个孩子。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等你有能力养活自己了，就可以帮助别人。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司有能力给每个员工买保险。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经有能力自己赚钱了。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要你有能力帮忙，就应该多帮助家人。", "target_word": "有能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有能力治疗很重的病。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有能力说服他，你不用担心。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们有能力解决这个问题。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有能力买车，但是喜欢坐地铁。", "target_word": "有能力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "后面接动词，表示具备做某事的本领和条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有能力", "is_correct": true, "explanation": "正确答案。“有能力”表示具备完成任务的本领，符合句意。"}, {"text": "无能", "is_correct": false, "explanation": "语义：“无能”指没有本领，与句中“完成这个任务”的能力正好相反。"}, {"text": "有名", "is_correct": false, "explanation": "搭配：“有名”说的是出名，不能用来说明完成任务的本领。"}, {"text": "健忘", "is_correct": false, "explanation": "语义：“健忘”指记性差，与完成任务所需的本领无关。"}], "explanations": {"有能力": "正确答案。“有能力”表示具备完成任务的本领，符合句意。", "无能": "语义：“无能”指没有本领，与句中“完成这个任务”的能力正好相反。", "有名": "搭配：“有名”说的是出名，不能用来说明完成任务的本领。", "健忘": "语义：“健忘”指记性差，与完成任务所需的本领无关。"}, "sentence_index": 0, "correct_answer": "有能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很有能力，可以自己走路。", "explanation": "这里不能用“有能力”：石头不会自己走路，说它“有能力”不合常理。"}, {"text": "这盆花很有能力，每天自己浇水。", "explanation": "这里不能用“有能力”：花不会自己浇水，说它“有能力”不合常理。"}, {"text": "这台洗衣机很有能力，每天自己做饭。", "explanation": "这里不能用“有能力”：洗衣机不会做饭，说它“有能力”不合常理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有能力", "is_correct": true, "explanation": "正确答案。“有能力”表示具备治疗重病的本领，符合句意。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”形容环境安静，不能用来说医院的治疗本领。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容天气或地面，不能用来形容医院做事的能力。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，与治疗重病无关。"}], "explanations": {"有能力": "正确答案。“有能力”表示具备治疗重病的本领，符合句意。", "寂静": "搭配：“寂静”形容环境安静，不能用来说医院的治疗本领。", "潮湿": "搭配：“潮湿”形容天气或地面，不能用来形容医院做事的能力。", "清脆": "语义：“清脆”形容声音，与治疗重病无关。"}, "sentence_index": 6, "correct_answer": "有能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆自行车有能力陪你去公园。", "explanation": "这里不能用“有能力”：自行车不会陪人，说它“有能力”不合常理。"}, {"text": "我今天很有能力，一口气吃了三大碗饭。", "explanation": "这里应该用〈有胃口〉。“有能力”指做事的本领，形容胃口好要用“有胃口”。"}, {"text": "这本书很有能力，内容非常好。", "explanation": "“有能力”用于能做事的人，不能用来形容书的内容，形容书要用〈有意思〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有能力的帮我修电脑。", "corrected_sentence": "他有能力帮我修电脑。", "error_description": "“有能力”后加了“的”：“有能力的”变成名词性短语，后面不能直接接动词“帮我修电脑”，应说“他有能力帮我修电脑”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子有能力着独立完成作业。", "corrected_sentence": "这个孩子有能力独立完成作业。", "error_description": "体标误用：“有能力”后面直接接动词，不能加“着”。应说“有能力独立完成作业”，去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
