INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94399, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "极其是特别特别，比很还要多。", "primary_collocate": null, "pronunciation": "jí qí", "ipa": "tɕi˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "昨天的考试极其难，很多人没做完。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他极其喜欢这只小狗，天天带它出去玩。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间极其安静，能听见钟的声音。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天这里极其炎热，没有人愿意出门。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的饭极其香甜，我吃了三碗。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们极其幸运，下雨前就到家了。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人极其善良，常常帮助邻居。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上极其拥挤，我们迟到了。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书极其精彩，我一口气看完了。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得极其快，一下子就看不见了。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "极其：比“很”程度更高，表示特别特别，可修饰形容词和心理动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9550a99-05ab-43a0-8580-e05f022f057f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极其", "is_correct": true, "explanation": "极其 jíqí：程度副词，比“很”程度更高，表示特别特别。"}, {"text": "机器", "is_correct": false, "explanation": "机器 jīqì 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qì 第四声，对 jí 第二声、qí 第二声），意思是机器。"}, {"text": "记起", "is_correct": false, "explanation": "记起 jìqǐ 与 极其 jíqí 两个音节的声调都不同（jì 第四声、qǐ 第三声），意思是想起来。"}, {"text": "激起", "is_correct": false, "explanation": "激起 jīqǐ 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qǐ 第三声），意思是引起、激发。"}], "explanations": {"极其": "极其 jíqí：程度副词，比“很”程度更高，表示特别特别。", "机器": "机器 jīqì 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qì 第四声，对 jí 第二声、qí 第二声），意思是机器。", "记起": "记起 jìqǐ 与 极其 jíqí 两个音节的声调都不同（jì 第四声、qǐ 第三声），意思是想起来。", "激起": "激起 jīqǐ 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qǐ 第三声），意思是引起、激发。"}, "sentence_index": null, "correct_answer": "极其"}, "level_3": {"options": [{"text": "极其", "is_correct": true, "explanation": "极其：程度副词，比“很”程度更高，修饰形容词“难”。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示即刻，不修饰“难”这类表示性质的形容词。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一贯如此，与“昨天”这个具体时间相矛盾。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示时间刚发生，与“难”的程度无关。"}], "explanations": {"极其": "极其：程度副词，比“很”程度更高，修饰形容词“难”。", "马上": "搭配：“马上”表示即刻，不修饰“难”这类表示性质的形容词。", "从来": "语义：“从来”指一贯如此，与“昨天”这个具体时间相矛盾。", "刚": "语义：“刚”表示时间刚发生，与“难”的程度无关。"}, "sentence_index": 0, "correct_answer": "极其"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地是极其公共的，大家都能来散步。", "explanation": "这里应该用〈完全〉。“公共”不能分程度，不能被“极其”修饰；表示完全向大家开放要用“完全”。"}, {"text": "他极其单独住在山上，很少和人来往。", "explanation": "这里应该用〈独自〉。“单独”不能被“极其”表示程度高的副词修饰；“一个人住”应说“独自住”。"}, {"text": "这是极其唯一的机会，我们一定要抓住。", "explanation": "这里不能用〈最〉式的程度副词修饰“唯一”。“唯一”表示只有一个，不分程度，应直接说“这是唯一的机会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94399, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极其", "is_correct": true, "explanation": "极其：程度副词，表示程度很高，修饰形容词“善良”。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示即时发生的动作，不修饰“善良”这类性质形容词。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示很少发生，与“常常帮助邻居”相矛盾。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定“善良”，与“常常帮助邻居”的描述相矛盾。"}], "explanations": {"极其": "极其：程度副词，表示程度很高，修饰形容词“善良”。", "立刻": "搭配：“立刻”表示即时发生的动作，不修饰“善良”这类性质形容词。", "偶尔": "语义：“偶尔”表示很少发生，与“常常帮助邻居”相矛盾。", "不": "语义：“不”否定“善良”，与“常常帮助邻居”的描述相矛盾。"}, "sentence_index": 6, "correct_answer": "极其"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他极其已婚，孩子都上小学了。", "explanation": "这里应该用〈已经〉。“已婚”表示结婚与否的状态，不能分程度，不能被“极其”修饰；表示状态已完成要用“已经”。"}, {"text": "这批零件极其合格，大家都很放心。", "explanation": "这里应该用〈完全〉。“合格”只说达标与否，不能分程度；表示完全达标要用“完全”。"}, {"text": "这次比赛是极其国际的，很多选手都来参加。", "explanation": "这里应该用〈大型〉。“国际”指涉及多个国家，是性质归类，不能分程度；要强调规模大要用“大型”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次登山的路很极其陡，我们走得很慢。", "corrected_sentence": "这次登山的路极其陡，我们走得很慢。", "error_description": "错误形式：“很极其陡”；正确形式：“极其陡”。“极其”本身已表示程度很高，不能再与“很”叠用修饰同一形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他唱歌唱极其好听，大家都夸他。", "corrected_sentence": "他唱歌唱得极其好听，大家都夸他。", "error_description": "错误形式：“唱极其好听”；正确形式：“唱得极其好听”。动作之后带程度补语时，要用“得”连接，结构是“动词+得+极其好听”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
