INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94400, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度很高，非常。", "primary_collocate": null, "pronunciation": "jí qí", "ipa": "tɕi˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这个问题极其重要，大家要认真想。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的声音极其微弱，我没听清。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的天气极其寒冷，要多穿衣服。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事极其危险，你不要去做。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对工作极其认真，从不迟到。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的服务极其周到。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天极其严肃，一句话也不说。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的水极其珍贵，人们都很节省。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路极其难走，我们走了三个小时。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩极其优秀，大家都很佩服。", "target_word": "极其", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "极其：程度副词，表示程度很高，相当于非常，后面多接形容词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9550a99-05ab-43a0-8580-e05f022f057f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极其", "is_correct": true, "explanation": "极其 jíqí：程度副词，表示程度很高，相当于“非常”。"}, {"text": "机器", "is_correct": false, "explanation": "机器 jīqì 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qì 第四声，对 jí 第二声、qí 第二声），意思是机器。"}, {"text": "记起", "is_correct": false, "explanation": "记起 jìqǐ 与 极其 jíqí 两个音节的声调都不同（jì 第四声、qǐ 第三声），意思是想起来。"}, {"text": "激起", "is_correct": false, "explanation": "激起 jīqǐ 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qǐ 第三声），意思是引起、激发。"}], "explanations": {"极其": "极其 jíqí：程度副词，表示程度很高，相当于“非常”。", "机器": "机器 jīqì 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qì 第四声，对 jí 第二声、qí 第二声），意思是机器。", "记起": "记起 jìqǐ 与 极其 jíqí 两个音节的声调都不同（jì 第四声、qǐ 第三声），意思是想起来。", "激起": "激起 jīqǐ 与 极其 jíqí 两个音节的声调都不同（jī 第一声、qǐ 第三声），意思是引起、激发。"}, "sentence_index": null, "correct_answer": "极其"}, "level_3": {"options": [{"text": "极其", "is_correct": true, "explanation": "极其：程度副词，表示程度很高，修饰形容词“重要”。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定“重要”，与后句“大家要认真想”的语气相矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示即刻，不修饰“重要”这类表示性质的形容词。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示时间刚发生，与“重要”的程度无关。"}], "explanations": {"极其": "极其：程度副词，表示程度很高，修饰形容词“重要”。", "不": "语义：“不”否定“重要”，与后句“大家要认真想”的语气相矛盾。", "马上": "搭配：“马上”表示即刻，不修饰“重要”这类表示性质的形容词。", "刚": "语义：“刚”表示时间刚发生，与“重要”的程度无关。"}, "sentence_index": 0, "correct_answer": "极其"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批产品极其合格，大家都很放心。", "explanation": "这里应该用〈完全〉。“合格”只说达标与否，不能分程度，“极其”只修饰可以分程度的形容词；表示完全达标要用“完全”。"}, {"text": "他的成绩极其及格，大家都没想到。", "explanation": "这里应该用〈刚好〉。“及格”表示分数刚过线，不能分程度，不能被“极其”修饰；应说“刚好及格”。"}, {"text": "这是极其唯一的办法，大家都同意了。", "explanation": "这里不能用〈最〉式的程度副词修饰“唯一”。“唯一”表示只有一个，不分程度，应直接说“这是唯一的办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极其", "is_correct": true, "explanation": "极其：程度副词，表示程度很高，修饰形容词“严肃”。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一贯如此，与“今天”这个限定的时间相矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的状态，与“今天”相矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示即时发生的动作，不修饰“严肃”这类状态形容词。"}], "explanations": {"极其": "极其：程度副词，表示程度很高，修饰形容词“严肃”。", "从来": "语义：“从来”指一贯如此，与“今天”这个限定的时间相矛盾。", "曾经": "语义：“曾经”指过去的状态，与“今天”相矛盾。", "立刻": "搭配：“立刻”表示即时发生的动作，不修饰“严肃”这类状态形容词。"}, "sentence_index": 6, "correct_answer": "极其"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个极其公共的场所，大家都要遵守规则。", "explanation": "这里应该用〈完全〉。“公共”指属于大家，是性质归类，不能分程度，不能被“极其”修饰；表示完全向大家开放要用“完全”。"}, {"text": "他极其单独住在山上，很少和人来往。", "explanation": "这里应该用〈独自〉。“单独”是性质或方式的归类，不能被“极其”表示程度高的副词修饰；“一个人住”应说“独自住”。"}, {"text": "这是极其国际的比赛，很多国家的选手都来了。", "explanation": "这里应该用〈大型〉。“国际”指涉及多个国家，是性质归类，不能分程度；要强调规模大要用“大型”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛的难度极其的大，选手们都很紧张。", "corrected_sentence": "这次比赛的难度极其大，选手们都很紧张。", "error_description": "错误形式：“极其的大”；正确形式：“极其大”。“极其”是程度副词，直接修饰形容词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小朋友吃饭吃极其快，一会儿就吃完了。", "corrected_sentence": "这个小朋友吃饭吃得极其快，一会儿就吃完了。", "error_description": "错误形式：“吃极其快”；正确形式：“吃得极其快”。动作之后带程度补语时，要用“得”连接，结构是“动词+得+极其快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
