INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94401, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "构造是一个东西里面各部分是怎么放在一起的。", "primary_collocate": null, "pronunciation": "gòu zào", "ipa": "kou˥˩ tsau˥˩", "syllable_count": 2, "sentences": [{"text": "你知道手机里面的构造吗？", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的构造很合理。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电脑拆开，研究它的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟的身体构造很适合飞行。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图画说明眼睛的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的构造很结实。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子的构造不复杂，我自己能修。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛的构造像一台小相机。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要修这台机器，先得懂它的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地铁站的构造很复杂，容易迷路。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "構造", "label": "繁体"}, {"form": "构造图", "label": "复合"}], "register": "书面", "sense_fingerprint": "一个东西里面各部分怎么放在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94401, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只指人或动物的体形，手机没有身材。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，不能用来说手机里面的东西。"}, {"text": "构造", "is_correct": true, "explanation": "正确：“构造”指东西里面各部分怎样放在一起，与“手机里面的……”搭配。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的性情特点，不能用于手机。"}], "explanations": {"身材": "体貌：“身材”只指人或动物的体形，手机没有身材。", "味道": "语义：“味道”指气味或滋味，不能用来说手机里面的东西。", "构造": "正确：“构造”指东西里面各部分怎样放在一起，与“手机里面的……”搭配。", "性格": "语义：“性格”指人的性情特点，不能用于手机。"}, "sentence_index": 0, "correct_answer": "构造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的构造很鲜艳，很多人都喜欢。", "explanation": "这里应该用〈颜色〉。“构造”指各部分怎样组合，说颜色鲜艳要用“颜色”。"}, {"text": "妹妹的构造很温和，大家都喜欢她。", "explanation": "这里应该用〈脾气〉。“构造”指事物的组成，说人的性情要用“脾气”。"}, {"text": "这个房间的构造很热闹，每天都有很多人来。", "explanation": "这里应该用〈气氛〉。“构造”指各部分怎样组合，说房间里的热闹程度要用“气氛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是东西的组成，不能说椅子的时间不复杂。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人或动物的性情，椅子没有脾气。"}, {"text": "构造", "is_correct": true, "explanation": "正确：“构造”指东西里面各部分怎样放在一起，与“这把椅子的……不复杂”搭配。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”指人的情绪，不能用来说椅子。"}], "explanations": {"时间": "语义：“时间”不是东西的组成，不能说椅子的时间不复杂。", "脾气": "语义：“脾气”指人或动物的性情，椅子没有脾气。", "构造": "正确：“构造”指东西里面各部分怎样放在一起，与“这把椅子的……不复杂”搭配。", "感情": "搭配：“感情”指人的情绪，不能用来说椅子。"}, "sentence_index": 6, "correct_answer": "构造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地铁站的构造很香，里面有很多面包店。", "explanation": "这里应该用〈气味〉。“构造”指各部分怎样组合，说闻起来怎么样要用“气味”。"}, {"text": "这个地铁站的构造很友好，工作人员总是笑着帮忙。", "explanation": "这里应该用〈服务〉。“构造”指各部分怎样组合，说人的态度要用“服务”。"}, {"text": "这个地铁站的构造很便宜，坐一次只要两块钱。", "explanation": "这里应该用〈票价〉。“构造”指各部分怎样组合，说价钱要用“票价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种台灯的的构造很巧妙。", "corrected_sentence": "这种台灯的构造很巧妙。", "error_description": "多余的“的”：定语“台灯”后只用一个“的”，应说“台灯的构造”，不能说“台灯的的构造”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个闹钟有一条很特别的构造。", "corrected_sentence": "这个闹钟有一种很特别的构造。", "error_description": "量词错误：“构造”应该用“种”，不能用“条”；“条”用于细长的东西，不能修饰“构造”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
