INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的组成部分及其相互关系。", "primary_collocate": null, "pronunciation": "gòu zào", "ipa": "kou˥˩ tsau˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器的构造很简单。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了房子的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的耳朵构造很复杂。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看这个手表的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种汽车的内部构造和别的不同。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里详细讲解了花的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生很了解人体的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的构造很特别。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学了句子的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具的构造让孩子很感兴趣。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "構造", "label": "繁体"}, {"form": "构造图", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物的组成部分及其相互关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，不能用来说机器的组成简单不简单。"}, {"text": "构造", "is_correct": true, "explanation": "正确：“构造”指事物各部分的组成及相互关系，与“机器的……很简单”搭配。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只指人或动物的体形，不用来说机器。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人或动物的性情，机器没有脾气。"}], "explanations": {"味道": "语义：“味道”指气味或滋味，不能用来说机器的组成简单不简单。", "构造": "正确：“构造”指事物各部分的组成及相互关系，与“机器的……很简单”搭配。", "身材": "体貌：“身材”只指人或动物的体形，不用来说机器。", "脾气": "语义：“脾气”指人或动物的性情，机器没有脾气。"}, "sentence_index": 0, "correct_answer": "构造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个蛋糕的构造很香甜，我吃了好几块。", "explanation": "这里应该用〈味道〉。“构造”指事物的组成和相互关系，说食物的滋味要用“味道”。"}, {"text": "他的构造很善良，大家都喜欢他。", "explanation": "这里应该用〈性格〉。“构造”指事物的组成，说人的为人和品质要用“性格”。"}, {"text": "这首歌的构造很响亮，邻居都听见了。", "explanation": "这里应该用〈音量〉。“构造”指各部分怎样组合，说声音的大小要用“音量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "搭配：“感情”指人的情绪，不能用来说人体的组成。"}, {"text": "作风", "is_correct": false, "explanation": "语义：“作风”指人的做事方式，与人体的组成无关。"}, {"text": "构造", "is_correct": true, "explanation": "正确：“构造”指人体各部分的组成及相互关系，与“医生很了解人体的……”搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是人体的组成或结构，句意不通。"}], "explanations": {"感情": "搭配：“感情”指人的情绪，不能用来说人体的组成。", "作风": "语义：“作风”指人的做事方式，与人体的组成无关。", "构造": "正确：“构造”指人体各部分的组成及相互关系，与“医生很了解人体的……”搭配。", "时间": "语义：“时间”不是人体的组成或结构，句意不通。"}, "sentence_index": 6, "correct_answer": "构造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个玩具的构造很便宜，只要十块钱。", "explanation": "这里应该用〈价格〉。“构造”指组成部分及其关系，说价钱要用“价格”。"}, {"text": "这个玩具的构造很鲜艳，孩子一眼就看到了。", "explanation": "这里应该用〈颜色〉。“构造”指组成部分及其关系，说颜色鲜艳要用“颜色”。"}, {"text": "这个玩具的构造很响亮，整个房间都听得见。", "explanation": "这里应该用〈声音〉。“构造”指组成部分及其关系，说声音大要用“声音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个积木的的构造很简单。", "corrected_sentence": "这个积木的构造很简单。", "error_description": "多余的“的”：定语“积木”后只用一个“的”，应说“积木的构造”，不能说“积木的的构造”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥有一只很特别的构造。", "corrected_sentence": "这座桥有一种很特别的构造。", "error_description": "量词错误：“构造”是抽象名词，应该用“种”，不能用“只”；“只”用于动物或单个的东西，不能修饰“构造”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
