INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94403, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "死者是已经不在了的人。", "primary_collocate": null, "pronunciation": "sǐ zhě", "ipa": "sɨ˨˩ ʈʂɤ˨˩", "syllable_count": 2, "sentences": [{"text": "死者的朋友都来参加葬礼。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上登出了死者的名字。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们给死者送了很多白花。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死者生前是一位老师。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方还没有找到死者的家人。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震中死者很多，大家都很难过。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每年都会去墓地悼念死者。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纪念碑是为死者建的。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死者已经不能再说话了。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院通知了死者的亲人。", "target_word": "死者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "死者家属", "label": "复合"}], "register": "书面", "sense_fingerprint": "已经不在了的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e17f9927-b1fd-4582-ab98-2acb8fc73a68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "死者", "is_correct": true, "explanation": "正确：“死者”指已经不在的人，朋友来参加葬礼是对他而言的。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空没有朋友，句子不成立。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不是人，不会有朋友来参加葬礼。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“朋友”一般指人，“教室的朋友”不能用于葬礼语境。"}], "explanations": {"死者": "正确：“死者”指已经不在的人，朋友来参加葬礼是对他而言的。", "天空": "语义：天空没有朋友，句子不成立。", "白菜": "语义：白菜不是人，不会有朋友来参加葬礼。", "教室": "搭配：“朋友”一般指人，“教室的朋友”不能用于葬礼语境。"}, "sentence_index": 0, "correct_answer": "死者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居是一位死者，每天早上都在公园里打太极。", "explanation": "“死者”指已经不在的人，这里说邻居每天打太极，活人不能用“死者”称呼。"}, {"text": "我的女儿是一个死者，她正在学校里认真地上课。", "explanation": "“死者”指已经不在的人，女儿正在上课说明她还活着，不能用“死者”称呼。"}, {"text": "他的死者很精彩。", "explanation": "这里应该用〈演技〉。〈死者〉指死去的人，不能用来评价表演是否精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死者", "is_correct": true, "explanation": "正确：“死者”是已经不在的人，是墓地悼念的对象。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是悼念的对象，“悼念课本”不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“悼念汽车”不符合语境。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：悼念一般针对人，“悼念雨伞”不自然。"}], "explanations": {"死者": "正确：“死者”是已经不在的人，是墓地悼念的对象。", "课本": "语义：课本不是悼念的对象，“悼念课本”不成立。", "汽车": "语义：“悼念汽车”不符合语境。", "雨伞": "搭配：悼念一般针对人，“悼念雨伞”不自然。"}, "sentence_index": 6, "correct_answer": "死者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法医正在查找死者的原因。", "explanation": "这里应该用〈死亡〉。〈死者〉指人，查找的是死去的原因，要说“死亡的原因”。"}, {"text": "他临终前说出了死者。", "explanation": "这里应该用〈遗愿〉。〈死者〉指死去的人，临终时说出的是心愿，要用〈遗愿〉。"}, {"text": "院子里开满了死者。", "explanation": "这里应该用〈鲜花〉。〈死者〉指人，不能用“开满”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条死者家属需要签署这份文件。", "corrected_sentence": "这位死者家属需要签署这份文件。", "error_description": "量词错误。“死者家属”指人，量词应用“位”；“条”用于细长的东西，这里应改为“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救援队在废墟下找到了一辆死者。", "corrected_sentence": "救援队在废墟下找到了一位死者。", "error_description": "“辆”用于车辆，“死者”指人，这里应该用〈位〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
