INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "混是把几样东西放在一起搅一搅。", "primary_collocate": null, "pronunciation": "hùn", "ipa": "xwən˥˩", "syllable_count": 1, "sentences": [{"text": "把水和糖混在一起，搅一搅。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把红色和黄色混了一下，变成了橙色。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面粉和水要先混好，再放盐。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油和水混不到一起。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两种米混一混。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把牛奶和鸡蛋混着放进碗里。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把颜料混一混，再画在纸上。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几种茶叶混在一起泡。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把沙子和水混在一起，搅成了泥。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把牛奶和咖啡混在一起，慢慢搅匀。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混合", "label": "复合"}, {"form": "混一混", "label": "重叠"}], "register": "口语", "sense_fingerprint": "混：动词，把几种东西放在一起搅拌，使它们合在一起，如把水和糖混在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9550a99-05ab-43a0-8580-e05f022f057f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "混", "is_correct": true, "explanation": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。"}, {"text": "恨", "is_correct": false, "explanation": "恨 hèn 与 混 hùn 只有韵母不同（en 与 un），声调都是第四声，意思是怨恨。"}, {"text": "困", "is_correct": false, "explanation": "困 kùn 与 混 hùn 只有声母不同（k 与 h），声调都是第四声，意思是疲倦、被困住。"}, {"text": "棍", "is_correct": false, "explanation": "棍 gùn 与 混 hùn 只有声母不同（g 与 h），声调都是第四声，意思是棍子。"}], "explanations": {"混": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。", "恨": "恨 hèn 与 混 hùn 只有韵母不同（en 与 un），声调都是第四声，意思是怨恨。", "困": "困 kùn 与 混 hùn 只有声母不同（k 与 h），声调都是第四声，意思是疲倦、被困住。", "棍": "棍 gùn 与 混 hùn 只有声母不同（g 与 h），声调都是第四声，意思是棍子。"}, "sentence_index": null, "correct_answer": "混"}, "level_3": {"options": [{"text": "混", "is_correct": true, "explanation": "混：动词，把几样东西放在一起搅拌，使它们合在一起。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”是分开，与后句“在一起”相矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”只用于清洗，不能说把水和糖“洗在一起”。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指切割，不能说把水和糖“切在一起”。"}], "explanations": {"混": "混：动词，把几样东西放在一起搅拌，使它们合在一起。", "分": "语义：“分”是分开，与后句“在一起”相矛盾。", "洗": "搭配：“洗”只用于清洗，不能说把水和糖“洗在一起”。", "切": "搭配：“切”指切割，不能说把水和糖“切在一起”。"}, "sentence_index": 0, "correct_answer": "混"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把书按大小混在一起，整整齐齐的。", "explanation": "这里应该用〈放〉。“混”指搀合在一起、分不清，与“按大小”“整整齐齐”的意思矛盾；把东西按次序放在一起要用“放”。"}, {"text": "把碎片混在一起，就成了一幅完整的画。", "explanation": "这里应该用〈拼〉。“混”不表示把碎片按位置组合，要把碎片组成完整的画应该用“拼”。"}, {"text": "两家公司混在一起，成了一家大公司。", "explanation": "这里应该用〈合〉。“混”指搀杂、不分彼此，两家公司合并成一家应该用“合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "混", "is_correct": true, "explanation": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。"}, {"text": "魂", "is_correct": false, "explanation": "魂 hún 与 混 hùn 只有声调不同（第二声与第四声），意思是灵魂。"}, {"text": "婚", "is_correct": false, "explanation": "婚 hūn 与 混 hùn 只有声调不同（第一声与第四声），意思是婚姻。"}, {"text": "滚", "is_correct": false, "explanation": "滚 gǔn 与 混 hùn 声母不同（g 与 h），声调也不同（第三声与第四声），意思是滚动。"}], "explanations": {"混": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。", "魂": "魂 hún 与 混 hùn 只有声调不同（第二声与第四声），意思是灵魂。", "婚": "婚 hūn 与 混 hùn 只有声调不同（第一声与第四声），意思是婚姻。", "滚": "滚 gǔn 与 混 hùn 声母不同（g 与 h），声调也不同（第三声与第四声），意思是滚动。"}, "sentence_index": null, "correct_answer": "混"}, "level_3": {"options": [{"text": "混", "is_correct": true, "explanation": "混：动词，把几种颜料搅在一起，使它们合在一起。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”是剪断、剪开，不能用于处理颜料。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是擦拭，与调和颜料的意思不同。"}, {"text": "削", "is_correct": false, "explanation": "搭配：“削”指削去表层，颜料不能被削。"}], "explanations": {"混": "混：动词，把几种颜料搅在一起，使它们合在一起。", "剪": "搭配：“剪”是剪断、剪开，不能用于处理颜料。", "擦": "语义：“擦”是擦拭，与调和颜料的意思不同。", "削": "搭配：“削”指削去表层，颜料不能被削。"}, "sentence_index": 6, "correct_answer": "混"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "把苹果和香蕉混在一起，一个个摆成了整齐的队伍。", "explanation": "这里应该用〈排〉。“混”指搀合在一起、分不清，与“一个个摆成整齐的队伍”矛盾；按次序放置要用“排”。"}, {"text": "两块布混在一起，就成了一件衣服。", "explanation": "这里应该用〈缝〉。“混”指搀合，不表示把两块东西连接成整体；要把布连在一起应该用“缝”。"}, {"text": "把红豆和绿豆混开，各自装在两个碗里。", "explanation": "这里应该用〈分〉。“混”是搀合，与“混开”“各自装”的分离意思矛盾；把东西分开要用“分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把面粉和水混很匀，再放一点盐。", "corrected_sentence": "把面粉和水混得很匀，再放一点盐。", "error_description": "错误形式：“混很匀”；正确形式：“混得很匀”。动词后接程度补语“很匀”时，要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把红色和白色混进一起，就变成了粉色。", "corrected_sentence": "把红色和白色混在一起，就变成了粉色。", "error_description": "错误形式：“混进一起”；正确形式：“混在一起”。“进”表示进入某处，不能与“一起”搭配，表示东西搀合在某处要用“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
