INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在外国学习。", "primary_collocate": null, "pronunciation": "liú xué", "ipa": "liou˧˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他在法国留学，住在学校旁边。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友正在加拿大留学。", "target_word": "留学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "留学期间，她认识了很多新朋友。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他留学的时候，每个月都给妈妈打电话。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹在英国留学，那里常常下雨。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在国外留学，不能回家过春节。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "留学的时候，我学会了做中国菜。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在美国留学，学的是经济。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边留学，一边在饭馆打工。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在国外留学，他学会了照顾自己。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "留學", "label": "繁体"}, {"form": "留学生", "label": "复合"}], "register": "中性", "sense_fingerprint": "人在外国学习、生活的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主语是天气，不能说“他在法国下雨”。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”必须带宾语，“他在法国购买”后面缺少宾语。"}, {"text": "留学", "is_correct": true, "explanation": "正确：“留学”指在外国学习生活，与“他在法国……，住在学校旁边”搭配。"}, {"text": "打雷", "is_correct": false, "explanation": "语义：“打雷”是天气现象，不能说人在法国打雷。"}], "explanations": {"下雨": "语义：“下雨”的主语是天气，不能说“他在法国下雨”。", "购买": "配价：“购买”必须带宾语，“他在法国购买”后面缺少宾语。", "留学": "正确：“留学”指在外国学习生活，与“他在法国……，住在学校旁边”搭配。", "打雷": "语义：“打雷”是天气现象，不能说人在法国打雷。"}, "sentence_index": 0, "correct_answer": "留学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去山区留学，每天给学生上课。", "explanation": "这里应该用〈支教〉。“留学”指在外国学习生活，在国内山区教书要用〈支教〉。"}, {"text": "他去农村留学，帮农民种地。", "explanation": "这里应该用〈下乡〉。“留学”指在外国学习生活，去国内农村劳动要用〈下乡〉。"}, {"text": "他去北京留学，参加了三个会议。", "explanation": "这里应该用〈出差〉。“留学”指在外国学习生活，去国内开会要用〈出差〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行书刊，与做中国菜无关，句意不通。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指用打印机印出文件，与做中国菜无关，句意不通。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”必须带宾语，“赠送的时候”后面缺少宾语。"}, {"text": "留学", "is_correct": true, "explanation": "正确：“留学”指在外国学习生活，与“……的时候，我学会了做中国菜”搭配。"}], "explanations": {"出版": "语义：“出版”指印刷发行书刊，与做中国菜无关，句意不通。", "打印": "语义：“打印”指用打印机印出文件，与做中国菜无关，句意不通。", "赠送": "配价：“赠送”必须带宾语，“赠送的时候”后面缺少宾语。", "留学": "正确：“留学”指在外国学习生活，与“……的时候，我学会了做中国菜”搭配。"}, "sentence_index": 6, "correct_answer": "留学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在北京的饭馆留学，每天要洗很多碗。", "explanation": "这里应该用〈打工〉。“留学”指在外国学习生活，在国内饭馆做工要用〈打工〉。"}, {"text": "他在国内的大学留学，学生都很喜欢他。", "explanation": "这里应该用〈教书〉。“留学”指在外国学习生活，在国内大学教书要用〈教书〉。"}, {"text": "他在家附近的医院留学，每天给病人看病。", "explanation": "这里应该用〈工作〉。“留学”指在外国学习生活，在家附近的医院给病人看病要用〈工作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟在澳大利亚被留学，学习很努力。", "corrected_sentence": "我弟弟在澳大利亚留学，学习很努力。", "error_description": "“留学”是不及物动词，不能用于“被”字句，应去掉“被”，说“在澳大利亚留学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他法国留学两年。", "corrected_sentence": "他在法国留学两年。", "error_description": "漏字错误：表示地点的“在法国”前缺少介词“在”，应说“在法国留学”，不能说“法国留学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
