INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94409, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "疫苗是打进身体里的药，让人不容易生病。", "primary_collocate": null, "pronunciation": "yì miáo", "ipa": "i˥˩ miɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "孩子今天要去医院打疫苗。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打了疫苗，就不容易生病。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种疫苗很安全。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手臂打完疫苗有点疼。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来以前，老人要打流感疫苗。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支疫苗可以让小孩少生病。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带弟弟去打疫苗了。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疫苗能帮身体提前防范病毒。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士提醒我，打疫苗以后要休息。", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今年打过流感疫苗吗？", "target_word": "疫苗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一支疫苗", "label": "量词"}, {"form": "流感疫苗", "label": "复合"}], "register": "中性", "sense_fingerprint": "打进身体、预防生病的药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e17f9927-b1fd-4582-ab98-2acb8fc73a68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体温计", "is_correct": false, "explanation": "搭配：“打”后面接的是针剂，不能接“体温计”。"}, {"text": "护士", "is_correct": false, "explanation": "语义：“护士”是人，不是可以被打进身体的东西。"}, {"text": "疫苗", "is_correct": true, "explanation": "正确。“疫苗”是打进身体、预防生病的药，与“打”搭配。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：应说“做作业”，不说“打作业”。"}], "explanations": {"体温计": "搭配：“打”后面接的是针剂，不能接“体温计”。", "护士": "语义：“护士”是人，不是可以被打进身体的东西。", "疫苗": "正确。“疫苗”是打进身体、预防生病的药，与“打”搭配。", "作业": "搭配：应说“做作业”，不说“打作业”。"}, "sentence_index": 0, "correct_answer": "疫苗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我生病以后，身体里产生了很多疫苗。", "explanation": "这里应该用〈抗体〉。疫苗是从外面打进身体的药，身体自己产生的是抗体。"}, {"text": "感冒了，医生给我开了一些疫苗。", "explanation": "这里应该用〈药〉。疫苗用于预防，不能用来治疗已经得了的感冒。"}, {"text": "医生给我的伤口上涂了疫苗。", "explanation": "这里应该用〈药膏〉。“涂”用于药膏，疫苗是打进身体里的，不能涂在伤口上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”是穿在脚上的鞋，不是可以“打”的东西。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“打”不与“书包”搭配，应说“背书包”。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能作“打”的对象。"}, {"text": "疫苗", "is_correct": true, "explanation": "正确。“疫苗”是打进身体、预防生病的药，与“打”搭配。"}], "explanations": {"拖鞋": "语义：“拖鞋”是穿在脚上的鞋，不是可以“打”的东西。", "书包": "搭配：“打”不与“书包”搭配，应说“背书包”。", "地铁": "语义：“地铁”是交通工具，不能作“打”的对象。", "疫苗": "正确。“疫苗”是打进身体、预防生病的药，与“打”搭配。"}, "sentence_index": 6, "correct_answer": "疫苗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用疫苗量了一下体温。", "explanation": "这里应该用〈体温计〉。疫苗是注射用的药品，不能用来测量体温。"}, {"text": "明天他要去做疫苗。", "explanation": "这里应该用〈手术〉。疫苗要“打”或“接种”，不说“做”。"}, {"text": "医生在我的胳膊上贴了疫苗。", "explanation": "这里应该用〈膏药〉。“贴”用于膏药这类贴在皮肤上的东西，疫苗是打进身体里的，不能贴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天打了一条疫苗。", "corrected_sentence": "我昨天打了一支疫苗。", "error_description": "量词错误：“疫苗”的量词应为“支”，“条”用于细长的东西，不能用于疫苗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟昨天打了一颗疫苗。", "corrected_sentence": "弟弟昨天打了一支疫苗。", "error_description": "量词错误：“疫苗”的量词应为“支”，“颗”用于小而圆的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94412, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平凡", "is_correct": true, "explanation": "正确：“平凡”指普通、不奇特，与“神奇”意思相反。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”指没有声音或动静，与“神奇”不构成反义。"}, {"text": "沉重", "is_correct": false, "explanation": "无反义关系：“沉重”指重量大或心情压抑，与“神奇”不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "无反义关系：“柔软”指质地软，与“神奇”不构成反义。"}], "correct_answer": "平凡", "explanations": {"平凡": "正确：“平凡”指普通、不奇特，与“神奇”意思相反。", "安静": "无反义关系：“安静”指没有声音或动静，与“神奇”不构成反义。", "沉重": "无反义关系：“沉重”指重量大或心情压抑，与“神奇”不构成反义。", "柔软": "无反义关系：“柔软”指质地软，与“神奇”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94412, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平凡", "is_correct": true, "explanation": "正确：“平凡”指普通、不奇特，与“神奇”意思相反。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”指光线足，与“神奇”不构成反义。"}, {"text": "迟钝", "is_correct": false, "explanation": "无反义关系：“迟钝”指反应慢，与“神奇”不构成反义。"}, {"text": "干燥", "is_correct": false, "explanation": "无反义关系：“干燥”指缺少水分，与“神奇”不构成反义。"}], "correct_answer": "平凡", "explanations": {"平凡": "正确：“平凡”指普通、不奇特，与“神奇”意思相反。", "明亮": "无反义关系：“明亮”指光线足，与“神奇”不构成反义。", "迟钝": "无反义关系：“迟钝”指反应慢，与“神奇”不构成反义。", "干燥": "无反义关系：“干燥”指缺少水分，与“神奇”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94412, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "奇特而神妙的，超出一般想象。", "primary_collocate": null, "pronunciation": "shén qí", "ipa": "ʂən˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这个山洞里的景色非常神奇。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一个神奇的故事。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔术师的表演太神奇了。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草药有神奇的作用。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚的星空看起来很神奇。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大自然真神奇，花会跟着太阳转。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们被这个神奇的盒子吸引了。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里有一个神奇的湖，水是红色的。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事听起来很神奇，但是真的。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一双神奇的手，能让花重新开。", "target_word": "神奇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神奇地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "奇特神妙，超出想象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e17f9927-b1fd-4582-ab98-2acb8fc73a68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神奇", "is_correct": true, "explanation": "正确：“神奇”形容景色奇妙、超出想象，符合语境。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：景色是视觉对象，不能用“沉重”来形容。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不用来形容山洞景色。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容声音，不能说景色吵闹。"}], "explanations": {"神奇": "正确：“神奇”形容景色奇妙、超出想象，符合语境。", "沉重": "语义：景色是视觉对象，不能用“沉重”来形容。", "柔软": "语义：“柔软”形容质地，不用来形容山洞景色。", "吵闹": "搭配：“吵闹”形容声音，不能说景色吵闹。"}, "sentence_index": 0, "correct_answer": "神奇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看到这个结果，我很神奇。", "explanation": "这里应该用〈惊奇〉。〈神奇〉修饰事物，说人吃惊时要用〈惊奇〉。"}, {"text": "他穿的衣服很神奇，颜色乱七八糟。", "explanation": "这里应该用〈难看〉。〈神奇〉指奇妙、令人赞叹，不能用来形容杂乱的颜色。"}, {"text": "这次考试的成绩很神奇，我很失望。", "explanation": "〈神奇〉指奇妙、令人赞叹，用来形容让人失望的成绩不合适，应换成〈糟糕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神奇", "is_correct": true, "explanation": "正确：“神奇”形容盒子奇妙，能吸引孩子，符合语境。"}, {"text": "乏味", "is_correct": false, "explanation": "语义：“乏味”与“吸引”矛盾，孩子不会被乏味的盒子吸引。"}, {"text": "衰老", "is_correct": false, "explanation": "搭配：盒子不会衰老，“衰老”只用于人或生物。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”是坏的状态，与“吸引孩子”的语境相反。"}], "explanations": {"神奇": "正确：“神奇”形容盒子奇妙，能吸引孩子，符合语境。", "乏味": "语义：“乏味”与“吸引”矛盾，孩子不会被乏味的盒子吸引。", "衰老": "搭配：盒子不会衰老，“衰老”只用于人或生物。", "腐烂": "语义：“腐烂”是坏的状态，与“吸引孩子”的语境相反。"}, "sentence_index": 6, "correct_answer": "神奇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条山路很神奇，开车一定要小心。", "explanation": "这里应该用〈危险〉。〈神奇〉指奇妙、令人赞叹，提醒小心时要用〈危险〉。"}, {"text": "这间屋子的面积很神奇。", "explanation": "这里应该用〈大〉。〈神奇〉指奇妙、令人赞叹，不能用来描述面积的大小。"}, {"text": "我的作业写得很神奇，老师批评了我。", "explanation": "这里应该用〈马虎〉。〈神奇〉指奇妙、令人赞叹，不能用来说被批评的作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的实验结果真神奇着。", "corrected_sentence": "这次的实验结果真神奇。", "error_description": "“神奇”作谓语时不能带“着”，“神奇着”不成立，应去掉“着”，改为“真神奇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用神奇地方法解决了问题。", "corrected_sentence": "他用神奇的方法解决了问题。", "error_description": "修饰名词“方法”要用“的”，“神奇地”是状语形式，不能直接修饰名词，应改为“神奇的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
