INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94415, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "经年是过了很多年。", "primary_collocate": null, "pronunciation": "jīng nián", "ipa": "tɕiŋ˥ niɛn˧˥", "syllable_count": 2, "sentences": [{"text": "经年未见，他的头发已经白了。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子经年失修，墙都裂了。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人经年独居，很少有人来看他。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经年不见的朋友，今天突然来电话了。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条河经年干涸，河底长满了草。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她经年在外工作，很少回家。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把旧椅子经年不用，上面全是灰。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们经年没有联系，现在见面有点陌生。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小路经年无人走，已经看不见了。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经年吃药，身体还是不太好。", "target_word": "经年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经年累月", "label": "复合"}], "register": "书面", "sense_fingerprint": "经年：表示已经过了很多年，多用于书面，常修饰未见、失修等状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9550a99-05ab-43a0-8580-e05f022f057f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经年", "is_correct": true, "explanation": "正确：“经年”表示过了很多年，与“未见”和“白了”相合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快，与“头发已经白了”所说的长时间不合。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示不久前，与“未见”所指的长时间间隔矛盾。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”后接即时动作，不能与“未见”这种长时状态搭配。"}], "explanations": {"经年": "正确：“经年”表示过了很多年，与“未见”和“白了”相合。", "马上": "语义：“马上”表示很快，与“头发已经白了”所说的长时间不合。", "刚刚": "语义：“刚刚”表示不久前，与“未见”所指的长时间间隔矛盾。", "立即": "搭配：“立即”后接即时动作，不能与“未见”这种长时状态搭配。"}, "sentence_index": 0, "correct_answer": "经年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经年就到家了。", "explanation": "这里应该用〈马上〉。“经年”指过了很多年，不能说很快就到家。"}, {"text": "我经年吃完了午饭。", "explanation": "这里应该用〈刚刚〉。“经年”指经过很多年，不能用来说刚发生的一顿饭。"}, {"text": "他经年就站起来了。", "explanation": "这里应该用〈立刻〉。“经年”指经过很多年，不能表示立刻发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经年", "is_correct": true, "explanation": "正确：“经年”表示长时间，与“不用”和“全是灰”相合。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”表示不久前，与“上面全是灰”的长期积累矛盾。"}, {"text": "一下子", "is_correct": false, "explanation": "语义：“一下子”表示突然，不能与“全是灰”的积累过程相合。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”后接即时动作，不与“不用”这种长时状态搭配。"}], "explanations": {"经年": "正确：“经年”表示长时间，与“不用”和“全是灰”相合。", "刚才": "语义：“刚才”表示不久前，与“上面全是灰”的长期积累矛盾。", "一下子": "语义：“一下子”表示突然，不能与“全是灰”的积累过程相合。", "立刻": "搭配：“立刻”后接即时动作，不与“不用”这种长时状态搭配。"}, "sentence_index": 6, "correct_answer": "经年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经年就把药吃完了。", "explanation": "这里应该用〈一会儿〉。“经年”指经过很多年，不能用于很短时间内吃完药这样的事。"}, {"text": "我们经年就到了山顶。", "explanation": "这里应该用〈片刻〉。“经年”指经过很多年，不能说片刻之间就到达。"}, {"text": "经年他就离开了房间。", "explanation": "这里应该用〈随后〉。“经年”指经过很多年，与“随后”表示紧接着的时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那辆旧自行车经年了停在院子里，轮胎都瘪了。", "corrected_sentence": "那辆旧自行车经年停在院子里，轮胎都瘪了。", "error_description": "错误：“经年”是副词，后面不能加“了”。应去掉“了”，说“经年停在院子里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑很经年放在角落里，早就不能用了。", "corrected_sentence": "这台电脑经年放在角落里，早就不能用了。", "error_description": "错误：“经年”前加了程度副词“很”。“经年”是表示时间的副词，不能与“很”连用，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea68d73a-7c32-43c2-b51d-9217e962cd45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
