INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94417, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经济安全是钱和生活有保障，不用担心。", "primary_collocate": null, "pronunciation": "jīng jì ān quán", "ipa": "tɕiŋ˥ tɕi˥˩ an˥ tɕʰyɛn˧˥", "syllable_count": 4, "sentences": [{"text": "有了这份工作，我才有了经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "furigana": "yǒu le zhè fèn gōngzuò, wǒ cái yǒu le jīngjì ānquán", "sentence_source": "generated"}, {"text": "她很在意经济安全，每月都存钱。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人最需要经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸总说，经济安全比什么都重要。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有经济安全，生活就会很累。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对年轻人来说，经济安全是第一步。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿辞职，因为想要经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济安全让我晚上睡得很好。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先攒钱，再谈经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济安全不是有很多钱，而是不用担心。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "經濟安全", "label": "繁体"}], "register": "书面", "sense_fingerprint": "个人钱和生活有保障，不用担心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "童年", "is_correct": false, "explanation": "语义：工作带不来童年，童年是人生阶段，“有了……才有了”的因果不成立。"}, {"text": "故乡", "is_correct": false, "explanation": "搭配：“有了”后接“故乡”不通，故乡不是靠工作获得的。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：工作与雷声毫无关系，句意不通。"}, {"text": "经济安全", "is_correct": true, "explanation": "正确：经济安全指钱和生活有保障，与“有了这份工作”的因果相符。"}], "explanations": {"童年": "语义：工作带不来童年，童年是人生阶段，“有了……才有了”的因果不成立。", "故乡": "搭配：“有了”后接“故乡”不通，故乡不是靠工作获得的。", "雷声": "语义：工作与雷声毫无关系，句意不通。", "经济安全": "正确：经济安全指钱和生活有保障，与“有了这份工作”的因果相符。"}, "sentence_index": 0, "correct_answer": "经济安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天给经济安全浇水。", "explanation": "这里把“经济安全”当成了可以浇水的植物，但它指钱和生活有保障的状态，不能浇水。"}, {"text": "他手里有一把经济安全。", "explanation": "这里应该用〈种〉。经济安全是抽象概念，“把”用于有柄的器具，不能用来计量它。"}, {"text": "他把经济安全存进了银行。", "explanation": "这里把“经济安全”当成了可以存进银行的钱财，但它指钱和生活有保障的状态，不能存入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：没有人因为“想要”而去要感冒，与“不愿辞职”的原因不合。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是人们想避开的东西，不是“想要”的对象。"}, {"text": "皱纹", "is_correct": false, "explanation": "体貌：皱纹是脸上的特征，不能作为“想要”的对象。"}, {"text": "经济安全", "is_correct": true, "explanation": "正确：“不愿辞职”的原因是想要经济安全，句意通顺。"}], "explanations": {"感冒": "语义：没有人因为“想要”而去要感冒，与“不愿辞职”的原因不合。", "噪音": "语义：噪音是人们想避开的东西，不是“想要”的对象。", "皱纹": "体貌：皱纹是脸上的特征，不能作为“想要”的对象。", "经济安全": "正确：“不愿辞职”的原因是想要经济安全，句意通顺。"}, "sentence_index": 6, "correct_answer": "经济安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们开始研发经济安全。", "explanation": "这里把“经济安全”当成了可以研发的产品，但它指钱和生活有保障的状态，不能研发。"}, {"text": "他按时缴纳了经济安全。", "explanation": "这里把“经济安全”当成了税费一类的款项，但它指钱和生活有保障的状态，不能缴纳。"}, {"text": "公司今年裁掉了经济安全。", "explanation": "这里把“经济安全”当成了可以裁减的人员，但它指钱和生活有保障的状态，不能裁掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很珍惜这本经济安全。", "corrected_sentence": "他很珍惜这份经济安全。", "error_description": "量词错误：“经济安全”是抽象概念，应用“份”，“本”用于书册。正确形式是“这份经济安全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家从没有着经济安全。", "corrected_sentence": "我们家从没有过经济安全。", "error_description": "“着”误作“过”：表示“从未有过”的经历体应用“过”，“没有着”不成立。正确形式是“从没有过经济安全”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
