INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或个人的经济利益、运行不受威胁的状态。", "primary_collocate": null, "pronunciation": "jīng jì ān quán", "ipa": "tɕiŋ˥ tɕi˥˩ an˥ tɕʰyɛn˧˥", "syllable_count": 4, "sentences": [{"text": "国家要保护自己的经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府十分重视国家经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "furigana": "zhèngfǔ shífēn zhòngshì guójiā jīngjì ānquán", "sentence_source": "generated"}, {"text": "外国的做法可能影响我们的经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济安全关系到每一个国家的发展。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，粮食问题也是经济安全问题。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行出了问题，会威胁国家经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想提高经济安全的水平。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济安全受到威胁，人民的生活也会变化。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司倒了，会影响整个地区的经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开会讨论如何保证经济安全。", "target_word": "经济安全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "經濟安全", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家或个人经济利益不受威胁的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：国家不会“保护”感冒，句意不通。"}, {"text": "童年", "is_correct": false, "explanation": "语义：国家不能“保护”童年，童年是个人的人生阶段。"}, {"text": "皱纹", "is_correct": false, "explanation": "体貌：皱纹是人脸上的特征，不能说国家要保护它。"}, {"text": "经济安全", "is_correct": true, "explanation": "正确：国家保护的是自己的经济安全，指经济利益和运行不受威胁。"}], "explanations": {"感冒": "语义：国家不会“保护”感冒，句意不通。", "童年": "语义：国家不能“保护”童年，童年是个人的人生阶段。", "皱纹": "体貌：皱纹是人脸上的特征，不能说国家要保护它。", "经济安全": "正确：国家保护的是自己的经济安全，指经济利益和运行不受威胁。"}, "sentence_index": 0, "correct_answer": "经济安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家要搬走经济安全。", "explanation": "这里把“经济安全”当成了可以搬走的东西，但它指国家或个人的经济利益、运行不受威胁的状态，不能搬走。"}, {"text": "国家要打击经济安全。", "explanation": "这里把“经济安全”当成了犯罪或敌人一类的对象，但它是经济利益、运行不受威胁的状态，不能打击。"}, {"text": "这个国家掌握着一把经济安全。", "explanation": "这里应该用〈种〉。经济安全是抽象概念，“把”用于有柄的器具，不能用来计量它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“提高……的水平”不能用于体重，句意不通。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：筷子是吃饭用的东西，没有“水平”可言，政府也不会提高它的水平，句意不通。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：尾巴是动物身体的一部分，不能说“提高尾巴的水平”，句意不通。"}, {"text": "经济安全", "is_correct": true, "explanation": "正确：经济安全有“水平”之说，“政府想提高经济安全的水平”通顺。"}], "explanations": {"体重": "语义：“提高……的水平”不能用于体重，句意不通。", "筷子": "语义：筷子是吃饭用的东西，没有“水平”可言，政府也不会提高它的水平，句意不通。", "尾巴": "语义：尾巴是动物身体的一部分，不能说“提高尾巴的水平”，句意不通。", "经济安全": "正确：经济安全有“水平”之说，“政府想提高经济安全的水平”通顺。"}, "sentence_index": 6, "correct_answer": "经济安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们开始研发经济安全。", "explanation": "这里把“经济安全”当成了可以研发的产品，但它指国家或个人的经济利益、运行不受威胁的状态，不能研发。"}, {"text": "他按时缴纳了经济安全。", "explanation": "这里把“经济安全”当成了税费一类的款项，但它是经济利益、运行不受威胁的状态，不能缴纳。"}, {"text": "公司今年裁掉了经济安全。", "explanation": "这里把“经济安全”当成了可以裁减的人员，但它是经济利益、运行不受威胁的状态，不能裁掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要维护国家了经济安全。", "corrected_sentence": "我们要维护国家的经济安全。", "error_description": "“的”误作“了”：定语标记应为“的”，“国家的经济安全”中“的”连接修饰语与中心语；“了”是完成体助词，不能用于定语位置。正确形式是“国家的经济安全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法会威胁过经济安全。", "corrected_sentence": "这种做法会威胁经济安全。", "error_description": "错误：“会威胁过经济安全”；正确：“会威胁经济安全”。“会”表示将来，经历体“过”表示已经有过的经历，二者不能搭配，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
