INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94419, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94419, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "罢工是大家一起不去上班，要求提高待遇。", "primary_collocate": null, "pronunciation": "bà gōng", "ipa": "pa˥˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "工人们要求加工资，所以罢工了。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交司机昨天罢工，路上车很少。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的工人为了提高待遇而罢工。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经罢工三天了。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不同意加工资，工人就罢工。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁工人罢工，我只好走路上班。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的工人去年罢工过。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家决定一起罢工，要求提高工资。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天医生们要罢工。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "罢工的工人们站在工厂门口。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "罢工了", "label": "体标（了）"}, {"form": "罢工过", "label": "体标（过）"}, {"form": "罷工", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工人集体不上班以提出要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罢工", "is_correct": true, "explanation": "罢工：工人集体停止工作以要求加薪，与“要求加工资”和“所以”的因果相合。"}, {"text": "退学", "is_correct": false, "explanation": "语义：退学指学生离开学校，工人不会因要求加工资而退学。"}, {"text": "逃课", "is_correct": false, "explanation": "搭配：“逃课”的主体是学生，不说工人逃课。"}, {"text": "放学", "is_correct": false, "explanation": "语义：放学是学生的日常活动，与工人要求加工资毫无关联。"}], "explanations": {"罢工": "罢工：工人集体停止工作以要求加薪，与“要求加工资”和“所以”的因果相合。", "退学": "语义：退学指学生离开学校，工人不会因要求加工资而退学。", "逃课": "搭配：“逃课”的主体是学生，不说工人逃课。", "放学": "语义：放学是学生的日常活动，与工人要求加工资毫无关联。"}, "sentence_index": 0, "correct_answer": "罢工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂因为停电，今天罢工了一整天。", "explanation": "这里应该用〈停工〉。罢工是工人为要求而集体拒绝上班，停电导致的停工要用〈停工〉。"}, {"text": "学生们因为作业太多，集体罢工了。", "explanation": "这里应该用〈罢课〉。罢工的主体是工人，学生集体不上课要用〈罢课〉。"}, {"text": "因为疫情，这家餐厅罢工了。", "explanation": "这里应该用〈停业〉。罢工是工人的集体行动，餐厅因疫情暂停营业要用〈停业〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罢工", "is_correct": true, "explanation": "罢工：工人集体停工提出要求，去年发生过，与“去年……过”相合。"}, {"text": "逃学", "is_correct": false, "explanation": "搭配：“逃学”的主体是学生，不能用于工厂工人。"}, {"text": "辍学", "is_correct": false, "explanation": "语义：辍学指学生中途停止上学，与工厂工人的身份不符。"}, {"text": "停课", "is_correct": false, "explanation": "搭配：“停课”针对学校的课程，不说工人停课。"}], "explanations": {"罢工": "罢工：工人集体停工提出要求，去年发生过，与“去年……过”相合。", "逃学": "搭配：“逃学”的主体是学生，不能用于工厂工人。", "辍学": "语义：辍学指学生中途停止上学，与工厂工人的身份不符。", "停课": "搭配：“停课”针对学校的课程，不说工人停课。"}, "sentence_index": 6, "correct_answer": "罢工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家剧院因为修缮罢工了一个月。", "explanation": "这里应该用〈停演〉。剧院因修缮暂停演出要用〈停演〉；罢工是工人为要求而集体停止工作。"}, {"text": "台风来了，学校罢工了一天。", "explanation": "这里应该用〈停课〉。罢工的主体是工人，学校因台风不上课要用〈停课〉。"}, {"text": "放暑假了，学校罢工了两个月。", "explanation": "这里应该用〈放假〉。学校按计划不上课要用〈放假〉；罢工是工人为提出要求而集体停止工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们因为工资太低，决定罢工老板。", "corrected_sentence": "工人们因为工资太低，决定罢工。", "error_description": "错误在“罢工”后直接加宾语“老板”。“罢工”是离合词，不能带宾语，应说“决定罢工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂去年发生了一只罢工。", "corrected_sentence": "工厂去年发生了一次罢工。", "error_description": "错误在量词。“罢工”指一次集体停工事件，应用“次”或“场”；“只”用于动物等，不能修饰“罢工”。正确说法是“一次罢工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
