INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94420, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94420, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "工人为达到要求而集体停止工作。", "primary_collocate": null, "pronunciation": "bà gōng", "ipa": "pa˥˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "工人们为了要求加工资，决定罢工。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为工资太低，工人们罢工了。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场工作人员罢工，很多飞机不能起飞。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板答应了要求，工人们就不罢工了。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为什么要罢工？", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们罢工已经一个星期了。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，司机们明天要罢工。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不涨工资，我们就罢工。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们商量好了，下周一一起罢工。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的工人在罢工，机器都停了。", "target_word": "罢工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "罢工了", "label": "体标（了）"}, {"form": "罢工过", "label": "体标（过）"}, {"form": "罷工", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工人为达到要求集体停止工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罢工", "is_correct": true, "explanation": "罢工：为达到加薪要求而集体停止工作，与“为了要求加工资”的目的相合。"}, {"text": "旷课", "is_correct": false, "explanation": "搭配：“旷课”是学生缺课，不说工人旷课。"}, {"text": "退学", "is_correct": false, "explanation": "语义：退学专指学生离开学校，与工人加工资的目的不符。"}, {"text": "放学", "is_correct": false, "explanation": "语义：放学指学校一天的课结束、学生回家，与工人为加工资而停工无关。"}], "explanations": {"罢工": "罢工：为达到加薪要求而集体停止工作，与“为了要求加工资”的目的相合。", "旷课": "搭配：“旷课”是学生缺课，不说工人旷课。", "退学": "语义：退学专指学生离开学校，与工人加工资的目的不符。", "放学": "语义：放学指学校一天的课结束、学生回家，与工人为加工资而停工无关。"}, "sentence_index": 0, "correct_answer": "罢工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座博物馆因为布展罢工了两天。", "explanation": "这里应该用〈闭馆〉。博物馆因布展暂停开放要用〈闭馆〉；罢工是工人为达到要求而集体停止工作。"}, {"text": "台风来了，学校罢工了一天。", "explanation": "这里应该用〈停课〉。罢工的主体是工人，学校因台风不上课要用〈停课〉。"}, {"text": "原料不够，这家公司罢工了一个月。", "explanation": "这里应该用〈停产〉。原料不足导致的停产要用〈停产〉；罢工是工人为达到要求而集体停工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罢工", "is_correct": true, "explanation": "罢工：司机集体停止工作，与“新闻里说明天要……”的消息相合。"}, {"text": "出院", "is_correct": false, "explanation": "语义：出院指病人离开医院，司机不适用。"}, {"text": "停课", "is_correct": false, "explanation": "搭配：“停课”是学校的停课，不说司机停课。"}, {"text": "入学", "is_correct": false, "explanation": "语义：入学指学生进入学校，与司机的身份不符。"}], "explanations": {"罢工": "罢工：司机集体停止工作，与“新闻里说明天要……”的消息相合。", "出院": "语义：出院指病人离开医院，司机不适用。", "停课": "搭配：“停课”是学校的停课，不说司机停课。", "入学": "语义：入学指学生进入学校，与司机的身份不符。"}, "sentence_index": 6, "correct_answer": "罢工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疫情期间，这家餐厅罢工了两个月。", "explanation": "这里应该用〈停业〉。罢工是工人的集体行动，餐厅因疫情暂停营业要用〈停业〉。"}, {"text": "电路坏了，这个车间罢工了一下午。", "explanation": "这里应该用〈停工〉。设备故障导致的停工要用〈停工〉，罢工是工人为要求而集体拒绝上班。"}, {"text": "这家商店因装修罢工了一周。", "explanation": "这里应该用〈歇业〉。商店因装修而暂停营业要用〈歇业〉，罢工是工人为提要求而停工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机们因为待遇太低，昨天开始罢工公司。", "corrected_sentence": "司机们因为待遇太低，昨天开始罢工。", "error_description": "错误在“罢工”后直接加宾语“公司”。“罢工”是离合词，不能带宾语，应说“开始罢工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月，这家工厂发生了一只罢工。", "corrected_sentence": "上个月，这家工厂发生了一场罢工。", "error_description": "错误在量词。“罢工”指一次集体停工事件，应用“场”或“次”；“只”用于动物等，不能修饰“罢工”。正确说法是“一场罢工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "老到是做事时间长，很有经验，做得很稳。", "primary_collocate": null, "pronunciation": "lǎo dào", "ipa": "lau̯˨˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "他做事很老到，从来不出错。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王干了三十年，处理问题十分老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老司机开车很老到，我们都很放心。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅修机器的手法非常老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厨师炒菜的火候掌握得很老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做生意很老到，一眼就看出问题。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老医生下手老到，病人一点也不怕。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手艺老到，做出来的家具又结实又好看。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民撒网的动作十分老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老木匠干活很老到，从不着急。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事年头久、经验足、手法稳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。"}, {"text": "捞到", "is_correct": false, "explanation": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。"}, {"text": "考到", "is_correct": false, "explanation": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。"}, {"text": "老套", "is_correct": false, "explanation": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d，送气与不送气），意思是陈旧、不新鲜。"}], "explanations": {"老到": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。", "捞到": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。", "考到": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。", "老套": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d，送气与不送气），意思是陈旧、不新鲜。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。做事经验足、手法稳，与后文“从来不出错”相符。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”指做事不仔细，与后文“从来不出错”矛盾。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”指做事不认真，与后文“从来不出错”矛盾。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”指做事不熟练，与“从来不出错”相矛盾。"}], "explanations": {"老到": "正确。做事经验足、手法稳，与后文“从来不出错”相符。", "粗心": "语义：“粗心”指做事不仔细，与后文“从来不出错”矛盾。", "马虎": "语义：“马虎”指做事不认真，与后文“从来不出错”矛盾。", "生疏": "语义：“生疏”指做事不熟练，与“从来不出错”相矛盾。"}, "sentence_index": 0, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新打印机很老到，买回来第二天就坏了。", "explanation": "这里应该用〈劣质〉。老到形容人做事的经验和手法，不用来形容刚买的机器；买回来就坏的应说劣质。"}, {"text": "他对这条路很老到，一出门就走错了。", "explanation": "这里应该用〈生疏〉。老到指经验足、做得稳，一出门就走错说明不熟悉，应说生疏。"}, {"text": "这把椅子很老到，靠背都裂了。", "explanation": "这里应该用〈陈旧〉。老到指做事经验足、做得稳，形容家具用旧应说陈旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。"}, {"text": "老大", "is_correct": false, "explanation": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。"}, {"text": "老调", "is_correct": false, "explanation": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。"}, {"text": "咬到", "is_correct": false, "explanation": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}], "explanations": {"老到": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。", "老大": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。", "老调": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。", "咬到": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。老医生下手熟练稳当，才会让病人一点也不怕。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：“慌张”说明下手乱，与病人“一点也不怕”的信任感矛盾。"}, {"text": "生硬", "is_correct": false, "explanation": "语义：“生硬”指动作或态度僵硬、不柔和，与病人“一点也不怕”的情形相反，句意不符。"}, {"text": "笨拙", "is_correct": false, "explanation": "语义：“笨拙”与老医生的熟练相反，病人不会因此一点也不怕。"}], "explanations": {"老到": "正确。老医生下手熟练稳当，才会让病人一点也不怕。", "慌张": "语义：“慌张”说明下手乱，与病人“一点也不怕”的信任感矛盾。", "生硬": "语义：“生硬”指动作或态度僵硬、不柔和，与病人“一点也不怕”的情形相反，句意不符。", "笨拙": "语义：“笨拙”与老医生的熟练相反，病人不会因此一点也不怕。"}, "sentence_index": 6, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚接触这台新设备，用起来很老到，连开关都找不到。", "explanation": "这里应该用〈生疏〉。老到要靠多年经验，连开关都找不到说明不熟练，应说生疏。"}, {"text": "这把新菜刀很老到，切了几下就卷了刃。", "explanation": "这里应该用〈不耐用〉。老到形容人做事的经验和手法，不用来形容新买的菜刀；切几下就卷刃的应说不耐用。"}, {"text": "这座老宅子很老到，墙上都是裂缝。", "explanation": "这里应该用〈破旧〉。老到指做事经验足、做得稳，形容房屋年头久、残旧应说破旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他修车修很老到，从来不出错。", "corrected_sentence": "他修车修得很老到，从来不出错。", "error_description": "错误在于动词后接形容词作状态补语时漏了“得”。正确说法是“修得很老到”，动词和“很老到”之间要用“得”连接，不能直接写“修很老到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个做事很老到人。", "corrected_sentence": "他是个做事很老到的人。", "error_description": "错误在于“老到”修饰“人”时漏了“的”。正确说法是“做事很老到的人”，形容词作定语后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容做事经验丰富，周到老练。", "primary_collocate": null, "pronunciation": "lǎo dào", "ipa": "lau̯˨˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "她虽然年轻，待人接物却很老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位律师在法庭上的表现十分老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他待人办事很老到，一看就是见过世面的人。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈判时他的回答很老到，对方没占到便宜。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小伙子看起来年轻，办事却老到得很。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李处理家里的矛盾很老到，两边都不得罪。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者提问很老到，一步一步问到了重点。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她招待客人的方式很老到，大家都满意。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板应付检查很老到，从没出过麻烦。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟同事相处很老到，话说得周全，从不得罪人。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "待人处事周到老练", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。"}, {"text": "捞到", "is_correct": false, "explanation": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。"}, {"text": "考到", "is_correct": false, "explanation": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。"}, {"text": "老套", "is_correct": false, "explanation": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d），意思是陈旧、不新鲜。"}], "explanations": {"老到": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。", "捞到": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。", "考到": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。", "老套": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d），意思是陈旧、不新鲜。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。“虽然…却…”后面要说出与“年轻”相反的长处，“老到”符合这一转折。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“虽然…却…”要转出与“年轻”相反的长处，“幼稚”顺着“年轻”说，没有转折。"}, {"text": "粗疏", "is_correct": false, "explanation": "语义：“粗疏”是缺点，与“却”要求的转折优点不相符，也与“待人接物”的周到相反。"}, {"text": "冒失", "is_correct": false, "explanation": "语义：“冒失”是缺点，与“却”要求的转折优点不相符。"}], "explanations": {"老到": "正确。“虽然…却…”后面要说出与“年轻”相反的长处，“老到”符合这一转折。", "幼稚": "语义：“虽然…却…”要转出与“年轻”相反的长处，“幼稚”顺着“年轻”说，没有转折。", "粗疏": "语义：“粗疏”是缺点，与“却”要求的转折优点不相符，也与“待人接物”的周到相反。", "冒失": "语义：“冒失”是缺点，与“却”要求的转折优点不相符。"}, "sentence_index": 0, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很老到，有什么想法就直说，不管别人爱不爱听。", "explanation": "这里应该用〈直爽〉。老到指待人周到、说话有分寸，有什么想法就直说的人应说直爽。"}, {"text": "他为人很老到，从不考虑别人的感受。", "explanation": "这里应该用〈自私〉。老到讲究周全、顾及各方，从不考虑别人感受的人应说自私。"}, {"text": "他穿的衣服很老到，都是十几年前的款式。", "explanation": "这里应该用〈老式〉。老到指待人周到、做事老练，形容衣服款式过时应说老式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。"}, {"text": "老大", "is_correct": false, "explanation": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。"}, {"text": "老调", "is_correct": false, "explanation": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。"}, {"text": "咬到", "is_correct": false, "explanation": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}], "explanations": {"老到": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。", "老大": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。", "老调": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。", "咬到": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。记者提问周密，才会一步一步问到重点。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：“慌张”与“一步一步”的沉稳不符。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”与“一步一步问到了重点”的周密相反。"}, {"text": "乖巧", "is_correct": false, "explanation": "搭配：“乖巧”多形容孩子的举止，不用来说记者提问。"}], "explanations": {"老到": "正确。记者提问周密，才会一步一步问到重点。", "慌张": "语义：“慌张”与“一步一步”的沉稳不符。", "草率": "语义：“草率”与“一步一步问到了重点”的周密相反。", "乖巧": "搭配：“乖巧”多形容孩子的举止，不用来说记者提问。"}, "sentence_index": 6, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚入行，应付客户很老到，结果把客户都得罪光了。", "explanation": "这里应该用〈莽撞〉。老到指待人周到、处事有分寸，把客户都得罪光的应说莽撞。"}, {"text": "他的思想很老到，什么新方法都不肯试。", "explanation": "这里应该用〈保守〉。老到指待人处事周到老练，不指思想不肯接受新事物，应说保守。"}, {"text": "他对新来的同事很老到，见了面连招呼都不打。", "explanation": "这里应该用〈冷淡〉。老到指待人周到，不用来形容对人冷淡、不愿交谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她招待客人招待很老到，大家都满意。", "corrected_sentence": "她招待客人招待得很老到，大家都满意。", "error_description": "错误在于“老到”作补语时漏了“得”。正确说法是“招待得很老到”，动词后接形容词补语时要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是个应付场面很老到人。", "corrected_sentence": "她是个应付场面很老到的人。", "error_description": "错误在于“老到”修饰“人”时漏了“的”。正确说法是“应付场面很老到的人”，形容词作定语后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
