INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94424, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "若干队伍按规定轮流比赛、决出名次的体育赛事。", "primary_collocate": null, "pronunciation": "lián sài", "ipa": "ljɛn˧˥ saɪ˥˩", "syllable_count": 2, "sentences": [{"text": "联赛按积分决定名次。", "target_word": "联赛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这支队在联赛中排第三。", "target_word": "联赛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "球队要踢完整个联赛，才知道冠军是谁。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国足球联赛的第一名是上海队。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联赛每队都要主场和客场各踢一次。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在联赛最后一轮赢了，拿到第一名。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联赛开始后，球票很快卖完了。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛不是联赛，是友谊赛。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们踢了一个赛季的联赛，累极了。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "篮球联赛的比赛时间在晚上。", "target_word": "联赛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一届联赛", "label": "量词"}, {"form": "足球联赛", "label": "复合"}, {"form": "联赛冠军", "label": "复合"}], "register": "中性", "sense_fingerprint": "按规定轮流比赛、按积分决出名次的体育赛事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e17f9927-b1fd-4582-ab98-2acb8fc73a68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是比赛，不能按积分决定名次。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“积分”与“课本”不搭配，课本不计积分。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不是比赛，不能按积分决定名次。"}, {"text": "联赛", "is_correct": true, "explanation": "正确。“联赛”是按规定轮流比赛、按积分决出名次的体育赛事。"}], "explanations": {"天气": "语义：“天气”不是比赛，不能按积分决定名次。", "课本": "搭配：“积分”与“课本”不搭配，课本不计积分。", "老师": "语义：“老师”是人，不是比赛，不能按积分决定名次。", "联赛": "正确。“联赛”是按规定轮流比赛、按积分决出名次的体育赛事。"}, "sentence_index": 0, "correct_answer": "联赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "联赛是淘汰制，输了就出局。", "explanation": "这里应该用〈杯赛〉。联赛按积分排名，不是淘汰制，“淘汰制”是杯赛的特点。"}, {"text": "联赛不计积分，只为交流。", "explanation": "这里应该用〈友谊赛〉。联赛要按积分决出名次，不会不计积分。"}, {"text": "联赛不计成绩，只为好看。", "explanation": "这里应该用〈表演赛〉。联赛要决出名次，不是只为好看的表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名次", "is_correct": false, "explanation": "语义：“名次”是比赛的结果，不是开始后能卖票的活动。"}, {"text": "课程", "is_correct": false, "explanation": "语义：“课程”是教学活动，与“球票”没有关系。"}, {"text": "饭局", "is_correct": false, "explanation": "搭配：“饭局”不会卖“球票”，球票只与比赛搭配。"}, {"text": "联赛", "is_correct": true, "explanation": "正确。“联赛”是体育赛事，开始后可以卖球票。"}], "explanations": {"名次": "语义：“名次”是比赛的结果，不是开始后能卖票的活动。", "课程": "语义：“课程”是教学活动，与“球票”没有关系。", "饭局": "搭配：“饭局”不会卖“球票”，球票只与比赛搭配。", "联赛": "正确。“联赛”是体育赛事，开始后可以卖球票。"}, "sentence_index": 6, "correct_answer": "联赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次联赛产生了新的市长。", "explanation": "这里应该用〈选举〉。联赛决出的是名次，不能产生市长，产生市长是选举的结果。"}, {"text": "联赛在台上唱歌，很好听。", "explanation": "这里应该用〈歌手〉。联赛是体育比赛，不会唱歌，“唱歌”要靠歌手。"}, {"text": "他的梦想是成为联赛。", "explanation": "这里应该用〈科学家〉。联赛是体育比赛，不是人，不能“成为”它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只联赛按积分决定名次。", "corrected_sentence": "这届联赛按积分决定名次。", "error_description": "量词错误：“联赛”应按“届”计算，“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只联赛推迟了两周。", "corrected_sentence": "这届联赛推迟了两周。", "error_description": "量词错误：“联赛”应按“届”计算，“只”用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
