INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "临是快要到了某个时间或动作的时候，表示事情即将发生。", "primary_collocate": null, "pronunciation": "lín", "ipa": "lin˧˥", "syllable_count": 1, "sentences": [{"text": "临走前，他给我打了电话。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "临睡前不要喝咖啡。", "target_word": "临", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "临出门的时候，下起了大雨。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "临考试前，她还在认真复习。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他临上车才发现没带钱包。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "临下班的时候，老板给了我一个新任务。", "target_word": "临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临开会前，我才想起要带电脑。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈临出发前检查了一下行李。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他临毕业时，找到了工作。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我总是临睡前才想起来关灯。", "target_word": "临", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "臨", "label": "繁体"}, {"form": "临近", "label": "复合"}, {"form": "临时", "label": "复合"}], "register": "中性", "sense_fingerprint": "放在动作前，表示事情快要发生的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc69421-3810-4b86-b910-85c9db54434e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案，表示快要到某个时候、事情即将发生。"}, {"text": "您", "is_correct": false, "explanation": "声母 n 与 l 不同（nín 与 lín），意思是您（敬称）。"}, {"text": "零", "is_correct": false, "explanation": "韵母 -ing 与 -in 不同，意思是零。"}, {"text": "拎", "is_correct": false, "explanation": "声调不同（līn 第一声与 lín 第二声），意思是用手提。"}], "explanations": {"临": "正确答案，表示快要到某个时候、事情即将发生。", "您": "声母 n 与 l 不同（nín 与 lín），意思是您（敬称）。", "零": "韵母 -ing 与 -in 不同，意思是零。", "拎": "声调不同（līn 第一声与 lín 第二声），意思是用手提。"}, "sentence_index": null, "correct_answer": "临"}, "level_3": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案。“临走前”表示快要走的时候，符合句意。"}, {"text": "靠", "is_correct": false, "explanation": "语义：“靠”表示靠近或依靠，不能表示事情快要发生。"}, {"text": "随", "is_correct": false, "explanation": "语义：“随”表示跟随，与快要发生的时间无关。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”指站立，不能与“走前”搭配。"}], "explanations": {"临": "正确答案。“临走前”表示快要走的时候，符合句意。", "靠": "语义：“靠”表示靠近或依靠，不能表示事情快要发生。", "随": "语义：“随”表示跟随，与快要发生的时间无关。", "站": "搭配：“站”指站立，不能与“走前”搭配。"}, "sentence_index": 0, "correct_answer": "临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他临上周才告诉我这件事。", "explanation": "这里应该用〈直到〉。“临”表示快要发生，不能指已经过去的时间，应说“直到上周”。"}, {"text": "我们临吃饭以后才想起没买菜。", "explanation": "这里应该用〈饭后〉。“临”表示快要发生，不能指已经发生的事，饭后才想起要用“饭后”。"}, {"text": "临走之后，他才想起忘了带钥匙。", "explanation": "这里应该用〈之前〉。“临”表示快要发生，不能与“之后”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案，表示快要到某个时候、事情即将发生。"}, {"text": "蓝", "is_correct": false, "explanation": "韵母 -an 与 -in 不同（lán 与 lín），意思是蓝色。"}, {"text": "凌", "is_correct": false, "explanation": "韵母 -ing 与 -in 不同，意思是凌（欺压、升高）。"}, {"text": "离", "is_correct": false, "explanation": "韵尾 n 不同（lí 与 lín），意思是离开。"}], "explanations": {"临": "正确答案，表示快要到某个时候、事情即将发生。", "蓝": "韵母 -an 与 -in 不同（lán 与 lín），意思是蓝色。", "凌": "韵母 -ing 与 -in 不同，意思是凌（欺压、升高）。", "离": "韵尾 n 不同（lí 与 lín），意思是离开。"}, "sentence_index": null, "correct_answer": "临"}, "level_3": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案。“临开会前”表示快要开会的时候，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”是进食，不能与“开会前”搭配。"}, {"text": "绕", "is_correct": false, "explanation": "搭配：“绕”表示环绕，不能用来说“开会前”。"}, {"text": "登", "is_correct": false, "explanation": "搭配：“登”表示登上或登记，不能与“开会前”搭配。"}], "explanations": {"临": "正确答案。“临开会前”表示快要开会的时候，符合句意。", "吃": "搭配：“吃”是进食，不能与“开会前”搭配。", "绕": "搭配：“绕”表示环绕，不能用来说“开会前”。", "登": "搭配：“登”表示登上或登记，不能与“开会前”搭配。"}, "sentence_index": 6, "correct_answer": "临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他临去年就离开了这座城市。", "explanation": "这里应该用〈早在〉。“临”表示快要发生，不能指已经过去的时间，应说“早在去年”。"}, {"text": "我们昨天临放学后，老师表扬了我。", "explanation": "这里应该用〈放学后〉。“临”表示快要发生，不能与“后”搭配，应说“放学后”。"}, {"text": "妈妈临下班之后，才想起要买菜。", "explanation": "这里应该用〈下班后〉。“临”表示快要发生，不能用于已经发生的事，下班以后要用“下班后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他临下班后给我发了消息。", "corrected_sentence": "他临下班前给我发了消息。", "error_description": "“临”表示快要发生，后面应接“前”，说“临下班前”。“临下班后”表示已经下班以后，与“临”的意思矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她临开会后才把报告发给我。", "corrected_sentence": "她临开会前才把报告发给我。", "error_description": "“临”表示快要发生，后面应接“前”，说“临开会前”。“临开会后”表示已经开完会以后，与“临”的意思矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caccbed0-da05-4bb5-898c-4650fd85abdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94427, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94427, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94427, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自比是把自己比成别的东西。", "primary_collocate": null, "pronunciation": "zì bǐ", "ipa": "tsɹ̩˥˩ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他自比为一棵小草，不怕风雨。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人常常自比为一只小鸟。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自比成一朵花，希望每天都开心。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师自比蜡烛，照亮学生，自己慢慢变短。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷自比为一头老牛，一辈子都在工作。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明自比为小船，说妈妈是他的海港。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在信里自比为一座山，安静地站着。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个作家自比为一面镜子。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常自比为一只鸟，想去很远的地方。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈自比为一棵大树，给孩子们遮风挡雨。", "target_word": "自比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自比：把自己比作某种东西（比喻）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94427, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自比", "is_correct": true, "explanation": "正确答案：zì bǐ（第三声）是“自比”，把自己比作某种东西。"}, {"text": "自卑", "is_correct": false, "explanation": "bēi（第一声）与 bǐ（第三声）韵母和声调都不同，意思是“自卑”，觉得自己不如别人。"}, {"text": "自闭", "is_correct": false, "explanation": "bì（第四声）与 bǐ（第三声）声调不同，意思是“自闭”，把自己封闭起来。"}, {"text": "自备", "is_correct": false, "explanation": "bèi（第四声）与 bǐ（第三声）韵母和声调都不同，意思是“自备”，即自己准备。"}], "explanations": {"自比": "正确答案：zì bǐ（第三声）是“自比”，把自己比作某种东西。", "自卑": "bēi（第一声）与 bǐ（第三声）韵母和声调都不同，意思是“自卑”，觉得自己不如别人。", "自闭": "bì（第四声）与 bǐ（第三声）声调不同，意思是“自闭”，把自己封闭起来。", "自备": "bèi（第四声）与 bǐ（第三声）韵母和声调都不同，意思是“自备”，即自己准备。"}, "sentence_index": null, "correct_answer": "自比"}, "level_3": {"options": [{"text": "自比", "is_correct": true, "explanation": "自比：把自己比作一棵小草，与“不怕风雨”的比喻义相合。"}, {"text": "自满", "is_correct": false, "explanation": "语法：自满是形容词，后面不能用“为”引出“一棵小草”这样的比作对象，与句意不合。"}, {"text": "自省", "is_correct": false, "explanation": "语法：自省是反省自己的动词，不能用“为一棵小草”表示把自己比作什么。"}, {"text": "自封", "is_correct": false, "explanation": "语义：自封是自己给自己加上头衔或名分，与“一棵小草”的意思不合。"}], "explanations": {"自比": "自比：把自己比作一棵小草，与“不怕风雨”的比喻义相合。", "自满": "语法：自满是形容词，后面不能用“为”引出“一棵小草”这样的比作对象，与句意不合。", "自省": "语法：自省是反省自己的动词，不能用“为一棵小草”表示把自己比作什么。", "自封": "语义：自封是自己给自己加上头衔或名分，与“一棵小草”的意思不合。"}, "sentence_index": 0, "correct_answer": "自比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他自比很聪明。", "explanation": "这里应该用〈自认为〉。自比要说明把自己比作什么，不能直接接“很聪明”这样的形容词。"}, {"text": "人们把老师自比作蜡烛。", "explanation": "这里应该用〈比作〉。自比只能由自己把自己比作别的东西，不能由别人来比，也不能用“把”字结构。"}, {"text": "她把书自比为一个朋友，常和它说话。", "explanation": "这里应该用〈看作〉。自比的主语只能是人，而且是把自己与别的事物相比，不能说“把书自比为朋友”；表示把书当成朋友，要用〈看作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自比", "is_correct": true, "explanation": "自比：把自己比作一座山，与“安静地站着”的比喻义相合。"}, {"text": "变为", "is_correct": false, "explanation": "语义：变为表示事物发生变化，与“在信里”和“安静地站着”的语境不合。"}, {"text": "评为", "is_correct": false, "explanation": "搭配：评为用于评定等级或称号，不能说在信里把自己评为一座山。"}, {"text": "选为", "is_correct": false, "explanation": "语义：选为指选举或选定，信里不能选出一座山，与句意不合。"}], "explanations": {"自比": "自比：把自己比作一座山，与“安静地站着”的比喻义相合。", "变为": "语义：变为表示事物发生变化，与“在信里”和“安静地站着”的语境不合。", "评为": "搭配：评为用于评定等级或称号，不能说在信里把自己评为一座山。", "选为": "语义：选为指选举或选定，信里不能选出一座山，与句意不合。"}, "sentence_index": 6, "correct_answer": "自比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子常自比大人说话。", "explanation": "这里应该用〈模仿〉。自比是拿自己与别人或事物相比，不表示学着别人的样子做事，后面不能接“说话”这样的动作。"}, {"text": "他把书自比成宝贝。", "explanation": "这里应该用〈当成〉。自比的主语只能是人，比的是自己，不能说把某物自比成另一样东西，也不用“把”字结构。"}, {"text": "他自比没听见。", "explanation": "这里应该用〈假装〉。自比不表示假装，后面不能接“没听见”这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我自比成为一只小猫，喜欢晒太阳。", "corrected_sentence": "我自比为一只小猫，喜欢晒太阳。", "error_description": "“自比”后面接“为”或“成”，不能同时用“成为”，“成为”与“自比”的比作义重复。正确说法是“自比为”或“自比成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟也自比了一条小鱼，每天都在游泳。", "corrected_sentence": "弟弟也自比为一条小鱼，每天都在游泳。", "error_description": "“也…每天都在游泳”描述的是持续、习惯性的状态，而“了”表示已完成的动作，两者矛盾；“自比”后接“为”或“成”都可以，问题在于“了”，应去掉“了”，说“也自比为一条小鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94429, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94429, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94429, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "与此同时是说在这件事发生的时候，另一件事也在发生。", "primary_collocate": null, "pronunciation": "yǔ cǐ tóng shí", "ipa": "y˨˩ tsʰɨ˨˩ tʰʊŋ˧˥ ʂɻ̩˧˥", "syllable_count": 4, "sentences": [{"text": "妈妈在厨房做饭，与此同时，爸爸在客厅看报纸。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳慢慢升起来了，与此同时，鸟儿开始唱歌。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写字，与此同时，学生在本子上做笔记。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司赚了很多钱，与此同时，工作也更忙了。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在打电话，与此同时，孩子在房间里玩游戏。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天开始下雨，与此同时，风也越来越大。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进了教室，与此同时，铃声响了。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市越来越大，与此同时，空气也变差了。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束了，与此同时，外面下起了大雨。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喝着咖啡，与此同时，朋友给我发了消息。", "target_word": "与此同时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "与此同时|连词|一件事发生时另一件事也在发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "与此同时", "is_correct": true, "explanation": "与此同时表示两件事同时进行，妈妈做饭和爸爸看报纸同时发生，符合句意。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示先后相继，而句中两件事都在进行（「在…」），不是先后发生。"}, {"text": "况且", "is_correct": false, "explanation": "语义：「况且」用于补充更进一步的理由，而句中两件事只是同时进行，没有理由关系，句意不通。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」引出原因，但做饭和看报纸之间没有因果关系，句意不通。"}], "explanations": {"与此同时": "与此同时表示两件事同时进行，妈妈做饭和爸爸看报纸同时发生，符合句意。", "然后": "语义：「然后」表示先后相继，而句中两件事都在进行（「在…」），不是先后发生。", "况且": "语义：「况且」用于补充更进一步的理由，而句中两件事只是同时进行，没有理由关系，句意不通。", "因为": "语义：「因为」引出原因，但做饭和看报纸之间没有因果关系，句意不通。"}, "sentence_index": 0, "correct_answer": "与此同时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先写完作业，与此同时去吃了饭。", "explanation": "这里是先后发生的两件事，应该用〈然后〉。「与此同时」表示两件事同时进行，不能用于先后相继的事件。"}, {"text": "吃完晚饭，与此同时我们去散步了。", "explanation": "这里是先后相继的两件事，应该用〈之后〉。「与此同时」表示两件事同时发生，不能用于先后发生的事件。"}, {"text": "他昨天生病了，与此同时今天没来上课。", "explanation": "这里前后是因果关系，应该用〈所以〉。「与此同时」只表示两件事同时发生，不能表示因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "与此同时", "is_correct": true, "explanation": "与此同时表示两件事同时出现：他走进教室，铃声也响了，符合句意。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，但铃声响起并不是因为他走进教室，句意不通。"}, {"text": "因而", "is_correct": false, "explanation": "语义：「因而」同样表示因果，铃声响起与他走进教室之间没有因果联系，句意不通。"}, {"text": "从而", "is_correct": false, "explanation": "语域：「从而」是书面语，表示由此产生的结果，口语语境中不合适，且两件事没有因果联系。"}], "explanations": {"与此同时": "与此同时表示两件事同时出现：他走进教室，铃声也响了，符合句意。", "所以": "语义：「所以」表示因果，但铃声响起并不是因为他走进教室，句意不通。", "因而": "语义：「因而」同样表示因果，铃声响起与他走进教室之间没有因果联系，句意不通。", "从而": "语域：「从而」是书面语，表示由此产生的结果，口语语境中不合适，且两件事没有因果联系。"}, "sentence_index": 6, "correct_answer": "与此同时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很想去，与此同时没有时间。", "explanation": "这里前后是转折关系，应该用〈但是〉。「与此同时」只表示两件事同时发生，不能表示转折。"}, {"text": "她和同学与此同时走进了教室。", "explanation": "这里是两人做同一件事，不是两件事同时发生，应该用〈同时〉。「与此同时」用于连接两件不同的事。"}, {"text": "你多穿点衣服，与此同时会感冒。", "explanation": "这里是条件与后果的关系，应该用〈否则〉。「与此同时」不能引出「不这样做就会……」的后果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王在写作业，与此同时的妈妈在做饭。", "corrected_sentence": "小王在写作业，与此同时，妈妈在做饭。", "error_description": "「与此同时」是连词，不能带「的」作定语。「与此同时的妈妈」说不通，应把「的」改为逗号。正确的是：小王在写作业，与此同时，妈妈在做饭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹在弹钢琴，和与此同时，哥哥在写信。", "corrected_sentence": "妹妹在弹钢琴，与此同时，哥哥在写信。", "error_description": "「与此同时」本身已是连词，前面不能再加「和」。「和」只连接名词，不能连接分句。正确的是：妹妹在弹钢琴，与此同时，哥哥在写信。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甜", "is_correct": true, "explanation": "正确：「甜」指像糖或蜜的味道，与「苦」相对。"}, {"text": "酸", "is_correct": false, "explanation": "「酸」是另一种味道，与「苦」并列，不是反义关系。"}, {"text": "辣", "is_correct": false, "explanation": "「辣」是另一种味道，与「苦」并列，不是反义关系。"}, {"text": "鲜", "is_correct": false, "explanation": "「鲜」指味道鲜美，与「苦」没有反义关系。"}], "correct_answer": "甜", "explanations": {"甜": "正确：「甜」指像糖或蜜的味道，与「苦」相对。", "酸": "「酸」是另一种味道，与「苦」并列，不是反义关系。", "辣": "「辣」是另一种味道，与「苦」并列，不是反义关系。", "鲜": "「鲜」指味道鲜美，与「苦」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甜", "is_correct": true, "explanation": "正确：「甜」指像糖或蜜的味道，与「苦」相对。"}, {"text": "淡", "is_correct": false, "explanation": "「淡」指味道轻、不浓，与「苦」没有反义关系。"}, {"text": "烫", "is_correct": false, "explanation": "「烫」指温度高，与「苦」没有反义关系。"}, {"text": "香", "is_correct": false, "explanation": "「香」指气味好，与「苦」没有反义关系。"}], "correct_answer": "甜", "explanations": {"甜": "正确：「甜」指像糖或蜜的味道，与「苦」相对。", "淡": "「淡」指味道轻、不浓，与「苦」没有反义关系。", "烫": "「烫」指温度高，与「苦」没有反义关系。", "香": "「香」指气味好，与「苦」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "苦是吃起来不甜，让人不想吃的味道。", "primary_collocate": null, "pronunciation": "kǔ", "ipa": "kʰu˨˩˦", "syllable_count": 1, "sentences": [{"text": "这杯咖啡没放糖，喝起来很苦。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药很苦，孩子不肯吃。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝了一口没放糖的茶，说太苦了。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢苦的东西，只爱吃甜的。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑巧克力不甜，吃起来有点苦。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中药又黑又苦，我每次都喝不下去。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶泡得太久，味道变苦了。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个橙子的皮很苦，不能吃。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯茶苦得他直摇头。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药太苦了，妈妈给我一块糖。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "苦味", "label": "复合"}, {"form": "苦瓜", "label": "复合"}], "register": "中性", "sense_fingerprint": "味道不甜，不好吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5fa97b1-fd90-4ed3-8e63-a2bf197b8d55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。"}, {"text": "哭", "is_correct": false, "explanation": "声调不同：「哭」读 kū（第一声），「苦」读 kǔ（第三声），意思是哭泣。"}, {"text": "库", "is_correct": false, "explanation": "声调不同：「库」读 kù（第四声），「苦」读 kǔ（第三声），意思是仓库。"}, {"text": "古", "is_correct": false, "explanation": "声母不同：「古」读 gǔ，声母是 g，「苦」的声母是 k，意思是古老。"}, {"text": "努", "is_correct": false, "explanation": "声母不同：「努」读 nǔ，声母是 n，「苦」的声母是 k，意思是努力。"}], "explanations": {"苦": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。", "哭": "声调不同：「哭」读 kū（第一声），「苦」读 kǔ（第三声），意思是哭泣。", "库": "声调不同：「库」读 kù（第四声），「苦」读 kǔ（第三声），意思是仓库。", "古": "声母不同：「古」读 gǔ，声母是 g，「苦」的声母是 k，意思是古老。", "努": "声母不同：「努」读 nǔ，声母是 n，「苦」的声母是 k，意思是努力。"}, "sentence_index": null, "correct_answer": "苦"}, "level_3": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：咖啡没放糖，喝起来「很苦」，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：咖啡「没放糖」，不可能很甜，与句中条件相矛盾。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：「咸」指盐的味道，咖啡一般不说很咸。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：「硬」形容质地，不能用来形容饮品的味道。"}], "explanations": {"苦": "正确：咖啡没放糖，喝起来「很苦」，符合句意。", "甜": "语义：咖啡「没放糖」，不可能很甜，与句中条件相矛盾。", "咸": "搭配：「咸」指盐的味道，咖啡一般不说很咸。", "硬": "搭配：「硬」形容质地，不能用来形容饮品的味道。"}, "sentence_index": 0, "correct_answer": "苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个程序很苦，运行起来总是很慢。", "explanation": "这里应该用〈慢〉。苦是味觉，程序的运行速度要说慢，不说苦。"}, {"text": "这块布摸起来很苦，穿着不舒服。", "explanation": "这里应该用〈粗糙〉。苦是味觉，布料的触感要用粗糙，不说苦。"}, {"text": "这块石头很苦，我一个人搬不动。", "explanation": "这里应该用〈重〉。苦是味觉，石头的分量要说重，不说苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。"}, {"text": "酷", "is_correct": false, "explanation": "声调不同：「酷」读 kù（第四声），「苦」读 kǔ（第三声），意思是酷炫。"}, {"text": "鼓", "is_correct": false, "explanation": "声母不同：「鼓」读 gǔ，声母是 g，「苦」的声母是 k，意思是鼓。"}, {"text": "土", "is_correct": false, "explanation": "声母不同：「土」读 tǔ，声母是 t，「苦」的声母是 k，意思是土地。"}, {"text": "五", "is_correct": false, "explanation": "声母不同：「五」读 wǔ，声母是 w，「苦」的声母是 k，意思是数字五。"}], "explanations": {"苦": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。", "酷": "声调不同：「酷」读 kù（第四声），「苦」读 kǔ（第三声），意思是酷炫。", "鼓": "声母不同：「鼓」读 gǔ，声母是 g，「苦」的声母是 k，意思是鼓。", "土": "声母不同：「土」读 tǔ，声母是 t，「苦」的声母是 k，意思是土地。", "五": "声母不同：「五」读 wǔ，声母是 w，「苦」的声母是 k，意思是数字五。"}, "sentence_index": null, "correct_answer": "苦"}, "level_3": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「变苦了」指茶泡久了味道变得发苦，符合句意。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：「亮」形容光线或颜色，不能用来形容味道。"}, {"text": "宽", "is_correct": false, "explanation": "搭配：「宽」形容空间或尺寸，不能用来形容味道。"}, {"text": "快", "is_correct": false, "explanation": "语义：「快」指速度，茶泡久了味道不会变快。"}], "explanations": {"苦": "正确：「变苦了」指茶泡久了味道变得发苦，符合句意。", "亮": "搭配：「亮」形容光线或颜色，不能用来形容味道。", "宽": "搭配：「宽」形容空间或尺寸，不能用来形容味道。", "快": "语义：「快」指速度，茶泡久了味道不会变快。"}, "sentence_index": 6, "correct_answer": "苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盒茶叶的香味很苦，我不太喜欢。", "explanation": "这里应该用〈清香〉。苦是味觉，气味不能说苦，要说清香。"}, {"text": "这幅画的颜色很苦，看着很刺眼。", "explanation": "这里应该用〈鲜艳〉。苦是味觉，颜色不能说苦，要说鲜艳。"}, {"text": "这把刀很苦，一下就把苹果切开了。", "explanation": "这里应该用〈锋利〉。苦是味觉，刀好不好切要说锋利，不说苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version =